def build_today_items(companies, certificate=None, certificates=None, runs=None, audits=None, now=None):
    """Itens do painel "Hoje" do Início, em ordem de prioridade.

    Cada item é um dict: severity ('alta' | 'atencao' | 'ok'), title, detail e action
    (chave de uma ação da interface: companies, certificate, pending, documents, sync).
    """
    now = now or datetime.now()
    items = []

    def days_left(cert):
        try:
            dt = datetime.fromisoformat(str((cert or {}).get('NotAfter', '')).replace('Z', '+00:00')).replace(tzinfo=None)
            return (dt - now).days
        except Exception:
            return None

    # Certificado digital
    if certificate:
        left = days_left(certificate)
        name = certificate.get('FriendlyName') or certificate.get('Subject') or 'Certificado selecionado'
        name = str(name).split(':')[0][:48]
        if left is not None and left <= 30:
            items.append({'severity': 'alta' if left <= 7 else 'atencao',
                          'title': f'Certificado vence em {max(left, 0)} dia(s)',
                          'detail': name, 'action': 'certificate', 'action_label': 'Ver certificados'})
    else:
        items.append({'severity': 'atencao', 'title': 'Nenhum certificado selecionado',
                      'detail': 'Escolha o certificado digital para consultar os documentos fiscais.',
                      'action': 'certificate', 'action_label': 'Escolher certificado'})
    others = [c for c in (certificates or []) if c is not certificate and (days_left(c) is not None and days_left(c) <= 30)
              and c.get('Thumbprint') != (certificate or {}).get('Thumbprint')]
    if others:
        items.append({'severity': 'atencao', 'title': f'{len(others)} outro(s) certificado(s) vencendo em até 30 dias',
                      'detail': ', '.join(str(c.get('FriendlyName') or c.get('Subject') or '').split(':')[0][:28] for c in others[:3]),
                      'action': 'certificate', 'action_label': 'Ver certificados'})

    # Empresas desatualizadas
    stale = [c for c in (companies or []) if _company_update_status(c.get('last_sync'), now) == 'Desatualizada']
    warn = [c for c in (companies or []) if _company_update_status(c.get('last_sync'), now) == 'Atenção']
    if stale:
        items.append({'severity': 'alta', 'title': f'{len(stale)} empresa(s) desatualizada(s)',
                      'detail': ', '.join(str(c.get('name') or c.get('cnpj') or '')[:26] for c in stale[:3]) + (' …' if len(stale) > 3 else ''),
                      'action': 'companies', 'action_label': 'Abrir Empresas'})
    if warn:
        items.append({'severity': 'atencao', 'title': f'{len(warn)} empresa(s) em atenção',
                      'detail': 'Última busca entre 24h e 72h.', 'action': 'companies', 'action_label': 'Abrir Empresas'})

    # Pendências (capturas com observação e auditorias com divergência)
    failed = [r for r in (runs or []) if r.get('status') in ('Concluído com observações', 'Não concluído', 'Cancelado') or r.get('error_text')]
    audit_failed = [a for a in (audits or []) if a.get('status') != 'conforme' or int(a.get('missing_count') or 0) > 0 or int(a.get('divergence_count') or 0) > 0]
    if audit_failed or failed:
        parts = []
        if audit_failed: parts.append(f'{len(audit_failed)} auditoria(s)')
        if failed: parts.append(f'{len(failed)} captura(s)')
        items.append({'severity': 'alta' if audit_failed else 'atencao', 'title': f'{len(audit_failed) + len(failed)} pendência(s) para revisar',
                      'detail': ' e '.join(parts), 'action': 'pending', 'action_label': 'Ver pendências'})

    # Última busca
    last = (runs or [None])[0]
    if last and last.get('finished_at'):
        try:
            when = datetime.fromisoformat(str(last['finished_at'])).strftime('%d/%m %H:%M')
        except Exception:
            when = str(last.get('finished_at'))[:16]
        items.append({'severity': 'ok', 'title': f'Última busca: {when}',
                      'detail': str(last.get('status') or ''), 'action': 'documents', 'action_label': 'Ver documentos'})
    if not any(i['severity'] in ('alta', 'atencao') for i in items):
        items.insert(0, {'severity': 'ok', 'title': 'Tudo em dia', 'detail': 'Nada precisa de atenção agora.',
                         'action': 'sync', 'action_label': 'Buscar XML'})
    order = {'alta': 0, 'atencao': 1, 'ok': 2}
    items.sort(key=lambda i: order[i['severity']])
    return items


_TECH_PATTERNS = [
    (re.compile(r"\[Errno 13\][^\n]*", re.I), 'sem permissão para acessar o arquivo ou a pasta'),
    (re.compile(r"\[Errno 2\][^\n]*", re.I), 'arquivo ou pasta não encontrado'),
    (re.compile(r"\[Errno 28\][^\n]*", re.I), 'o disco está cheio'),
    (re.compile(r"\[WinError \d+\][^\n]*"), 'o Windows não conseguiu concluir a operação'),
    (re.compile(r"(?:Permission|PermissionError)[^\n]*", re.I), 'sem permissão de acesso'),
    (re.compile(r"database is locked[^\n]*", re.I), 'o banco de dados está em uso; tente de novo em instantes'),
    (re.compile(r"\b(?:FileNotFoundError|IsADirectoryError)\b:?[^\n]*"), 'arquivo ou pasta não encontrado'),
    (re.compile(r"\b(?:[A-Za-z_.]*Error|[A-Za-z_.]*Exception|KeyError|StopIteration)\b:?[^\n]*"), 'ocorreu um erro interno; o detalhe foi guardado no registro de erros'),
    (re.compile(r"Traceback[^\n]*"), 'ocorreu um erro interno; o detalhe foi guardado no registro de erros'),
    (re.compile(r"'[A-Za-z]+' object has no attribute[^\n]*"), 'ocorreu um erro interno; o detalhe foi guardado no registro de erros'),
]


def friendly_message(text):
    """Troca mensagens técnicas de programação por frases claras; o texto original vai para o registro de erros."""
    original = str(text)
    out = original
    for pattern, replacement in _TECH_PATTERNS:
        out = pattern.sub(replacement, out)
    if out != original:
        try: setup_logging().warning('Mensagem técnica ocultada do usuário: %s', original[:400])
        except Exception: pass
        out = re.sub(r'(?:(?<=: )|^)(sem permissão[^.\n]*|arquivo ou pasta[^.\n]*|ocorreu um erro interno[^\n]*)(?:\s*\1)+', r'\1', out)
    return out


def _install_friendly_messageboxes():
    for name in ('showerror', 'showwarning', 'showinfo'):
        original = getattr(messagebox, name)
        if getattr(original, '_exato_friendly', False):
            continue
        def make(orig):
            def wrapper(title=None, message=None, *args, **kwargs):
                return orig(title, friendly_message(message) if message is not None else message, *args, **kwargs)
            wrapper._exato_friendly = True
            return wrapper
        setattr(messagebox, name, make(original))


_install_friendly_messageboxes()


def _attach_digit_mask(var, max_digits, groups, separators):
    """Máscara de digitação: o usuário digita só números e o programa coloca os separadores.

    groups: tamanhos dos grupos (ex.: 2,2,4 para a data); separators: caractere depois de cada grupo.
    """
    state = {'prev': var.get(), 'busy': False}
    boundaries = []
    total = 0
    for g, sep in zip(groups[:-1], separators):
        total += g; boundaries.append((total, sep))
    def render(digits, forward):
        out = ''; pos = 0
        for i, g in enumerate(groups):
            chunk = digits[pos:pos + g]
            if not chunk: break
            out += chunk; pos += g
            if i < len(groups) - 1 and (len(digits) > pos or (forward and len(digits) == pos and len(chunk) == g)):
                out += separators[i]
        return out
    def on_change(*_):
        if state['busy']:
            return
        cur = var.get(); prev = state['prev']
        digits = re.sub(r'\D', '', cur)[:max_digits]
        forward = len(cur) >= len(prev)
        out = render(digits, forward)
        if out != cur:
            state['busy'] = True
            try:
                var.set(out)
                try:
                    root = var._root; w = root.focus_get()
                    if w is not None and str(w.cget('textvariable')) == str(var): w.icursor('end')
                    # valor trocado por código (não digitado): reafirma depois para o campo mostrar o texto já formatado
                    root.after_idle(lambda o=out: var.get() == o and var.set(o))
                except Exception: pass
            finally: state['busy'] = False
        state['prev'] = out
    var.trace_add('write', on_change)
    return var


def attach_date_mask(var):
    """Campo de data: digite ddmmaaaa e o programa escreve dd/mm/aaaa."""
    return _attach_digit_mask(var, 8, (2, 2, 4), ('/', '/'))


def attach_cnpj_mask(var):
    """Campo de CNPJ: digite só os 14 números e o programa escreve 00.000.000/0000-00."""
    return _attach_digit_mask(var, 14, (2, 3, 3, 4, 2), ('.', '.', '/', '-'))


def setup_logging():
    """V148: registro de eventos e erros em %LOCALAPPDATA%\\Exato\\Central Fiscal\\Dados\\Logs\\exato.log (rotativo)."""
    global _LOGGER
    if _LOGGER is not None:
        return _LOGGER
    import logging
    from logging.handlers import RotatingFileHandler
    logger = logging.getLogger('exato')
    logger.setLevel(logging.INFO)
    logger.propagate = False
    try:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        handler = RotatingFileHandler(LOG_DIR / 'exato.log', maxBytes=1_000_000, backupCount=5, encoding='utf-8')
        handler.setFormatter(logging.Formatter('%(asctime)s [%(levelname)s] %(message)s', '%Y-%m-%d %H:%M:%S'))
    except Exception:
        handler = logging.NullHandler()
    if not any(isinstance(h, type(handler)) for h in logger.handlers):
        logger.addHandler(handler)
    _LOGGER = logger
    return logger


def log_exception(context, exc_info=None):
    """Grava a falha completa (com o trecho do código) no arquivo de registro; nunca levanta erro."""
    try:
        import traceback
        info = exc_info or sys.exc_info()
        text = ''.join(traceback.format_exception(*info)) if info and info[0] else '(sem detalhes)'
        setup_logging().error('%s\n%s', context, text.rstrip())
    except Exception:
        pass


def install_error_hooks():
    """Erros fora da interface (threads e código geral) também vão para o registro."""
    def _excepthook(exc_type, exc, tb):
        log_exception('Erro não tratado', (exc_type, exc, tb))
        sys.__excepthook__(exc_type, exc, tb)
    def _thread_hook(args):
        log_exception(f'Erro em segundo plano ({getattr(args.thread, "name", "thread")})', (args.exc_type, args.exc_value, args.exc_traceback))
    sys.excepthook = _excepthook
    threading.excepthook = _thread_hook


def _natural_number_key(value):
    """Chave de ordenação natural para números de documentos (2 antes de 10; texto depois de números)."""
    text = str(value or '').strip()
    return tuple((0, int(part), '') if part.isdigit() else (1, 0, part.casefold())
                 for part in re.split(r'(\d+)', text) if part != '')


def _audit_ui_family(value):
    v=str(value or '').strip().casefold()
    if v in ('nf-e','nfe','55'):
        return 'nfe'
    if v in ('nfc-e','nfce','65'):
        return 'nfce'
    return ''


def _audit_row_detected_family(row):
    raw=str(row.get('tipo_documento') or row.get('tipo') or '').strip()
    fam=_audit_family(raw)
    if fam in ('nfe','nfce'):
        return fam
    key=_normalize_access_key(row.get('chave') or '')
    if len(key)==44:
        model=key[20:22]
        if model=='55': return 'nfe'
        if model=='65': return 'nfce'
    raw_digits=re.sub(r'\D','',raw)
    return {'55':'nfe','65':'nfce'}.get(raw_digits,'')


def _outside_period_documents(results, date_from='', date_to=''):
    """Find unique current-run documents that fall outside the selected period.
    This intentionally inspects only the current synchronization result, not the
    full persistent archive, so the notice never invents availability from old data.
    """
    found={}
    for res in (results or {}).values():
        for doc in (res or {}).get('documents') or []:
            d=str(doc.get('data') or doc.get('issued_at') or '')[:10]
            if not d: continue
            if date_from and d >= str(date_from)[:10] and (not date_to or d <= str(date_to)[:10]):
                continue
            if date_to and d > str(date_to)[:10]:
                pass
            elif date_from and d < str(date_from)[:10]:
                pass
            else:
                continue
            key=_normalize_access_key(doc.get('chave') or '') or f"{doc.get('family','')}|{d}|{doc.get('numero') or doc.get('number') or ''}"
            found[key]=(d,doc)
    groups={}
    for _,(d,doc) in found.items():
        month=d[:7]
        groups.setdefault(month,{'count':0,'examples':[]})
        groups[month]['count']+=1
        if len(groups[month]['examples'])<2:
            groups[month]['examples'].append(str(doc.get('numero') or doc.get('number') or ''))
    return groups


def _sort_document_exports(documents):
    def key(doc):
        d=str(doc.get('data') or doc.get('issued_at') or '')[:10]
        n=str(doc.get('numero') or doc.get('number') or '').strip()
        digits=re.sub(r'\D','',n)
        try: ni=int(digits) if digits else 10**12
        except Exception: ni=10**12
        return (d or '9999-99-99', ni, n.casefold(), _normalize_access_key(doc.get('chave') or ''))
    return sorted(list(documents or []), key=key)

