def _find_newer_local_versions():
    current_match = re.search(r'_V(\d+)$', APP_DIR.name, re.I)
    current = int(current_match.group(1)) if current_match else int(re.sub(r'\D','', APP_VERSION) or 0)
    found=[]
    try:
        for child in APP_DIR.parent.iterdir():
            if not child.is_dir():
                continue
            m=re.match(r'^Exato_Central_Fiscal_V(\d+)$', child.name, re.I)
            if not m: continue
            ver=int(m.group(1))
            if ver <= current: continue
            marker=child/'VERSAO.txt'
            found.append((ver, child, marker.read_text(encoding='utf-8').strip() if marker.exists() else child.name))
    except Exception:
        pass
    return sorted(found, key=lambda x:x[0], reverse=True)


def _run_system_diagnostics(cnpj=''):
    checks=[]
    py_ok=sys.version_info >= (3,10)
    checks.append(('Python 3.10+', 'OK' if py_ok else 'Atualizar Python', py_ok))
    try:
        import reportlab  # noqa: F401
        checks.append(('Relatórios PDF', 'OK', True))
    except Exception:
        checks.append(('Relatórios PDF', 'Componente não disponível', False))
    try:
        APP_DATA_DIR.mkdir(parents=True, exist_ok=True)
        probe=APP_DATA_DIR/'.write_test'
        probe.write_text('ok',encoding='utf-8'); probe.unlink(missing_ok=True)
        checks.append(('Dados locais', 'OK', True))
    except Exception as exc:
        checks.append(('Dados locais', f'Não gravável: {exc}', False))
    try:
        init_database()
        stats=db_get_stats(re.sub(r'\D','',str(cnpj or '')) if cnpj else '')
        checks.append(('Banco fiscal', f"OK • {int(stats.get('total') or 0)} documento(s)", True))
    except Exception as exc:
        checks.append(('Banco fiscal', f'Falha: {exc}', False))
    try:
        usage=shutil.disk_usage(APP_DATA_DIR)
        free_gb=usage.free/(1024**3)
        checks.append(('Espaço livre', f'{free_gb:.1f} GB', free_gb >= 5))
    except Exception as exc:
        checks.append(('Espaço livre', f'Não foi possível verificar: {exc}', False))
    cfg=load_config()
    thumb=str(cfg.get('selected_certificate_thumbprint') or '').strip()
    checks.append(('Certificado selecionado', 'Selecionado' if thumb else 'Nenhum certificado selecionado', bool(thumb)))
    try:
        req=Request('https://www.sef.sc.gov.br', headers={'User-Agent':'ExatoCentralFiscal/1.1'})
        with urlopen(req, timeout=5) as resp:
            code=int(getattr(resp,'status',200) or 200)
        checks.append(('Conectividade SEF/SC', f'OK • HTTP {code}', True))
    except Exception as exc:
        checks.append(('Conectividade SEF/SC', f'Verificar conexão: {exc}', False))
    return checks

def _nfe_runtime_diagnostic_summary(cnpj=''):
    """Read the latest local NF-e state without issuing a new fiscal request."""
    digits=re.sub(r'\D','',str(cnpj or ''))
    try:
        cfg=load_config()
    except Exception:
        cfg={}
    sync=cfg.get('nfe_sync_control',{}) if isinstance(cfg,dict) else {}
    control=dict(sync.get(digits) or {}) if digits else {}
    last_cstat=str(control.get('last_cstat') or '').strip()
    last_reason=str(control.get('last_end_reason') or '').strip()
    last_query=str(control.get('last_query_at') or '').strip()
    cooldown_until=str(control.get('cooldown_until') or '').strip()
    diag_root=WORK_DIR/'DIAGNOSTICO_WEBSERVICE'
    latest=None
    if diag_root.exists():
        try:
            runs=[x for x in diag_root.iterdir() if x.is_dir() and (not digits or x.name.startswith(digits+'_'))]
            latest=max(runs,key=lambda x:x.stat().st_mtime) if runs else None
        except Exception:
            latest=None
    msg=nfe_cstat_user_message(last_cstat,'') if last_cstat else 'Nenhum retorno NF-e registrado nesta instalação.'
    return {
        'cnpj':digits,
        'last_cstat':last_cstat or '—',
        'last_cstat_message':msg,
        'last_reason':last_reason or '—',
        'last_query_at':last_query or '—',
        'cooldown_until':cooldown_until or '—',
        'diagnostic_path':str(latest) if latest else '—',
        'actor':str(control.get('last_actor') or '—'),
        'next_actor':str(control.get('next_actor') or '—'),
    }

def _find_previous_installation():
    """Find the richest previous Exato Central Fiscal installation beside this version.

    New ZIP versions are commonly extracted into sibling folders (V061, V062, ...).
    The application must never silently start with an empty database when an older
    validated installation already contains the company's documents/checkpoints.
    """
    m=re.search(r'_V(\d+)$', APP_DIR.name, re.I)
    current=int(m.group(1)) if m else 0
    candidates=[]
    for child in APP_DIR.parent.iterdir():
        if not child.is_dir() or child.resolve()==APP_DIR.resolve():
            continue
        mm=re.match(r'^Exato_Central_Fiscal_V(\d+)$', child.name, re.I)
        if not mm:
            continue
        ver=int(mm.group(1))
        if ver>=current:
            continue
        db=child/'central_fiscal.db'; cfg=child/'config.json'
        count=_safe_read_db_count(db)
        if db.exists() or cfg.exists():
            candidates.append((count,ver,child))
    if not candidates:
        return None
    # Prefer the installation with the richest durable index; version breaks ties.
    candidates.sort(key=lambda x:(x[0],x[1]), reverse=True)
    return candidates[0][2]


def _merge_previous_installation():
    """Merge prior local DB/config into the current version, without overwriting data.

    This is a one-time startup migration. It is deliberately conservative: current
    documents/checkpoints are retained, while missing records and higher NSUs from a
    richer previous installation are brought forward.
    """
    previous=_find_previous_installation()
    if previous is None:
        return {'migrated':False,'source':''}
    init_database()
    src_db=previous/'central_fiscal.db'
    if src_db.exists() and _safe_read_db_count(src_db)>0:
        conn=sqlite3.connect(DB_PATH, timeout=30)
        try:
            conn.execute("ATTACH DATABASE ? AS olddb", (str(src_db),))
            for table in ('companies','documents','document_sources','audit_runs','sync_runs'):
                try:
                    cols=[r[1] for r in conn.execute(f'PRAGMA table_info({table})').fetchall()]
                    oldcols=[r[1] for r in conn.execute(f'PRAGMA olddb.table_info({table})').fetchall()]
                    common=[c for c in cols if c in oldcols]
                    if not common: continue
                    colsql=','.join(common)
                    conn.execute(f'INSERT OR IGNORE INTO {table} ({colsql}) SELECT {colsql} FROM olddb.{table}')
                except Exception:
                    continue
            conn.commit()
        finally:
            try: conn.execute('DETACH DATABASE olddb')
            except Exception: pass
            conn.close()
    # Merge config conservatively, preserving current selected certificate/config values.
    try:
        current=load_config()
    except Exception:
        current={}
    try:
        older=json.loads((previous/'config.json').read_text(encoding='utf-8')) if (previous/'config.json').exists() else {}
    except Exception:
        older={}
    merged=dict(older)
    merged.update(current)
    old_states=older.get('sync_state') or {}; cur_states=current.get('sync_state') or {}
    merged_states=dict(old_states); merged_states.update(cur_states)
    for key,item in old_states.items():
        if key not in cur_states: continue
        a=cur_states.get(key) or {}; b=item or {}
        try:
            if int(str(b.get('last_saved_nsu') or 0))>int(str(a.get('last_saved_nsu') or 0)):
                merged_states[key]=dict(b, **{k:v for k,v in a.items() if k not in {'last_saved_nsu'}})
        except Exception:
            pass
    merged['sync_state']=merged_states
    if older.get('selected_certificate_thumbprint') and not current.get('selected_certificate_thumbprint'):
        merged['selected_certificate_thumbprint']=older.get('selected_certificate_thumbprint')
        merged['selected_certificate_subject']=older.get('selected_certificate_subject','')
        merged['selected_certificate_document']=older.get('selected_certificate_document','')
        merged['selected_at']=older.get('selected_at','')
    try:
        save_config(merged)
    except Exception:
        pass
    try:
        (WORK_DIR/'MIGRACAO_V068.txt').write_text(
            f'Migração automática de continuidade realizada a partir de: {previous}\n'
            f'Data/hora: {datetime.now().isoformat(timespec="seconds")}\n'
            'Os documentos e checkpoints anteriores foram preservados/mesclados.\n', encoding='utf-8')
    except Exception: pass
    return {'migrated':True,'source':str(previous)}


def load_config():
    try:
        if CONFIG_PATH.exists():
            return json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except Exception:
        pass
    return {}


def save_config(data):
    with CONFIG_LOCK:
        temp = CONFIG_PATH.with_suffix(".tmp")
        temp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        temp.replace(CONFIG_PATH)


def extract_document_id(text):
    digits = re.sub(r"\D", "", text or "")
    m = re.search(r"(\d{14})", digits)
    if m:
        cnpj = m.group(1)
        return f"{cnpj[:2]}.{cnpj[2:5]}.{cnpj[5:8]}/{cnpj[8:12]}-{cnpj[12:]}"
    m = re.search(r"(\d{11})", digits)
    if m:
        cpf = m.group(1)
        return f"{cpf[:3]}.{cpf[3:6]}.{cpf[6:9]}-{cpf[9:]}"
    return "Não identificado"


def classify_certificate(provider_name, subject, friendly_name):
    text = " ".join(filter(None, [provider_name, subject, friendly_name])).lower()
    smart_terms = [
        "smart card", "smartcard", "cartão", "card", "token", "minidriver",
        "gemalto", "safenet", "soluti smart", "serasa smart", "certisign smart",
    ]
    if any(term in text for term in smart_terms):
        return "Provável A3/token"
    if "microsoft software key storage provider" in text or "software key storage provider" in text:
        return "Provável A1"
    return "Não determinado"


def enumerate_windows_certificates():
    if os.name != "nt":
        return [], "Este teste precisa ser executado no Windows."

    ps = r'''
$ErrorActionPreference = 'Stop'
$stores = @('CurrentUser\\My','LocalMachine\\My')
$result = foreach ($store in $stores) {
    try {
        Get-ChildItem -Path ("Cert:\\" + $store) -ErrorAction Stop |
            Where-Object { $_.HasPrivateKey } |
            ForEach-Object {
                $provider = ''
                try {
                    if ($_.PrivateKey -and $_.PrivateKey.CspKeyContainerInfo) { $provider = $_.PrivateKey.CspKeyContainerInfo.ProviderName }
                } catch {}
                [PSCustomObject]@{
                    Thumbprint = $_.Thumbprint
                    Subject = $_.Subject
                    Issuer = $_.Issuer
                    FriendlyName = $_.FriendlyName
                    NotBefore = $_.NotBefore.ToString('o')
                    NotAfter = $_.NotAfter.ToString('o')
                    SerialNumber = $_.SerialNumber
                    HasPrivateKey = [bool]$_.HasPrivateKey
                    ProviderName = $provider
                    Store = $store
                }
            }
    } catch {}
}
$result | ConvertTo-Json -Compress
'''
    try:
        proc = subprocess.run(
            ["powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", ps],
            capture_output=True,
            text=True,
            timeout=15,
            encoding="utf-8",
            errors="replace",
        )
        if proc.returncode != 0:
            return [], (proc.stderr.strip() or "Falha ao consultar o repositório de certificados do Windows.")
        raw = proc.stdout.strip()
        if not raw:
            return [], "Nenhum certificado com chave privada foi encontrado nos repositórios consultados."
        data = json.loads(raw)
        if isinstance(data, dict):
            data = [data]
        clean = []
        seen = set()
        now = datetime.now()
        for item in data:
            thumb = (item.get("Thumbprint") or "").replace(" ", "").upper()
            if not thumb or thumb in seen:
                continue
            seen.add(thumb)
            try:
                not_after = datetime.fromisoformat((item.get("NotAfter") or "").replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                not_after = None
            item["Document"] = extract_document_id(" ".join([
                item.get("Subject") or "", item.get("FriendlyName") or "", item.get("Issuer") or ""
            ]))
            item["Status"] = "Válido" if (not_after is None or not_after >= now) else "Expirado"
            item["TypeGuess"] = classify_certificate(
                item.get("ProviderName", ""), item.get("Subject", ""), item.get("FriendlyName", "")
            )
            clean.append(item)
        return clean, None
    except FileNotFoundError:
        return [], "PowerShell não foi encontrado neste Windows."
    except subprocess.TimeoutExpired:
        return [], "Tempo excedido ao consultar os certificados."
    except json.JSONDecodeError:
        return [], "O Windows retornou um formato inesperado ao listar os certificados."
    except Exception as exc:
        return [], f"Não foi possível listar os certificados: {exc}"


def _clean_response_text(text):
    return (text or "").replace("\r", " ").replace("\n", " ").strip()


def _safe_filename(value):
    text = re.sub(r"[^A-Za-z0-9._-]+", "_", str(value or "")).strip("._")
    return text or "arquivo"


def _save_webservice_diagnostic(info, family, cnpj, batch, request_nsu, diagnostic_dir):
    """Persist the raw SOAP response, decompressed lot and raw child XMLs for diagnosis.

    This is intentionally outside the normal document-export path. It lets us compare
    exactly what the SEF/SC Web Service returned with the XML later written by the Central.
    """
    if not diagnostic_dir:
        return None
    try:
        root = Path(diagnostic_dir)
        root.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
        fam_dir = root / f"{int(batch):04d}_{_safe_filename(family)}_{_safe_filename(request_nsu)}_{stamp}"
        fam_dir.mkdir(parents=True, exist_ok=True)

        raw = info.get('raw') or ''
        if raw:
            (fam_dir / '01_resposta_soap_original.xml').write_bytes(
                raw.encode('utf-8', errors='replace')
            )
        lote_texto = info.get('lote_texto') or ''
        if lote_texto:
            (fam_dir / '02_lote_descompactado.xml').write_bytes(
                lote_texto.encode('utf-8', errors='replace')
            )

        docs = info.get('documents') or []
        manifest = {
            'familia': family,
            'ator': str(info.get('actor_label') or info.get('actor_code') or ''),
            'ator_codigo': str(info.get('actor_code') or ''),
            'cnpj': re.sub(r'\D', '', str(cnpj or '')),
            'lote': int(batch),
            'nsu_inicial': str(request_nsu),
            'cstat': str(info.get('cstat') or ''),
            'motivo': str(info.get('motivo') or ''),
            'ultNSU': str(info.get('ultNSU') or ''),
            'ultNSURet': str(info.get('ultNSURet') or ''),
            'qtDfeRet': str(info.get('qtDfeRet') or ''),
            'documentos_identificados': len(docs),
            'lote_bytes': int(info.get('lote_bytes') or 0),
            'tipos': list(info.get('tipos') or []),
            'arquivos': []
        }
        for idx, doc in enumerate(docs, start=1):
            xml = bytes(doc.get('xml') or b'')
            key = _safe_filename(doc.get('chave') or f"sem_chave_{idx}")
            ctag = _safe_filename(doc.get('tipo') or 'documento')
            target = fam_dir / f"03_{idx:03d}_{ctag}_{key}.xml"
            if xml:
                target.write_bytes(xml)
                manifest['arquivos'].append({
                    'arquivo': target.name,
                    'nsu': str(doc.get('nsu') or ''),
                    'chave': str(doc.get('chave') or ''),
                    'tipo': str(doc.get('tipo') or ''),
                    'bytes': len(xml)
                })

        (fam_dir / '04_manifesto.json').write_text(
            json.dumps(manifest, ensure_ascii=False, indent=2), encoding='utf-8'
        )
        return str(fam_dir)
    except Exception:
        return None



def _local_tag(elem):
    return elem.tag.rsplit('}', 1)[-1] if '}' in elem.tag else elem.tag


def _raw_document_blocks_from_lote(raw_bytes):
    """Yield raw child XML bytes from a distributed lot without re-serializing the signed XML.

    ElementTree.tostring() can rewrite namespace prefixes/namespace declarations and thereby
    invalidate the XML Digital Signature digest. This extractor keeps the original bytes from
    the SEF/SC response and only adds an XML declaration at file-export time when necessary.
    """
    import re
    if not isinstance(raw_bytes, (bytes, bytearray)):
        raw_bytes = str(raw_bytes or '').encode('utf-8')
    dist_pat = re.compile(rb'<(?:(?:[A-Za-z_][\w.-]*):)?dist(?:NFe|NFCe|CTe)SC\b[^>]*>.*?</(?:(?:[A-Za-z_][\w.-]*):)?dist(?:NFe|NFCe|CTe)SC>', re.S)
    child_pat = re.compile(rb'<(?:(?:[A-Za-z_][\w.-]*):)?(nfeProc|procEventoNFe|resNFe|resEvento|procEventoNFCe|cteProc|procEventoCTe)\b[^>]*>.*?</(?:(?:[A-Za-z_][\w.-]*):)?\1>', re.S)
    import xml.etree.ElementTree as ET
    for dist_match in dist_pat.finditer(raw_bytes):
        block = dist_match.group(0)
        try:
            item = ET.fromstring(block)
            nsu = item.attrib.get('NSU') or item.attrib.get('nsu') or ''
            chave = item.attrib.get('chAcesso') or item.attrib.get('chAcesso') or ''
        except Exception:
            # The embedded child can carry its own XML declaration. Parse only the
            # distribution header attributes in that case; raw child bytes remain untouched.
            open_tag = re.search(rb'^<(?:(?:[A-Za-z_][\w.-]*):)?dist(?:NFe|NFCe|CTe)SC\b([^>]*)>', block)
            attrs = open_tag.group(1) if open_tag else b''
            m_nsu = re.search(rb'\bNSU=[\"\']([^\"\']*)[\"\']', attrs, re.I)
            m_key = re.search(rb'\bchAcesso=[\"\']([^\"\']*)[\"\']', attrs, re.I)
            nsu = m_nsu.group(1).decode('utf-8','replace') if m_nsu else ''
            chave = m_key.group(1).decode('utf-8','replace') if m_key else ''
        for child_match in child_pat.finditer(block):
            ctag = child_match.group(1).decode('ascii', errors='replace')
            raw_child = child_match.group(0)
            yield nsu, chave, ctag, raw_child


def _ensure_xml_declaration(xml_bytes):
    """Return XML bytes unchanged, adding only a declaration when absent."""
    if not xml_bytes:
        return xml_bytes
    stripped = bytes(xml_bytes).lstrip()
    if stripped.startswith(b'<?xml'):
        return bytes(xml_bytes)
    return b'<?xml version="1.0" encoding="UTF-8"?>\n' + bytes(xml_bytes)


def _extract_access_key_from_xml(xml_bytes):
    import xml.etree.ElementTree as ET
    key=''
    try:
        root=ET.fromstring(xml_bytes)
    except Exception:
        return key
    for node in root.iter():
        tag=_local_tag(node); txt=(node.text or '').strip()
        if tag == 'chNFe' and txt:
            return txt
        if tag == 'chCTe' and txt:
            return txt
        if tag in ('infNFe','infCte'):
            ident=node.attrib.get('Id') or ''
            m=re.search(r'(\d{44})', ident)
            if m:
                key=m.group(1)
    return key


def _parse_sef_response(raw):
    import xml.etree.ElementTree as ET
    info = {
        'cstat':'não identificado','motivo':'','dh':'','ultNSU':'','maxNSU':'','ultNSURet':'',
        'qtDfeRet':'','docs':0,'schemas':[],'lote_presente':False,'lote_bytes':0,
        'lote_texto':'','lote_erro':'','tipos':[],'documents':[],'raw':raw or ''
    }
    try:
        root = ET.fromstring(raw)
    except Exception:
        return info

    lote_b64 = None
    for elem in root.iter():
        tag = _local_tag(elem)
        text = (elem.text or '').strip()
        if tag == 'cStat' and text: info['cstat'] = text
        elif tag == 'xMotivo' and text: info['motivo'] = text
        elif tag == 'dhResp' and text: info['dh'] = text
        elif tag == 'ultNSU' and text: info['ultNSU'] = text
        elif tag in ('maxNSU','maxNuNSU') and text: info['maxNSU'] = text
        elif tag in ('ultNSURet','ultNuNSURet') and text: info['ultNSURet'] = text
        elif tag in ('qtDfeRet','qtdDfeRet') and text: info['qtDfeRet'] = text
        elif tag == 'docZip' and text:
            info['docs'] += 1
            schema = elem.attrib.get('schema') or elem.attrib.get('Schema')
            if schema and schema not in info['schemas']: info['schemas'].append(schema)
        elif tag == 'loteDistComp' and text:
            lote_b64 = text

    if lote_b64:
        info['lote_presente'] = True
        try:
            compressed = base64.b64decode(lote_b64, validate=False)
            info['lote_bytes'] = len(compressed)
            decompressed = None
            errors = []
            for fn in (gzip.decompress, zlib.decompress):
                try:
                    decompressed = fn(compressed)
                    break
                except Exception as exc:
                    errors.append(str(exc))
            if decompressed is None:
                if compressed.lstrip().startswith(b'<'):
                    decompressed = compressed
                else:
                    raise ValueError('não foi possível descompactar loteDistComp')
            info['lote_texto'] = decompressed.decode('utf-8', errors='replace')
            try:
                lote_root = ET.fromstring(info['lote_texto'])
                raw_blocks = list(_raw_document_blocks_from_lote(decompressed))
                if raw_blocks:
                    for nsu, chave, ctag, xml_bytes in raw_blocks:
                        schema = ''
                        try:
                            child = ET.fromstring(xml_bytes)
                            schema = child.attrib.get('schema') or child.attrib.get('Schema') or ''
                            key = chave or _extract_access_key_from_xml(xml_bytes)
                        except Exception:
                            key = chave
                        if schema and schema not in info['schemas']:
                            info['schemas'].append(schema)
                        info['documents'].append({'nsu': nsu, 'chave': key, 'tipo': ctag, 'xml': bytes(xml_bytes)})
                        if ctag not in info['tipos']: info['tipos'].append(ctag)
                else:
                    # Fallback for unexpected lot layouts: preserve old behavior rather than
                    # dropping documents, while still using raw XML when possible.
                    for item in list(lote_root):
                        tag = _local_tag(item)
                        if tag != 'distNFeSC':
                            continue
                        nsu = item.attrib.get('NSU') or item.attrib.get('nsu') or ''
                        chave = item.attrib.get('chAcesso') or ''
                        for child in [c for c in list(item) if _local_tag(c) in ('nfeProc','procEventoNFe','resNFe','resEvento')]:
                            ctag = _local_tag(child); schema = child.attrib.get('schema') or child.attrib.get('Schema')
                            if schema and schema not in info['schemas']: info['schemas'].append(schema)
                            xml_bytes = ET.tostring(child, encoding='utf-8', xml_declaration=True)
                            info['documents'].append({'nsu': nsu, 'chave': chave or _extract_access_key_from_xml(xml_bytes), 'tipo': ctag, 'xml': xml_bytes})
                            if ctag not in info['tipos']: info['tipos'].append(ctag)
                info['docs'] = max(info['docs'], len(info['documents']))
            except Exception as exc:
                info['lote_erro'] = f'falha ao interpretar o XML interno: {exc}'
        except Exception as exc:
            info['lote_erro'] = str(exc)
    return info

def nfe_cstat_user_message(cstat, motivo=''):
    """Return a user-facing explanation without changing the protected web-service request.

    Official NF-e documentation identifies 656 as Consumo Indevido and 657 as
    "Código do Órgão diverge do órgão autorizador". cStat 657 must never be
    surfaced as an automatic one-hour block.
    """
    code=str(cstat or '').strip()
    official=str(motivo or '').strip()
    if code=='656':
        return 'Rejeição cStat 656 — Consumo Indevido. Aguarde 1 hora antes de uma nova consulta quando a regra de uso indevido se aplicar.'
    if code=='657':
        return 'Rejeição cStat 657 — Código do Órgão diverge do órgão autorizador. Verifique o órgão/UF do serviço consultado antes de repetir a requisição.'
    if official:
        return f'cStat {code or "não identificado"} — {official}'
    return f'cStat {code or "não identificado"}.'


def nfe_normalize_service_result(result, info=None):
    """Normalize user-facing NF-e status while preserving the validated request layer."""
    info=info or {}
    cstat=str(info.get('cstat') or '').strip()
    if cstat!='657':
        return str(result or '')
    lines=[line for line in str(result or '').splitlines()
           if 'consumo indevido' not in line.casefold()
           and 'bloquead' not in line.casefold()]
    official=nfe_cstat_user_message(cstat,info.get('motivo'))
    # Keep all existing technical diagnostics, but insert the corrected interpretation once.
    if official not in lines:
        insert_at=2 if len(lines)>=2 else len(lines)
        lines.insert(insert_at,official)
    return '\n'.join(lines).strip()


def test_sef_nfe_webservice(cert_thumbprint, consulta_cnpj, homologacao=False, ind_xml=0, ult_nsu='0', ind_ator=3):
    thumb = re.sub(r'\s+', '', cert_thumbprint or '').upper()
    cnpj = re.sub(r'\D', '', consulta_cnpj or '')
    if not thumb: return False, 'Certificado não informado.'
    if len(cnpj) != 14: return False, 'Informe um CNPJ válido com 14 dígitos.'
    if int(ind_ator) not in (1,2,3,9): return False, 'Indicador de participação inválido para NF-e.'
    try: ult_nsu = str(int(str(ult_nsu or '0').strip()))
    except Exception: return False, 'O NSU informado é inválido.'

    if homologacao:
        url = 'https://hom.satnfe.sef.sc.gov.br/ws/distribuicao/nfedownload.asmx'
        soap_ns = 'http://www.satnfe.sef.sc.gov.br/ws/distribuicao-v1'
        action = soap_ns + '/NfeDownloadContab'; version='1.0'; amb='2'
    else:
        url = 'https://satnfe.sef.sc.gov.br/ws/distribuicao/nfedownloadV2.asmx'
        soap_ns = 'http://www.satnfe.sef.sc.gov.br/ws/distribuicao-v2'
        action = soap_ns + '/NfeDownloadContab'; version='2.00'; amb='1'

    ver_aplic='ExatoCF025'
    body = f'''<?xml version="1.0" encoding="utf-8"?>
<soap12:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap12="http://www.w3.org/2003/05/soap-envelope">
  <soap12:Body>
    <NfeDownloadContab xmlns="{soap_ns}">
      <pXml>
        <distNFeSC versao="{version}" xmlns="{soap_ns}">
          <tpAmb>{amb}</tpAmb><verAplic>{ver_aplic}</verAplic><cUF>42</cUF><CNPJ>{cnpj}</CNPJ>
          <solRel><indXML>{int(ind_xml)}</indXML><indAtor>{int(ind_ator)}</indAtor><ultNuNSU>{ult_nsu}</ultNuNSU></solRel>
        </distNFeSC>
      </pXml>
    </NfeDownloadContab>
  </soap12:Body>
</soap12:Envelope>'''

    ps = r'''param([string]$Thumbprint,[string]$Url,[string]$SoapAction,[string]$BodyBase64)
$ErrorActionPreference='Stop'
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
$cert=$null
foreach($path in @("Cert:\CurrentUser\My\$Thumbprint","Cert:\LocalMachine\My\$Thumbprint")) { try { $candidate=Get-Item -Path $path -ErrorAction Stop; if($candidate.HasPrivateKey){$cert=$candidate;break} } catch {} }
if(-not $cert){throw 'Certificado com chave privada não localizado no repositório do Windows.'}
$body=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($BodyBase64))
$request=[System.Net.HttpWebRequest]::Create($Url); $request.Method='POST'
$request.ContentType='application/soap+xml; charset=utf-8; action="'+$SoapAction+'"'; $request.Accept='application/soap+xml, text/xml'
$request.UserAgent='ExatoCentralFiscal/0.1'; $request.ClientCertificates.Add($cert)|Out-Null
$bytes=[Text.Encoding]::UTF8.GetBytes($body); $request.ContentLength=$bytes.Length
$stream=$request.GetRequestStream();$stream.Write($bytes,0,$bytes.Length);$stream.Close()
try {$response=[Net.HttpWebResponse]$request.GetResponse();$reader=New-Object IO.StreamReader($response.GetResponseStream(),[Text.Encoding]::UTF8);$content=$reader.ReadToEnd();$reader.Close();$response.Close();Write-Output $content}
catch [Net.WebException] {$resp=$_.Exception.Response;if($resp){$reader=New-Object IO.StreamReader($resp.GetResponseStream(),[Text.Encoding]::UTF8);$content=$reader.ReadToEnd();$reader.Close();$resp.Close();Write-Output $content}else{throw}}'''
    ps_b64=base64.b64encode(ps.encode('utf-8')).decode('ascii'); body_b64=base64.b64encode(body.encode('utf-8')).decode('ascii')
    command=("$s=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('"+ps_b64+"'));$sb=[ScriptBlock]::Create($s);& $sb "+f"-Thumbprint '{thumb}' -Url '{url}' -SoapAction '{action}' -BodyBase64 '{body_b64}'")
    try:
        proc=subprocess.run(['powershell.exe','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command',command],capture_output=True,text=True,timeout=60,encoding='utf-8',errors='replace')
    except FileNotFoundError: return False,'PowerShell não foi encontrado.'
    except subprocess.TimeoutExpired: return False,'A comunicação com a SEF/SC excedeu 60 segundos.'
    raw=(proc.stdout or '').strip(); err=(proc.stderr or '').strip()
    if not raw: return False,_clean_response_text(err) or 'Nenhuma resposta foi recebida da SEF/SC.'
    info=_parse_sef_response(raw)
    summary=[f"Resposta recebida da SEF/SC",f"cStat: {info['cstat']}"]
    if info['motivo']: summary.append(f"Motivo: {info['motivo']}")
    if info['dh']: summary.append(f"Data/hora: {info['dh']}")
    if info['ultNSU']: summary.append(f"ultNSU: {info['ultNSU']}")
    if info['maxNSU']: summary.append(f"maxNSU: {info['maxNSU']}")
    if info['ultNSURet']: summary.append(f"ultNSURet: {info['ultNSURet']}")
    if info['qtDfeRet']: summary.append(f"qtDfeRet informado pela SEF/SC: {info['qtDfeRet']}")
    summary.append(f"Documentos identificados: {info['docs']}")
    summary.append(f"Lote compactado retornado: {'SIM' if info['lote_presente'] else 'NÃO'}")
    if info['lote_bytes']: summary.append(f"Tamanho do lote compactado: {info['lote_bytes']} bytes")
    if info['tipos']: summary.append('Tipos identificados: '+', '.join(info['tipos']))
    if info['schemas']: summary.append('Schemas: '+', '.join(info['schemas'][:8]))
    if info['lote_erro']: summary.append('Aviso ao abrir o lote: '+info['lote_erro'])
    actor_label={1:'Emitente',2:'Destinatário',3:'Emitente ou destinatário',9:'Emitente e destinatário'}.get(int(ind_ator),str(ind_ator))
    summary.append('Filtro NF-e utilizado: '+actor_label+'.')
    summary.append('O certificado selecionado foi utilizado na autenticação TLS mútua.')
    if info['cstat'] == '657':
        summary.append('A SEF/SC recusou esta consulta por consumo indevido (cStat 657). A captura será marcada como não concluída para evitar apresentar NF-e como concluída sem documentos.')
    ok=info['cstat'] not in {'9999','215','280','657'}
    return ok, '\n'.join(summary), info



def _parse_sef_response_flexible(raw, family='nfe'):
    import xml.etree.ElementTree as ET
    info={'cstat':'não identificado','motivo':'','dh':'','ultNSU':'','maxNSU':'','ultNSURet':'','qtDfeRet':'','docs':0,'schemas':[],'lote_presente':False,'lote_bytes':0,'lote_texto':'','lote_erro':'','tipos':[],'documents':[],'raw':raw or '', 'family':family}
    try: root=ET.fromstring(raw)
    except Exception: return info
    lote_b64=None
    for elem in root.iter():
        tag=_local_tag(elem); text=(elem.text or '').strip()
        if tag=='cStat' and text: info['cstat']=text
        elif tag=='xMotivo' and text: info['motivo']=text
        elif tag=='dhResp' and text: info['dh']=text
        elif tag in ('ultNSU','ultNuNSU') and text: info['ultNSU']=text
        elif tag in ('maxNSU','maxNuNSU') and text: info['maxNSU']=text
        elif tag in ('ultNSURet','ultNuNSURet') and text: info['ultNSURet']=text
        elif tag in ('qtDfeRet','qtdDfeRet') and text: info['qtDfeRet']=text
        elif tag=='loteDistComp' and text: lote_b64=text
    if not lote_b64: return info
    info['lote_presente']=True
    try:
        compressed=base64.b64decode(lote_b64,validate=False); info['lote_bytes']=len(compressed)
        decompressed=None
        for fn in (gzip.decompress,zlib.decompress):
            try: decompressed=fn(compressed); break
            except Exception: pass
        if decompressed is None:
            if compressed.lstrip().startswith(b'<'): decompressed=compressed
            else: raise ValueError('não foi possível descompactar o lote')
        info['lote_texto']=decompressed.decode('utf-8',errors='replace')
        lote_root=ET.fromstring(info['lote_texto'])
        for item in lote_root.iter():
            if _local_tag(item) not in ('distNFeSC','distNFCeSC','distCTeSC'): continue
            nsu=item.attrib.get('NSU') or item.attrib.get('nsu') or ''
            chave=item.attrib.get('chAcesso') or ''
            raw_blocks = list(_raw_document_blocks_from_lote(decompressed))
            if raw_blocks:
                for nsu2, chave2, ctag, xml_bytes in raw_blocks:
                    if nsu2 != nsu:
                        continue
                    schema=''
                    try:
                        child=ET.fromstring(xml_bytes)
                        schema=child.attrib.get('schema') or child.attrib.get('Schema') or ''
                    except Exception:
                        pass
                    if schema and schema not in info['schemas']: info['schemas'].append(schema)
                    key=chave2 or _extract_access_key_from_xml(xml_bytes)
                    info['documents'].append({'nsu':nsu2 or nsu,'chave':key,'tipo':ctag,'xml':bytes(xml_bytes),'family':family})
                    if ctag not in info['tipos']: info['tipos'].append(ctag)
            else:
                children=[c for c in list(item) if _local_tag(c) in ('nfeProc','procEventoNFe','resNFe','resEvento','procEventoNFCe','cteProc','procEventoCTe')]
                for child in children:
                    ctag=_local_tag(child); schema=child.attrib.get('schema') or child.attrib.get('Schema')
                    if schema and schema not in info['schemas']: info['schemas'].append(schema)
                    xml_bytes=ET.tostring(child,encoding='utf-8',xml_declaration=True)
                    key=chave or _extract_access_key_from_xml(xml_bytes)
                    info['documents'].append({'nsu':nsu,'chave':key,'tipo':ctag,'xml':xml_bytes,'family':family})
                    if ctag not in info['tipos']: info['tipos'].append(ctag)
        info['docs']=len(info['documents'])
    except Exception as exc:
        info['lote_erro']=f'falha ao interpretar o lote: {exc}'
    return info


def test_sef_nfce_webservice(cert_thumbprint, consulta_cnpj, ind_xml=1, ind_ator=3, ult_nsu='0'):
    thumb=re.sub(r'\s+','',cert_thumbprint or '').upper(); cnpj=re.sub(r'\D','',consulta_cnpj or '')
    if not thumb: return False,'Certificado não informado.',{}
    if len(cnpj)!=14: return False,'Informe um CNPJ válido com 14 dígitos.',{}
    try: ult_nsu=str(int(str(ult_nsu or '0').strip()))
    except Exception: return False,'O NSU informado é inválido.',{}
    url='https://dfe.sat.sef.sc.gov.br/nfce/ws/distribuicao/DistribuicaoNfceDownload.asmx'
    soap_ns='http://www.satnfce.sef.sc.gov.br/ws/distribuicao-v1'
    action=soap_ns+'/nfceDownloadContab'
    body=f'''<?xml version="1.0" encoding="utf-8"?>
<soap12:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap12="http://www.w3.org/2003/05/soap-envelope">
  <soap12:Body>
    <nfceDownloadContab xmlns="{soap_ns}">
      <distNFCeSC versao="1.00" xmlns="{soap_ns}">
        <tpAmb>1</tpAmb><verAplic>ExatoCF025</verAplic><cUF>42</cUF><CNPJ>{cnpj}</CNPJ>
        <solRel><indXML>{int(ind_xml)}</indXML><indAtor>{int(ind_ator)}</indAtor><ultNuNSU>{ult_nsu}</ultNuNSU></solRel>
      </distNFCeSC>
    </nfceDownloadContab>
  </soap12:Body>
</soap12:Envelope>'''
    ps=r'''param([string]$Thumbprint,[string]$Url,[string]$SoapAction,[string]$BodyBase64)
$ErrorActionPreference='Stop'
[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
$cert=$null
foreach($path in @("Cert:\CurrentUser\My\$Thumbprint","Cert:\LocalMachine\My\$Thumbprint")){try{$candidate=Get-Item -Path $path -ErrorAction Stop;if($candidate.HasPrivateKey){$cert=$candidate;break}}catch{}}
if(-not $cert){throw 'Certificado com chave privada não localizado no repositório do Windows.'}
$body=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($BodyBase64))
$request=[System.Net.HttpWebRequest]::Create($Url);$request.Method='POST'
$request.ContentType='application/soap+xml; charset=utf-8; action="'+$SoapAction+'"';$request.Accept='application/soap+xml, text/xml'
$request.UserAgent='ExatoCentralFiscal/0.12';$request.ClientCertificates.Add($cert)|Out-Null
$bytes=[Text.Encoding]::UTF8.GetBytes($body);$request.ContentLength=$bytes.Length
$stream=$request.GetRequestStream();$stream.Write($bytes,0,$bytes.Length);$stream.Close()
try{$response=[Net.HttpWebResponse]$request.GetResponse();$reader=New-Object IO.StreamReader($response.GetResponseStream(),[Text.Encoding]::UTF8);$content=$reader.ReadToEnd();$reader.Close();$response.Close();Write-Output $content}
catch [Net.WebException] {$resp=$_.Exception.Response;if($resp){$reader=New-Object IO.StreamReader($resp.GetResponseStream(),[Text.Encoding]::UTF8);$content=$reader.ReadToEnd();$reader.Close();$resp.Close();Write-Output $content}else{throw}}'''
    ps_b64=base64.b64encode(ps.encode('utf-8')).decode('ascii'); body_b64=base64.b64encode(body.encode('utf-8')).decode('ascii')
    command=("$s=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('"+ps_b64+"'));$sb=[ScriptBlock]::Create($s);& $sb "+f"-Thumbprint '{thumb}' -Url '{url}' -SoapAction '{action}' -BodyBase64 '{body_b64}'")
    try: proc=subprocess.run(['powershell.exe','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-Command',command],capture_output=True,text=True,timeout=60,encoding='utf-8',errors='replace')
    except FileNotFoundError: return False,'PowerShell não foi encontrado.',{}
    except subprocess.TimeoutExpired: return False,'A comunicação com a SEF/SC excedeu 60 segundos.',{}
    raw=(proc.stdout or '').strip(); err=(proc.stderr or '').strip()
    if not raw: return False,_clean_response_text(err) or 'Nenhuma resposta foi recebida da SEF/SC.',{}
    info=_parse_sef_response_flexible(raw,'nfce')
    summary=['Resposta recebida da SEF/SC (NFC-e)',f"cStat: {info['cstat']}"]
    if info['motivo']: summary.append(f"Motivo: {info['motivo']}")
    if info['dh']: summary.append(f"Data/hora: {info['dh']}")
    if info['ultNSURet']: summary.append(f"ultNSURet: {info['ultNSURet']}")
    if info['qtDfeRet']: summary.append(f"qtDfeRet: {info['qtDfeRet']}")
    summary.append(f"Documentos identificados: {info['docs']}")
    summary.append(f"Lote compactado retornado: {'SIM' if info['lote_presente'] else 'NÃO'}")
    if info['tipos']: summary.append('Tipos: '+', '.join(info['tipos']))
    if info['lote_erro']: summary.append('Aviso: '+info['lote_erro'])
    summary.append('O certificado selecionado foi utilizado na autenticação TLS mútua.')
    ok=info['cstat'] not in {'9999','215','280'}
    return ok,'\n'.join(summary),info




def test_sef_cte_webservice(cert_thumbprint, consulta_cnpj, ind_xml=1, ind_ator=3, ult_nsu='0'):
    """Consulta o Web Service oficial de distribuição de CT-e/CT-eOS da SEF/SC."""
    thumb=re.sub(r'\s+','',cert_thumbprint or '').upper(); cnpj=re.sub(r'\D','',consulta_cnpj or '')
