    doc_pdf=SimpleDocTemplate(str(out),pagesize=A4,leftMargin=10*mm,rightMargin=10*mm,topMargin=30.5*mm,bottomMargin=22.0*mm,title='Relatório de Documentos Fiscais — Exato Central Fiscal')
    story=[]

    # ---------- PAGE 1: EXECUTIVE DASHBOARD ----------
    # The approved first-page reference is intentionally reproduced as a compact
    # executive dashboard: identity → KPIs → movement + Exato IA → audit →
    # principal documents + attention/actions.
    regime='Não informado'
    meta=Table([[Paragraph('EMPRESA',label),Paragraph('CNPJ',label),Paragraph('REGIME TRIBUTÁRIO',label)],
                [Paragraph(esc(company_name),value),Paragraph(_format_cnpj(consulta_cnpj),value),Paragraph(regime,value)]],colWidths=[82*mm,50*mm,48*mm])
    meta.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),WHITE),('BOX',(0,0),(-1,-1),0.5,colors.HexColor(BORDER)),('INNERGRID',(0,0),(-1,-1),0.35,colors.HexColor('#E7EEF5')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
    story += [meta,Spacer(1,2.5*mm)]

    def card(lbl,val,note,accent):
        display = money(val) if isinstance(val,(Decimal,int,float)) and not (lbl.lower().startswith('total de') and isinstance(val,int)) else str(val)
        t=Table([[Paragraph(lbl.upper(),label)],[Paragraph(display,card_value)],[Paragraph(note,small)]],colWidths=[43*mm])
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),WHITE),('BOX',(0,0),(-1,-1),0.5,colors.HexColor(BORDER)),('LINEBEFORE',(0,0),(0,-1),2.6,colors.HexColor(accent)),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
        return t

    k=Table([[card('Entradas',entry_authorized,f'{len(entries)} documento(s) • {entry_pct.quantize(Decimal("0.1"))}% do total',GREEN),
              card('Saídas',output_authorized,f'{len(outputs)} documento(s) • {output_pct.quantize(Decimal("0.1"))}% do total',RED),
              card('Total de documentos',str(len(rows)),f'{len(entries)} entradas / {len(outputs)} saídas',NAVY),
              card('Diferença',diff,'Saídas acima das entradas' if output_authorized>entry_authorized else 'Entradas acima das saídas' if entry_authorized>output_authorized else 'Movimentação equilibrada',BLUE)]],colWidths=[47.5*mm]*4)
    k.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),2)]))
