    ai_panel.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#FDF1F2')),('BOX',(0,0),(-1,-1),0.6,colors.HexColor(RED)),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),0),('TOPPADDING',(0,0),(-1,-1),0),('BOTTOMPADDING',(0,0),(-1,-1),0),('BACKGROUND',(0,1),(0,1),colors.HexColor(RED)),('TEXTCOLOR',(0,1),(0,1),WHITE),('SPAN',(1,1),(1,1))]))
