    def _set_window_identity(self):
        try:
            if APP_ICON_PATH.exists():
                try: self.iconbitmap(str(APP_ICON_PATH))
                except Exception: pass
                try:
                    from PIL import Image,ImageTk
                    im=Image.open(APP_ICON_PATH).convert('RGBA').resize((32,32),Image.Resampling.LANCZOS); self._window_icon_img=ImageTk.PhotoImage(im); self.iconphoto(True,self._window_icon_img)
                except Exception: pass
            elif LOGO_MARK_PATH.exists():
                self._window_icon_img=tk.PhotoImage(file=str(LOGO_MARK_PATH)); self.iconphoto(True,self._window_icon_img)
        except Exception:
            pass

    def _initial_geometry(self):
        try:
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
            # Prefer a notebook-safe working area while still using most of the screen.
            # This avoids screens/buttons being pushed below the fold on 1366x768 / 1366x800 displays.
            w = min(max(int(sw * 0.88), 900), 1240)
            h = min(max(int(sh * 0.86), 540), 760)
            x = max((sw - w) // 2, 0)
            y = max((sh - h) // 2, 0)
            return f"{w}x{h}+{x}+{y}"
        except Exception:
            return "1100x650"

    def _configure_styles(self):
        style = ttk.Style(self)
        try:
            style.theme_use("clam")
        except Exception:
            pass
        row_h = 38 if getattr(self, 'compact_ui', True) else 42
        head_pad = (12,9)
        style.configure("Treeview", background=WHITE, fieldbackground=WHITE,
                        foreground=TEXT, rowheight=row_h, borderwidth=0, relief="flat",
                        font=("Segoe UI", 9))
        style.layout("Treeview", [("Treeview.treearea", {"sticky": "nswe"})])
        style.configure("Treeview.Heading", background="#F8FAFC", foreground=MUTED,
                        font=("Segoe UI Semibold", 8), relief="flat", borderwidth=0, padding=head_pad)
        style.map("Treeview.Heading", background=[("active", "#F1F5F9")])
