    def _header_button(self, parent, icon_name, command, tip=''):
        """Botão de ícone do topo (ajuda, tema, sair): ícone de traço, fundo suave ao passar o mouse."""
        lab=tk.Label(parent,image=exato_ui.icon(icon_name,18,'#64748B'),bg=HEADER_BG,cursor='hand2',padx=8,pady=7,bd=0)
        lab.image=lab.cget('image')
        lab.bind('<Button-1>',lambda e:command(),add='+')
        lab.bind('<Enter>',lambda e:lab.config(bg='#EEF2F7',image=exato_ui.icon(icon_name,18,'#0F172A')),add='+')
        lab.bind('<Leave>',lambda e:lab.config(bg=HEADER_BG,image=exato_ui.icon(icon_name,18,'#64748B')),add='+')
        return lab

    def destroy(self):
        """V157: cancela todos os temporizadores antes de fechar (senão, ao reabrir a tela principal, eles disparam em comandos que já não existem)."""
        try:
            for aid in self.tk.splitlist(self.tk.call('after', 'info')):
                try: self.tk.call('after', 'cancel', aid)      # só o agendamento; os comandos Python são apagados pelo próprio destroy
                except Exception: pass
        except Exception:
            pass
        super().destroy()

    def _toggle_theme(self):
        """Troca entre tema claro e escuro: grava a escolha e reabre a tela principal (sem pedir a senha de novo)."""
        new='escuro' if not exato_ui.is_dark() else 'claro'
        self.config_data['tema']=new
        try: save_config(self.config_data)
        except Exception: pass
        self._theme_restart_requested=True
        self.destroy()

    def _tree_pill_mode(self, tree, heading, width, hide_columns):
        """V158: a primeira coluna (#0) do Treeview mostra a situação em etiquetas coloridas (pílulas); as colunas de texto equivalentes continuam
        guardando os valores (testes, exportação), só deixam de aparecer."""
        tree.configure(show=('tree', 'headings'))
        tree.heading('#0', text=heading, anchor='w'); tree.column('#0', width=width, minwidth=width, stretch=False, anchor='w')
        cols = [c for c in tree['columns'] if c not in hide_columns]
        tree.configure(displaycolumns=cols)
        tree._pill_images = {}

    def _tree_pill_insert(self, tree, iid, pills, values, tags=()):
        img = exato_ui.pill_row(pills)
        tree._pill_images[iid] = img
        tree.insert('', 'end', iid=iid, image=img, values=values, tags=tags)

    @staticmethod
    def _doc_pills(status, exported):
        status = str(status or '')
        if status == 'Cancelado': return [('Cancelado · já exportado', 'danger')] if exported else [('Cancelado', 'danger'), ('Não exportado', 'muted')]
        first = ('Autorizado', 'ok') if status == 'Autorizado' else (('Evento', 'muted') if status == 'Evento' else (status or '—', 'warn'))
        return [first, ('Exportado', 'info') if exported else ('Não exportado', 'muted')]

    def _tree_hover_refresh(self, widget):
        pass

    def _install_tree_hover(self):
        """V157: a linha sob o mouse fica com fundo suave (só em linhas sem cor própria)."""
        if getattr(self, '_tree_hover_installed', False): return
        self._tree_hover_installed = True
        state = {'tree': None, 'iid': None}
        def clear():
            t, i = state['tree'], state['iid']
            if t is not None and i:
                try:
                    tags = [x for x in t.item(i, 'tags') if x != 'hover']; t.item(i, tags=tuple(tags))
                except Exception: pass
            state['tree'] = state['iid'] = None
        def move(e):
            t = e.widget
            try: iid = t.identify_row(e.y)
            except Exception: return
            if t is state['tree'] and iid == state['iid']: return
            clear()
            if not iid: return
            try:
                tags = t.item(iid, 'tags')
                if tags: return
                t.tag_configure('hover', background='#F4F7FB'); t.item(iid, tags=('hover',)); state['tree'], state['iid'] = t, iid
            except Exception: pass
        self.bind_class('Treeview', '<Motion>', move, add='+'); self.bind_class('Treeview', '<Leave>', lambda e: clear(), add='+')
        def refresh(widget):
            """V159: depois de rolar com a roda, a linha sob o mouse muda sem o mouse se mover."""
            if widget.winfo_class() != 'Treeview': return
            def later():
                try:
                    x = widget.winfo_pointerx() - widget.winfo_rootx(); y = widget.winfo_pointery() - widget.winfo_rooty()
                    class E: pass
                    ev = E(); ev.widget = widget; ev.x = x; ev.y = y
                    if 0 <= x < widget.winfo_width() and 0 <= y < widget.winfo_height(): move(ev)
                except Exception: pass
            self.after_idle(later)
        self._tree_hover_refresh = refresh

