    @staticmethod
    def _logo_without_dark_box(im):
        # V146: o PNG oficial tem fundo cinza-escuro opaco; em tempo de execução ele vira transparente
        # para se fundir à barra lateral. O arquivo em assets/ não é alterado.
        from PIL import Image
        px=im.load(); w,h=im.size
        for y in range(h):
            for x in range(w):
                r,g,b,a=px[x,y]
                m=max(r,g,b)
                if m<=34: px[x,y]=(r,g,b,0)
                elif m<=70: px[x,y]=(r,g,b,int(a*(m-34)/36))
        return im

