        self._ia_live_render_job = None
        self._ia_live_prev_render_signature = None
        self._ia_live_pose_state = 'repouso'
        self._ia_live_base_pose = 'repouso'
        self._ia_live_breath_offset = self._ia_live_rng.uniform(0.0, math.tau)

        # ---- Camada de comportamento -------------------------------------
        # O personagem passa a distinguir percepção, estado e reação.  A
        # camada é deliberadamente independente dos núcleos fiscais.
        self._ia_behavior_state = 'IDLE'
