    @staticmethod
    def _ia_live_white_eye_mask(img, box):
        """Extrai somente o traço branco do olho, preservando transparência e brilho."""
        from PIL import Image
        x0,y0,x1,y1=box
        crop=img.crop(box).convert('RGBA')
        px=crop.load()
        alpha=Image.new('L', crop.size, 0)
        ap=alpha.load()
        for yy in range(crop.height):
            for xx in range(crop.width):
                r,g,b,a=px[xx,yy]
                if a < 100:
                    continue
                lum=(0.299*r)+(0.587*g)+(0.114*b)
                spread=max(r,g,b)-min(r,g,b)
                # O rosto é preto e o traço do olho é praticamente acromático e claro.
                if lum > 58 and spread < 62:
                    ap[xx,yy]=int(max(0,min(255,(lum-48)*2.15)) * (a/255.0))
        layer=Image.new('RGBA', crop.size, (255,255,255,0))
        layer.putalpha(alpha)
        return layer

    @staticmethod
    def _ia_live_clean_eye_region(img, boxes):
        """Remove o traço estático dos olhos do corpo-base para que os olhos possam ser desenhados separadamente."""
        from PIL import Image, ImageFilter
        base=img.copy().convert('RGBA')
        px=base.load()
        for x0,y0,x1,y1 in boxes:
            # O visor é predominantemente preto; usamos uma média escura local para apagar
            # apenas o brilho do olho, mantendo a identidade do mascote.
            samples=[]
            sx0=max(x0,x0+8); sy0=max(y0,y0+8); sx1=min(x1,x1-8); sy1=min(y1,y1-8)
            for yy in range(sy0,sy1,max(1,(sy1-sy0)//12 or 1)):
                for xx in range(sx0,sx1,max(1,(sx1-sx0)//12 or 1)):
                    r,g,b,a=px[xx,yy]
                    lum=(0.299*r)+(0.587*g)+(0.114*b)
                    if a>100 and lum < 70:
                        samples.append((r,g,b))
            if samples:
                sr=int(sum(v[0] for v in samples)/len(samples))
                sg=int(sum(v[1] for v in samples)/len(samples))
                sb=int(sum(v[2] for v in samples)/len(samples))
            else:
                sr=sg=sb=10
            mask=Image.new('L', base.size, 0)
            mp=mask.load()
            for yy in range(max(0,y0-5),min(base.height,y1+5)):
                for xx in range(max(0,x0-5),min(base.width,x1+5)):
                    r,g,b,a=px[xx,yy]
                    lum=(0.299*r)+(0.587*g)+(0.114*b)
                    spread=max(r,g,b)-min(r,g,b)
                    if a>70 and lum>55 and spread<70:
                        mp[xx,yy]=255
            mask=mask.filter(ImageFilter.GaussianBlur(radius=1.15))
            fill=Image.new('RGBA', base.size, (sr,sg,sb,255))
            base.alpha_composite(Image.composite(fill, Image.new('RGBA',base.size,(0,0,0,0)), mask))
        return base

    def _ia_live_prepare_renderer(self):
        """Prepara camadas uma vez; os quadros seguintes são renderizados matematicamente."""
        try:
            from PIL import Image
            src=Image.open(MASCOT_EXATO_IA_PATH).convert('RGBA')
            eye_boxes=((438,455,574,538),(705,405,835,490))
            self._ia_live_eye_boxes=eye_boxes
            self._ia_live_base_source=self._ia_live_clean_eye_region(src,eye_boxes)
            self._ia_live_eye_left=self._ia_live_white_eye_mask(src,eye_boxes[0])
            self._ia_live_eye_right=self._ia_live_white_eye_mask(src,eye_boxes[1])
            for state,path in MASCOT_POSE_PATHS.items():
                if state.startswith('look_'):
                    continue
                try:
                    if Path(path).exists():
                        self._ia_live_pose_sources[state]=Image.open(path).convert('RGBA')
                except Exception:
                    pass
            self._ia_live_ready=True
        except Exception:
            self._ia_live_ready=False

    def _ia_live_fit_source(self, source):
        from PIL import Image
        size=self._ia_live_render_size
        im=source.copy().convert('RGBA')
        im.thumbnail((size,size), Image.Resampling.LANCZOS)
        canvas=Image.new('RGBA',(size,size),(0,0,0,0))
        canvas.alpha_composite(im,((size-im.width)//2,size-im.height))
        return canvas

    def _ia_live_blink_factor(self, now):
        if self._ia_live_blink_started is None:
            return 1.0
        elapsed=now-self._ia_live_blink_started
        dur=max(0.08,self._ia_live_blink_duration)
        if elapsed >= dur:
            self._ia_live_blink_started=None
            if getattr(self,'_ia_live_blink_countdown',0):
                self._ia_live_blink_countdown=0
                self._ia_live_next_blink=now+self._ia_live_rng.uniform(0.10,0.22)
            else:
                self._ia_live_next_blink=now+self._ia_live_rng.uniform(2.8,5.8)
            return 1.0
        t=max(0.0,min(1.0,elapsed/dur))
        # 1 -> 0.08 -> 1: fecha e abre suavemente.
        return 0.08 + 0.92*abs(2.0*t-1.0)

    def _ia_behavior_transition(self, state, reason='', duration=0.0):
        """Troca o estado comportamental sem tocar nos fluxos fiscais."""
        state = str(state or 'IDLE').upper().replace('ATENCAO','ATENÇÃO').replace('CONFIRMACAO','CONFIRMAÇÃO')
        if state not in self._ia_behavior_profiles:
            state = 'IDLE'
        now = time.monotonic()
        previous = getattr(self, '_ia_behavior_state', 'IDLE')
        self._ia_behavior_state = state
        self._ia_behavior_reason = str(reason or '')
        self._ia_behavior_last_transition = now
        if duration > 0:
            self._ia_behavior_until = now + duration
        elif state not in getattr(self, '_ia_behavior_transient', set()):
            self._ia_behavior_until = 0.0
        if state != previous:
            self._ia_behavior_last_event = f'{previous}>{state}'
            try:
                profile = self._ia_behavior_profiles[state]
                self._ia_live_motion_energy = profile['energy']
            except Exception:
                pass
            # Reação física curta nos estados que representam acontecimentos.
            if state in {'ATENTO','INTERAGINDO','SUCESSO','CONFIRMAÇÃO','ATENÇÃO','DIVERGÊNCIA','ERRO'}:
                self._ia_live_reaction_until = now + (0.46 if state in {'SUCESSO','CONFIRMAÇÃO'} else 0.32)

    def _ia_behavior_tick(self, now):
        """Transforma contexto recente em estado, sem necessidade de frases."""
        state = getattr(self, '_ia_behavior_state', 'IDLE')
        # Estados transitórios respeitam sua duração antes de voltar ao repouso.
        if state in getattr(self, '_ia_behavior_transient', set()) and now < getattr(self, '_ia_behavior_until', 0.0):
            return state

        pose_map = {
            'processando':'PROCESSANDO', 'analisando':'ANALISANDO',
            'concluido':'SUCESSO', 'atencao':'ATENÇÃO',
            'divergencia':'DIVERGÊNCIA', 'erro':'ERRO',
            'dica':'OBSERVANDO', 'saudacao':'CONFIRMAÇÃO',
        }
        pose = str(getattr(self, '_ia_live_base_pose', 'repouso') or 'repouso').lower()
        if pose in pose_map:
            desired = pose_map[pose]
        elif getattr(self, '_ia_behavior_cursor_near', False):
            desired = 'INTERAGINDO'
        elif (now - getattr(self, '_ia_live_last_user_action_at', now)) < 3.0:
            desired = 'OBSERVANDO'
        elif now >= getattr(self, '_ia_behavior_next_curiosity', now + 1):
            desired = 'OBSERVANDO'
            self._ia_behavior_next_curiosity = now + self._ia_live_rng.uniform(9.0, 18.0)
        elif (now - getattr(self, '_ia_live_last_mouse_at', now)) < 1.8:
            desired = 'OBSERVANDO'
        else:
            desired = 'IDLE'

        if state != desired:
            self._ia_behavior_transition(desired, reason='context')
        return desired

    def _ia_behavior_gaze_bias(self, state):
        """Pequenos vieses de olhar por estado, evitando movimentos teatrais."""
        profiles = {
            'PROCESSANDO': ((0.0, -0.02), (0.08, 0.03)),
            'ANALISANDO':  ((-0.06, 0.08), (0.34, 0.08)),
            'BUSCANDO':    ((0.04, 0.02), (0.30, 0.04)),
            'AUDITANDO':   ((0.08, 0.09), (0.32, 0.07)),
            'SUCESSO':     ((0.0, 0.0), (0.20, 0.04)),
            'ATENÇÃO':     ((-0.03, 0.03), (0.26, 0.05)),
            'DIVERGÊNCIA': ((0.08, 0.04), (0.30, 0.06)),
            'ERRO':        ((0.10, 0.06), (0.26, 0.05)),
            'CONFIRMAÇÃO': ((0.0, -0.02), (0.18, 0.03)),
            'INTERAGINDO': ((0.0, 0.0), (0.14, 0.02)),
            'OBSERVANDO':  ((0.0, 0.0), (0.18, 0.03)),
            'IDLE':        ((0.0, 0.0), (0.20, 0.02)),
            'CURIOSO':     ((0.02, 0.01), (0.16, 0.035)),
            'HUMOR':       ((-0.02, -0.015), (0.22, 0.03)),
            'SURPRESA':    ((0.0, -0.02), (0.12, 0.02)),
            'DÚVIDA':      ((0.18, 0.01), (0.16, 0.03)),
            'ALÍVIO':      ((0.0, 0.0), (0.20, 0.02)),
            'CONCENTRADO': ((0.04, 0.05), (0.10, 0.02)),
        }
        return profiles.get(state, profiles['IDLE'])

    def _ia_live_update_autonomy(self, now):
        """Attention-driven gaze with short-term context and controlled curiosity."""
        self._ia_session_observe(now)
        state=self._ia_behavior_tick(now)
        mouse_recent=(now-self._ia_live_last_mouse_at) < (0.90 if state!='INTERAGINDO' else 1.35)
        focus_target=None; focus_strength=float(getattr(self,'_ia_attention_strength',0.0) or 0.0)
        if getattr(self,'_ia_attention_target',None) and focus_strength>0.03:
            try:
                fx,fy=self._ia_attention_target; cx=self.ia_float_img.winfo_rootx()+self.ia_float_img.winfo_width()/2.0; cy=self.ia_float_img.winfo_rooty()+self.ia_float_img.winfo_height()/2.0
                focus_target=(max(-1.0,min(1.0,(fx-cx)/330.0)),max(-1.0,min(1.0,(fy-cy)/420.0))*0.65)
            except Exception:focus_target=None
            self._ia_attention_strength=max(0.0,focus_strength*0.94)
        if focus_target and not mouse_recent and focus_strength>0.20:
            target_x,target_y=focus_target
            if state in {'IDLE','OBSERVANDO'}: self._ia_behavior_transition('ATENTO',reason='attention_target',duration=0.50)
        elif mouse_recent:
            target_x=self._ia_live_mouse_target; target_y=self._ia_live_mouse_target_y
        else:
            primary,bias=self._ia_behavior_gaze_bias(state)
            if now>=self._ia_live_next_autonomous_move and now>=self._ia_live_autonomous_return_at:
                if state in {'ANALISANDO','AUDITANDO','ATENÇÃO','DIVERGÊNCIA','ERRO'}: choices=((-0.45,0.08),(0.44,0.06),(-0.26,0.17),(0.30,0.12),(0.06,-0.06),(0.0,0.0))
                elif state in {'PROCESSANDO','BUSCANDO'}: choices=((-0.24,0.02),(0.30,-0.02),(0.12,0.10),(-0.10,-0.12),(0.0,0.0))
                elif state in {'SUCESSO','CONFIRMAÇÃO'}: choices=((-0.16,-0.04),(0.18,-0.02),(0.0,0.0))
                elif state=='OBSERVANDO' and now>=self._ia_behavior_curiosity_until: choices=((-0.20,0.02),(0.14,0.04),(0.08,0.10),(-0.08,-0.08))
                else: choices=((-0.52,-0.10),(0.46,-0.06),(-0.28,0.16),(0.28,0.12),(0.0,0.0),(-0.08,-0.18))
                choice=self._ia_live_rng.choice(choices); self._ia_live_autonomous_target=choice[0]+primary[0]; self._ia_live_autonomous_target_y=choice[1]+primary[1]
                self._ia_live_autonomous_return_at=now+self._ia_live_rng.uniform(0.55,1.45); self._ia_live_next_autonomous_move=now+self._ia_live_rng.uniform(2.6,6.8)
                if state=='OBSERVANDO': self._ia_behavior_curiosity_until=now+self._ia_live_rng.uniform(0.8,2.2)
            target_x=self._ia_live_autonomous_target; target_y=self._ia_live_autonomous_target_y
            if self._ia_live_autonomous_return_at and now>=self._ia_live_autonomous_return_at:
                self._ia_live_autonomous_target*=0.14; self._ia_live_autonomous_target_y*=0.14
                if abs(self._ia_live_autonomous_target)<0.04 and abs(self._ia_live_autonomous_target_y)<0.04:
                    self._ia_live_autonomous_target=0.0; self._ia_live_autonomous_target_y=0.0; self._ia_live_autonomous_return_at=0.0
                target_x=self._ia_live_autonomous_target; target_y=self._ia_live_autonomous_target_y
            target_x+=self._ia_live_rng.uniform(-bias[0],bias[0])*0.20; target_y+=self._ia_live_rng.uniform(-bias[1],bias[1])*0.20
        if now>=self._ia_live_next_saccade and now>=self._ia_live_saccade_until:
            amplitude_x=0.055 if state not in {'ERRO','DIVERGÊNCIA'} else 0.045; amplitude_y=0.035 if state not in {'ERRO','DIVERGÊNCIA'} else 0.028
            self._ia_live_saccade_x=self._ia_live_rng.uniform(-amplitude_x,amplitude_x); self._ia_live_saccade_y=self._ia_live_rng.uniform(-amplitude_y,amplitude_y)
            self._ia_live_saccade_until=now+self._ia_live_rng.uniform(0.08,0.16); self._ia_live_next_saccade=now+self._ia_live_rng.uniform(0.55,1.80)
        elif now>=self._ia_live_saccade_until:
            self._ia_live_saccade_x=0.0; self._ia_live_saccade_y=0.0
        target_x=max(-1.0,min(1.0,target_x+self._ia_live_saccade_x)); target_y=max(-1.0,min(1.0,target_y+self._ia_live_saccade_y))
        smoothing=0.10 if state in {'ATENTO','INTERAGINDO','SUCESSO','CONFIRMAÇÃO'} else 0.13
        self._ia_live_eye_current+=(target_x-self._ia_live_eye_current)*smoothing; self._ia_live_eye_current_y+=(target_y-self._ia_live_eye_current_y)*smoothing
        return self._ia_live_eye_current,self._ia_live_eye_current_y

    def _ia_live_render_frame(self, now=None):
        """Renderiza um quadro novo do personagem; não depende de PNGs de animação pré-trocados."""
        from PIL import Image, ImageTk
        if not self._ia_live_ready:
            return None
        now=now or time.monotonic()
        eye_target,eye_target_y=self._ia_live_update_autonomy(now)
        if self._ia_live_blink_started is None and now >= self._ia_live_next_blink:
            self._ia_live_blink_started=now
            self._ia_live_blink_duration=self._ia_live_rng.uniform(0.11,0.19)
            self._ia_live_blink_countdown=1 if self._ia_live_rng.random() < 0.12 else 0
        blink=self._ia_live_blink_factor(now)

        behavior=self._ia_behavior_tick(now)
        profile=self._ia_behavior_profiles.get(behavior,self._ia_behavior_profiles['IDLE'])
        breath_rate=profile['breath']
        self._ia_live_breath_phase=(now*breath_rate + self._ia_live_breath_offset)%(math.tau)
        breath=math.sin(self._ia_live_breath_phase)
        secondary=math.sin(self._ia_live_breath_phase*0.47+1.3)
        tertiary=math.sin(self._ia_live_breath_phase*0.71+3.7)
        energy=max(0.55,min(1.45,profile['energy']))
        scale=1.0 + (0.0075*energy)*breath
        bob=(0.30+0.24*energy)*breath + 0.12*secondary + 0.05*tertiary
        self._ia_live_head_target=(0.30*eye_target + 0.13*secondary + 0.08*tertiary + profile['head'])
        self._ia_live_head_current += (self._ia_live_head_target-self._ia_live_head_current)*0.055
        tilt=self._ia_live_head_current

        state=getattr(self,'_ia_live_base_pose',getattr(self,'_ia_float_base_pose','repouso'))
        source=self._ia_live_base_source if state in ('repouso','saudacao') else self._ia_live_pose_sources.get(state,self._ia_live_base_source)
        if source is None:
            source=self._ia_live_base_source
        frame=self._ia_live_fit_source(source)

        if state in ('repouso','saudacao') and self._ia_live_eye_left is not None and self._ia_live_eye_right is not None:
            # Coordenadas relativas ao mesmo encaixe usado no corpo-base.
            src_w,src_h=self._ia_live_base_source.size
            scaled_w,scaled_h=frame.width,frame.height
            # Como o source é ajustado proporcionalmente, os fatores são iguais.
            factor=min(scaled_w/src_w, scaled_h/src_h)
            ox=(self._ia_live_render_size-scaled_w)//2
            oy=self._ia_live_render_size-scaled_h
            lx0,ly0,lx1,ly1=self._ia_live_eye_boxes[0]
            rx0,ry0,rx1,ry1=self._ia_live_eye_boxes[1]
            eye_layers=((self._ia_live_eye_left,lx0,ly0),(self._ia_live_eye_right,rx0,ry0))
            eye_dx=3.05*eye_target
            eye_dy=1.55*eye_target_y + 0.28*breath
            expression_scale={
                'IDLE':0.98,'OBSERVANDO':1.00,'ATENTO':1.01,'INTERAGINDO':1.00,
                'CURIOSO':1.055,'HUMOR':0.89,'SURPRESA':1.12,'DÚVIDA':0.93,
                'ALÍVIO':0.89,'CONCENTRADO':0.85,'CONFIRMAÇÃO':0.98,
            }.get(behavior,0.92)
            expression_tilt={
                'CURIOSO':-5.0,'HUMOR':2.4,'SURPRESA':0.0,'DÚVIDA':-6.0,
                'ALÍVIO':1.8,'CONCENTRADO':-2.2,
            }.get(behavior,0.0)
            expression_asym={
                'CURIOSO':0.35,'DÚVIDA':0.95,'HUMOR':0.25,
            }.get(behavior,0.0)
            for idx,(eye,x,y) in enumerate(eye_layers):
                ew=max(1,int(round(eye.width*factor)))
                asym=(expression_asym if idx==0 else -expression_asym)
                eh=max(1,int(round(eye.height*factor*blink*expression_scale)))
                e=eye.resize((ew,eh),Image.Resampling.LANCZOS)
                # Inclinação e assimetria sutis criam leitura de curiosidade/dúvida/humor.
                e=e.rotate(-(eye_target*4.0 + expression_tilt + asym),Image.Resampling.BICUBIC,expand=True)
                ex=int(round(ox+x*factor + eye_dx + (1.0 if idx==0 else -1.0)*eye_target*0.25))
                ey=int(round(oy+y*factor + eye_dy + (1.0 if idx==0 else -1.0)*(0.15+0.55*expression_asym)))
                frame.alpha_composite(e,(ex,ey))

        if now < self._ia_live_reaction_until:
            reaction_phase=(self._ia_live_reaction_until-now)/0.32
            bob += 0.55*max(0.0,min(1.0,reaction_phase))
        if abs(scale-1.0)>0.001:
            sw=max(1,int(round(frame.width*scale)))
            sh=max(1,int(round(frame.height*scale)))
            scaled=frame.resize((sw,sh),Image.Resampling.BICUBIC)
            centered=Image.new('RGBA',(self._ia_live_render_size,self._ia_live_render_size),(0,0,0,0))
            centered.alpha_composite(scaled,((self._ia_live_render_size-sw)//2,int(round((self._ia_live_render_size-sh)*0.5+bob))))
            frame=centered
        elif abs(bob)>0.05:
            shifted=Image.new('RGBA',frame.size,(0,0,0,0))
            shifted.alpha_composite(frame,(0,int(round(bob))))
            frame=shifted

        frame=frame.rotate(tilt,Image.Resampling.BICUBIC,expand=False,center=(self._ia_live_render_size*0.5,self._ia_live_render_size*0.46))
        frame=frame.resize((self._ia_live_display_size,self._ia_live_display_size),Image.Resampling.LANCZOS)
        return ImageTk.PhotoImage(frame)

    def _ia_float_prepare_gaze_frames(self):
        # Mantido por compatibilidade com chamadas antigas; V114 não usa troca de quadros.
        return

    def _ia_float_load_pose(self, state='repouso'):
        self._ia_live_pose_state=state
        self._ia_float_pose=state
        if not hasattr(self,'ia_float_img'):
            return
        # Renderiza imediatamente um frame novo para que a mudança de contexto seja fluida.
        try:
            img=self._ia_live_render_frame(time.monotonic()) if self._ia_live_ready else None
            if img is not None:
                self._ia_float_imgtk=img
                self.ia_float_img.config(image=img, text='')
        except Exception:
            try:
                path=MASCOT_POSE_PATHS.get(state,MASCOT_EXATO_IA_PATH)
                self._ia_float_imgtk=__import__('tkinter').PhotoImage(file=str(path))
                self.ia_float_img.config(image=self._ia_float_imgtk,text='')
            except Exception:
                self.ia_float_img.config(text='E',fg=WHITE,bg=RED,font=('Segoe UI Semibold',12),width=2)

    def _ia_float_apply_gaze(self):
        # Compatibilidade: o olhar agora é calculado pelo renderizador procedural.
        return

    def _ia_float_set_bubble(self, text, duration_ms=3500):
        if not hasattr(self,'ia_float_bubble'): return
        if self._ia_float_bubble_job is not None:
            try: self.after_cancel(self._ia_float_bubble_job)
            except Exception: pass
            self._ia_float_bubble_job=None
        self.ia_float_bubble.config(text=str(text), fg='#F8FAFC', bg='#162033')
        if duration_ms:
            self._ia_float_bubble_job=self.after(duration_ms, self._ia_float_reset_bubble)

    def _ia_float_reset_bubble(self):
        self._ia_float_bubble_job=None
        try: self.ia_float_bubble.config(text='O Exatinho está por aqui.')
        except Exception: pass

    def _ia_emit_event(self, event_type, **payload):
        """Append a contextual event for Exato IA; safe to call from worker threads."""
        payload=dict(payload)
        focus=payload.pop('focus',None)
        event={
            'type':str(event_type or '').strip().upper(),
            'at':time.monotonic(),
            'timestamp':datetime.now().isoformat(timespec='seconds'),
            'screen':str(getattr(self,'current_screen','') or ''),
            'company':str(payload.pop('company','') or self._ia_event_context.get('company','')),
            'focus':focus,
            'payload':payload,
        }
        try:
            toast=self._toast_for_event(event['type'],payload,event['company'])
            if toast: self.after(0,lambda t=toast:self._toast(t[0],t[1]))
        except Exception:
            pass
        with getattr(self,'_ia_event_lock',threading.Lock()):
            queue=getattr(self,'_ia_event_queue',[])
            queue.append(event)
            if len(queue)>32:
                del queue[:-32]
            history=getattr(self,'_ia_session_events',[])
            history.append(event)
            if len(history)>24:
                del history[:-24]
        return event

    def _ia_last_significant_event(self):
        significant={'SYNC_SUCCESS','SYNC_ERROR','AUDIT_CONFORME','AUDIT_DIVERGENCIA','AUDIT_ERROR','PENDING_REVIEW','DANFE_BATCH_DONE'}
        for ev in reversed(getattr(self,'_ia_session_events',[])):
            if ev.get('type') in significant:
                return ev
        return None

    def _ia_session_observe(self, now=None):
        now=now or time.monotonic()
        ctx=getattr(self,'_ia_event_context',{}) or {}
        last=float(ctx.get('last_result_at') or 0.0)
        since=max(0.0,now-last) if last else 999.0
        if ctx.get('status') in {'SYNC_STARTED','AUDIT_STARTED','DANFE_BATCH_STARTED','SYNC_BATCH'}:
            ctx['session_phase']='working'
        elif ctx.get('status') in {'SYNC_SUCCESS','AUDIT_CONFORME','DANFE_BATCH_DONE'} and since<8.0:
            ctx['session_phase']='result'
        elif ctx.get('status') in {'SYNC_ERROR','AUDIT_DIVERGENCIA','AUDIT_ERROR','PENDING_REVIEW'} and since<12.0:
            ctx['session_phase']='attention'
        else:
            ctx['session_phase']='idle'
        return ctx['session_phase']

    def _ia_capture_focus(self, x, y, strength=1.0):
        try:
            self._ia_attention_target=(float(x),float(y))
            self._ia_attention_strength=max(0.0,min(1.0,float(strength)))
            self._ia_event_context['attention_target']=self._ia_attention_target
            self._ia_event_context['attention_strength']=self._ia_attention_strength
        except Exception:
            pass

    def _ia_event_phrase(self, event):
        kind=event.get('type','')
        p=event.get('payload') or {}
        if kind=='SYNC_STARTED':
            fam=str(p.get('family') or '').strip()
            return f'Vou acompanhar a busca de {fam}.' if fam else 'Vou acompanhar a busca.'
        if kind=='SYNC_SUCCESS':
            total=int(p.get('documents') or 0); new=int(p.get('new_documents') or 0)
            fam=str(p.get('family') or '').strip()
            prefix=(fam+' · ') if fam else ''
            if total<=0: return f'{prefix}Nenhum documento novo neste período.'
            if new: return f'{prefix}Encontrei {new} documento(s) novo(s).'
            return f'{prefix}Os documentos já estão organizados na Central.'
        if kind=='SYNC_ERROR':
            cstat=str(p.get('cstat') or '')
            if cstat=='657': return 'A consulta foi rejeitada pelo cStat 657. Vale revisar o órgão autorizador.'
            if cstat=='656': return 'A consulta retornou consumo indevido. É melhor aguardar antes de repetir.'
            return 'A consulta terminou com uma ocorrência. Separei o retorno para revisão.'
        if kind=='AUDIT_STARTED': return 'Agora eu vou prestar atenção nos cruzamentos.'
        if kind=='AUDIT_CONFORME': return 'Tudo conferido por aqui.'
        if kind=='AUDIT_DIVERGENCIA':
            fam=str(p.get('family') or '').strip()
            return f'Encontrei pontos de atenção em {fam}.' if fam else 'Encontrei pontos que merecem uma segunda olhada.'
        if kind=='AUDIT_ERROR': return 'A auditoria não fechou. Vale revisar o retorno.'
        if kind=='PENDING_REVIEW':
            qty=int(p.get('documents') or 0)
            return f'Encontrei {qty} pendência(s) para revisar.' if qty else 'Encontrei pendências que merecem atenção.'
        if kind=='DANFE_BATCH_DONE':
            qty=int(p.get('generated') or 0)
            return f'Pronto. {qty} representação(ões) foram geradas.' if qty else 'A geração terminou.'
        if kind=='USER_CLICK':
            label=str(p.get('focus_label') or '').strip()
            if 'BUSCAR XML' in label or 'SINCRONIZAR' in label: return 'Vou acompanhar a consulta.'
            if 'AUDITORIA' in label: return 'Agora eu presto atenção nos cruzamentos.'
            if 'PENDENCIAS' in label: return 'Vamos olhar o que ficou para trás.'
            if 'DANFE' in label or 'DACTE' in label: return 'Vou acompanhar a representação fiscal.'
        return ''

    def _ia_apply_event(self, event, now=None):
        now=now or time.monotonic(); kind=event.get('type',''); p=event.get('payload') or {}
        cooldowns={'NAVIGATED':0.20,'SYNC_BATCH':1.0,'USER_CLICK':0.18,'SYNC_STARTED':0.8,'AUDIT_STARTED':0.8,'DANFE_BATCH_STARTED':0.8,'PENDING_REVIEW':3.0,'SYNC_SUCCESS':1.6,'SYNC_ERROR':1.2,'AUDIT_CONFORME':2.0,'AUDIT_DIVERGENCIA':1.8,'AUDIT_ERROR':1.8,'DANFE_BATCH_DONE':1.8}
        cd=cooldowns.get(kind,0.45); last=float(getattr(self,'_ia_event_last_handled',{}).get(kind,0.0))
        if now-last<cd and kind not in {'SYNC_ERROR','AUDIT_ERROR','AUDIT_DIVERGENCIA'}: return
        self._ia_event_last_handled[kind]=now
        self._ia_event_context.update({'screen':event.get('screen','') or self._ia_event_context.get('screen',''),'company':event.get('company','') or self._ia_event_context.get('company',''),'family':str(p.get('family') or self._ia_event_context.get('family','')),'status':kind,'last_result_at':now})
        if p.get('documents') is not None:
            try:self._ia_event_context['documents']=int(p.get('documents') or 0)
            except Exception:pass
        if p.get('new_documents') is not None:
            try:self._ia_event_context['new_documents']=int(p.get('new_documents') or 0)
            except Exception:pass
        cstat=str(p.get('cstat') or '')
        if cstat:self._ia_event_context['last_cstat']=cstat
        if p.get('error'):self._ia_event_context['last_error']=str(p.get('error'))
        if event.get('focus'):
            try:self._ia_capture_focus(*event['focus'],strength=0.85)
            except Exception:pass
        significant={'SYNC_SUCCESS','SYNC_ERROR','AUDIT_CONFORME','AUDIT_DIVERGENCIA','AUDIT_ERROR','PENDING_REVIEW','DANFE_BATCH_DONE'}
        if kind in significant:
            self._ia_event_context['last_significant_type']=kind; self._ia_event_context['last_significant_at']=now
            counters=getattr(self,'_exatinho_session_counters',{})
            if kind.startswith('SYNC_') and kind in {'SYNC_SUCCESS','SYNC_ERROR'}: counters['sync']=int(counters.get('sync',0))+1
            elif kind.startswith('AUDIT_') and kind in {'AUDIT_CONFORME','AUDIT_DIVERGENCIA','AUDIT_ERROR'}: counters['audit']=int(counters.get('audit',0))+1
            elif kind=='DANFE_BATCH_DONE': counters['danfe']=int(counters.get('danfe',0))+1
            elif kind=='PENDING_REVIEW': counters['pending']=int(counters.get('pending',0))+1
            if kind=='SYNC_SUCCESS' and int(p.get('new_documents') or 0)>0:
                self._exatinho_schedule_proactive('sync_success_documents',1150,'Encontrei documentos novos. Quer conferir?','documents')
            elif kind in {'AUDIT_DIVERGENCIA','PENDING_REVIEW'}:
                self._exatinho_schedule_proactive('attention_review',1200,'Tem um ponto que merece sua atenção. Quer que eu mostre?','pending')
            elif kind=='AUDIT_CONFORME':
                self._exatinho_schedule_proactive('audit_done',1100,'A conferência terminou sem divergências.','audit')
            self._ia_session_state='attention' if kind in {'SYNC_ERROR','AUDIT_DIVERGENCIA','AUDIT_ERROR','PENDING_REVIEW'} else 'result'
        elif kind in {'SYNC_STARTED','AUDIT_STARTED','DANFE_BATCH_STARTED','SYNC_BATCH'}: self._ia_session_state='working'
        else:self._ia_session_state='idle'
        state_map={'SYNC_STARTED':'processando','SYNC_BATCH':'processando','SYNC_SUCCESS':'concluido','SYNC_ERROR':'erro','AUDIT_STARTED':'analisando','AUDIT_CONFORME':'concluido','AUDIT_DIVERGENCIA':'divergencia','AUDIT_ERROR':'erro','PENDING_REVIEW':'atencao','DANFE_BATCH_STARTED':'processando','DANFE_BATCH_DONE':'concluido'}
        state=state_map.get(kind); phrase=self._ia_event_phrase(event)
        if state:
            duration=1400 if kind in {'SYNC_BATCH','DANFE_BATCH_STARTED'} else 2400
            if kind in {'SYNC_SUCCESS','AUDIT_CONFORME','DANFE_BATCH_DONE'}:duration=2200
            if kind in {'SYNC_ERROR','AUDIT_DIVERGENCIA','AUDIT_ERROR','PENDING_REVIEW'}:duration=2600
            self._ia_float_set_state(state,phrase or 'Estou acompanhando.',duration,react=True)
            # V124: um evento relevante reinicia a janela de silêncio das falas espontâneas.
            self._ia_live_last_context_phrase_at=now
            expression_map={
                'AUDIT_CONFORME':'ALÍVIO',
                'DANFE_BATCH_DONE':'ALÍVIO',
                'PENDING_REVIEW':'CONCENTRADO',
                'AUDIT_DIVERGENCIA':'DÚVIDA',
                'AUDIT_ERROR':'ATENÇÃO',
                'SYNC_SUCCESS':'SUCESSO',
                'SYNC_ERROR':'ATENÇÃO',
            }
            expression=expression_map.get(kind)
            if expression:
                self._ia_behavior_transition(expression,reason=f'event_expression:{kind}',duration=1.15 if expression in {'ALÍVIO','SUCESSO'} else 1.35)
        elif kind=='NAVIGATED':
            active=str(p.get('screen') or event.get('screen') or ''); self._ia_event_context['screen']=active; self._ia_session_state='idle'
            self._ia_behavior_transition('OBSERVANDO',reason=f'navigation:{active}',duration=0.8)
        elif kind=='USER_CLICK':
            self._ia_behavior_transition('ATENTO',reason='event:user_click',duration=0.65); self._ia_live_reaction_until=now+0.30
        if kind=='SYNC_ERROR' and cstat=='657':
            self._ia_live_motion_energy=1.04; self._ia_behavior_transition('ATENÇÃO',reason='cstat:657',duration=1.5)
        elif kind=='SYNC_ERROR' and cstat=='656':
            self._ia_live_motion_energy=1.00; self._ia_behavior_transition('ATENÇÃO',reason='cstat:656',duration=1.7)

    def _ia_process_event_queue(self):
        queue=[]
        with getattr(self,'_ia_event_lock',threading.Lock()):
            if getattr(self,'_ia_event_queue',[]):
                queue=list(self._ia_event_queue[:6])
                del self._ia_event_queue[:len(queue)]
        if not queue:
            return
        now=time.monotonic()
        for event in queue:
            try:
                self._ia_apply_event(event,now)
            except Exception:
                continue

    def _ia_float_set_state(self, state='repouso', message=None, duration_ms=3600, react=False):
        if not hasattr(self,'ia_float'): return
        self._ia_float_base_pose=state
        self._ia_live_base_pose=state
        self._ia_live_pose_state=state
        energy_map={'repouso':0.68,'saudacao':1.08,'dica':0.78,'analisando':1.04,'processando':1.12,'concluido':1.18,'atencao':1.08,'divergencia':1.05,'erro':1.00}
        self._ia_live_motion_energy=energy_map.get(state,0.85)
        behavior_map={'saudacao':'CONFIRMAÇÃO','dica':'OBSERVANDO','analisando':'ANALISANDO','processando':'PROCESSANDO','concluido':'SUCESSO','atencao':'ATENÇÃO','divergencia':'DIVERGÊNCIA','erro':'ERRO','repouso':'IDLE'}
        duration_sec=max(0.0,(duration_ms or 0)/1000.0)
        self._ia_behavior_transition(behavior_map.get(state,'IDLE'),reason=f'pose:{state}',duration=duration_sec if behavior_map.get(state) in self._ia_behavior_transient else 0.0)
        if react:
            self._ia_live_reaction_until=time.monotonic()+0.34
        self._ia_float_load_pose(state)
        final_message=str(message or 'Estou aqui para ajudar.')
        try:
            current=str(self.ia_float_bubble.cget('text') or '').strip()
        except Exception:
            current=''
        if final_message and final_message != current:
            self._ia_float_set_bubble(final_message, duration_ms)

    def _ia_float_set_visibility(self, visible=True):
        return

    def _ia_float_animate(self):
        if not hasattr(self,'ia_float'): return
        try:
            self._ia_process_event_queue()
        except Exception:
            pass
        try:
            now=time.monotonic()
            self._exatinho_presence_tick(now)
            self._ia_float_bob = 1 - self._ia_float_bob
            img=self._ia_live_render_frame(now)
            if img is not None:
                self._ia_float_imgtk=img
                self.ia_float_img.config(image=img)
        except Exception:
            pass
        try: self._ia_float_render_job=self.after(40,self._ia_float_animate)
        except Exception: pass

    def _ia_float_on_mouse_move(self, event=None):
        """Calcula atenção ao cursor com queda de influência por distância e em 2D."""
        if not hasattr(self,'ia_float') or event is None: return
        try:
            now=time.monotonic()
            mx,my=float(event.x_root),float(event.y_root)
            cx=self.ia_float_img.winfo_rootx()+self.ia_float_img.winfo_width()/2.0
            cy=self.ia_float_img.winfo_rooty()+self.ia_float_img.winfo_height()/2.0
            dx=(mx-cx); dy=(my-cy)
            nx=max(-1.0,min(1.0,dx/330.0))
            ny=max(-1.0,min(1.0,dy/420.0))
            proximity=max(0.0,min(1.0,1.0-(abs(dx)/420.0)))
            vertical=max(0.0,min(1.0,1.0-(abs(dy)/520.0)))
            weight=0.25+0.65*min(proximity,vertical)
            target_x=nx*weight
            target_y=ny*weight*0.65
            self._ia_live_mouse_target=target_x
            self._ia_live_mouse_target_y=target_y
            self._ia_live_last_mouse_at=now
            self._ia_live_last_user_action_at=now
            self._ia_behavior_cursor_near=(abs(dx) < 95.0 and abs(dy) < 125.0)
            self._ia_behavior_attention=max(0.0,1.0-min(1.0,((abs(dx)/95.0)**2+(abs(dy)/125.0)**2)/2.0))
            if self._ia_behavior_cursor_near and getattr(self,'_ia_behavior_state','IDLE')=='IDLE':
                self._ia_behavior_transition('INTERAGINDO',reason='cursor_near',duration=0.55)
            self._ia_float_gaze_target=target_x
            self._ia_float_mouse_dir='left' if target_x < -0.18 else ('right' if target_x > 0.18 else 'center')
        except Exception:
            self._ia_live_mouse_target=0.0
            self._ia_live_mouse_target_y=0.0
            self._ia_live_last_mouse_at=time.monotonic()
            self._ia_behavior_cursor_near=False
            self._ia_behavior_attention=0.0
            self._ia_float_gaze_target=0.0
            self._ia_float_mouse_dir='center'

    def _ia_float_widget_text(self, widget):
        try:
            for key in ('text','label'):
                try:
                    val=widget.cget(key)
                    if val: return str(val).strip()
                except Exception:
                    pass
        except Exception:
            pass
        return ''

    def _ia_float_on_click(self, event=None):
        """Reação contextual a cliques, sem substituir os handlers fiscais."""
        if not hasattr(self,'ia_float') or event is None: return
        try:
            now=time.monotonic()
            self._ia_live_last_user_action_at=now
            label=self._ia_float_widget_text(event.widget)
            if not label: return
            text=unicodedata.normalize('NFKD',label).encode('ascii','ignore').decode().upper()
            try:
                mx,my=float(event.x_root),float(event.y_root)
                cx=self.ia_float_img.winfo_rootx()+self.ia_float_img.winfo_width()/2.0
                cy=self.ia_float_img.winfo_rooty()+self.ia_float_img.winfo_height()/2.0
                self._ia_live_mouse_target=max(-1.0,min(1.0,(mx-cx)/330.0))
                self._ia_live_mouse_target_y=max(-1.0,min(1.0,(my-cy)/420.0))*0.55
                self._ia_live_last_mouse_at=now
            except Exception:
                pass
            self._ia_live_reaction_until=now+0.34
            try: self._ia_capture_focus(mx,my,0.95)
            except Exception: pass
            self._ia_behavior_transition('ATENTO',reason=f'click:{text[:32]}',duration=0.90)
            try: self._ia_emit_event('USER_CLICK',label=text[:48],focus=(mx,my),focus_label=text[:48],screen=getattr(self,'current_screen',''))
            except Exception: pass
            contexts=(
                ('BUSCAR XML','sync','Vou acompanhar a consulta.'),
                ('SINCRONIZAR','sync','Vou acompanhar a sincronização.'),
                ('AUDITORIA','audit','Agora eu vou prestar atenção nos cruzamentos.'),
                ('PENDENCIAS','pending','Vamos olhar o que ficou para trás.'),
                ('RELATOR','reports','Vou olhar o que merece destaque.'),
                ('DANFE','documents','Vou acompanhar a representação fiscal.'),
                ('DACTE','documents','Vou acompanhar a representação fiscal.'),
                ('DOCUMENTOS','documents','Vamos olhar os documentos.'),
                ('CERTIFICADO','cert','Vou ficar atento a essa configuração.'),
            )
            for needle,screen,phrase in contexts:
                if needle in text and screen==getattr(self,'current_screen',screen):
                    if screen=='audit':
                        self._ia_float_set_state('atencao',phrase,1500,react=True)
                        self._ia_behavior_transition('ATENÇÃO',reason=f'context:{needle}',duration=1.50)
                    elif screen=='sync':
                        self._ia_float_set_state('processando',phrase,1500,react=True)
                        self._ia_behavior_transition('BUSCANDO',reason=f'context:{needle}',duration=1.50)
                    else:
                        self._ia_float_set_state('repouso',phrase,1500,react=True)
                    self._ia_live_last_click_context=needle
                    return
        except Exception:
            pass

    def _exatinho_screen_label(self, screen=None):
        screen = str(screen or getattr(self, 'current_screen', '') or '').strip().lower()
        return {
            'dashboard': 'Início',
            'sync': 'Buscar XML',
            'documents': 'Documentos Fiscais',
            'audit': 'Auditoria Fiscal',
            'pending': 'Pendências',
            'history': 'Histórico',
            'reports': 'Relatórios',
            'cert': 'Certificado',
            'maintenance': 'Manutenção',
            'companies': 'Empresas',
        }.get(screen, 'Central Fiscal')

    def _exatinho_event_label(self, event=None):
        if not event:
            return ''
        kind = str(event.get('type') or '')
        p = event.get('payload') or {}
        labels = {
            'SYNC_STARTED': 'Busca XML iniciada',
            'SYNC_SUCCESS': 'Busca XML concluída',
            'SYNC_ERROR': 'Retorno do serviço fiscal',
            'AUDIT_STARTED': 'Auditoria iniciada',
            'AUDIT_CONFORME': 'Auditoria concluída',
            'AUDIT_DIVERGENCIA': 'Auditoria com pontos de atenção',
            'AUDIT_ERROR': 'Auditoria com ocorrência',
            'PENDING_REVIEW': 'Pendências identificadas',
            'DANFE_BATCH_STARTED': 'Geração em lote iniciada',
            'DANFE_BATCH_DONE': 'Geração em lote concluída',
            'NAVIGATED': 'Navegação na Central',
            'USER_CLICK': 'Interação com a Central',
        }
        label = labels.get(kind, kind.replace('_', ' ').title())
        if kind == 'SYNC_SUCCESS':
            try:
                total = int(p.get('documents') or 0)
                new = int(p.get('new_documents') or 0)
                if total or new:
                    label += f' · {new or total} doc(s)'
            except Exception:
                pass
        return label

    def _exatinho_context_message(self):
        ctx = getattr(self, '_ia_event_context', {}) or {}
        screen = self._exatinho_screen_label(ctx.get('screen') or getattr(self, 'current_screen', ''))
        status = str(ctx.get('status') or 'idle').upper()
        docs = int(ctx.get('documents') or 0) if str(ctx.get('documents') or '').isdigit() else 0
        last = self._ia_last_significant_event()
        if status in {'SYNC_STARTED', 'AUDIT_STARTED', 'DANFE_BATCH_STARTED', 'SYNC_BATCH'}:
            return f'Estou acompanhando {screen}. A operação ainda está em andamento.'
        if status in {'SYNC_ERROR', 'AUDIT_ERROR'}:
            cstat = str(ctx.get('last_cstat') or '').strip()
            return f'Estou atento ao retorno atual{(" · cStat " + cstat) if cstat else ""}. Vale revisar os detalhes antes de repetir.'
        if status in {'AUDIT_DIVERGENCIA', 'PENDING_REVIEW'}:
            return 'Encontrei pontos que merecem atenção. Quer que eu mostre?'
        if status in {'SYNC_SUCCESS', 'AUDIT_CONFORME', 'DANFE_BATCH_DONE'}:
            if docs:
                return f'A Central está em {screen}. Tenho {docs} documento(s) no contexto recente.'
            return f'A Central está em {screen}. Tudo tranquilo por aqui.'
        if last:
            return f'Último acontecimento: {self._exatinho_event_label(last)}.'
        return f'Você está em {screen}. Estou acompanhando a operação.'

    def _exatinho_session_snapshot(self):
        """Resumo compacto do estado da sessão para o painel do Exatinho."""
        ctx=getattr(self,'_ia_event_context',{}) or {}
        phase=getattr(self,'_ia_session_state','idle') or 'idle'
        status=str(ctx.get('status') or 'idle').upper()
        last=self._ia_last_significant_event()
        company=str(ctx.get('company') or '').strip()
        docs=int(ctx.get('documents') or 0) if str(ctx.get('documents') or '').isdigit() else 0
        screen=self._exatinho_screen_label(ctx.get('screen') or getattr(self,'current_screen',''))
        tone={
            'idle':'Tranquilo',
            'working':'Em atividade',
            'result':'Resultado recente',
            'attention':'Atenção',
        }.get(str(phase).lower(),'Acompanhando')
        counters=dict(getattr(self,'_exatinho_session_counters',{}) or {})
        return {'screen':screen,'phase':phase,'tone':tone,'status':status,'company':company,'documents':docs,'last':last,'session':counters}

    def _exatinho_recent_activity_lines(self, limit=4):
        """Retorna uma pequena linha do tempo, sem expor detalhes técnicos desnecessários."""
        events=[]
        for ev in reversed(getattr(self,'_ia_session_events',[])):
            kind=str(ev.get('type') or '')
            if kind not in {'SYNC_SUCCESS','SYNC_ERROR','AUDIT_CONFORME','AUDIT_DIVERGENCIA','AUDIT_ERROR','PENDING_REVIEW','DANFE_BATCH_DONE','SYNC_STARTED','AUDIT_STARTED','DANFE_BATCH_STARTED'}:
                continue
            when=str(ev.get('timestamp') or '')[11:16]
            label=self._exatinho_event_label(ev)
            if label:
                events.append(f'{when}  {label}' if when else label)
            if len(events)>=limit: break
        return events

    def _exatinho_presence_tick(self, now):
        """Microreações autônomas ocasionais: presença sem interromper o trabalho."""
        if not hasattr(self,'ia_float') or getattr(self,'_exatinho_panel_open',False):
            return
        if getattr(self,'_ia_float_bubble_job',None) is not None:
            return
        if now < getattr(self,'_exatinho_presence_next',now):
            return
        idle_for=now-getattr(self,'_ia_live_last_user_action_at',now)
        if idle_for < 24.0:
            self._exatinho_presence_next=now+self._ia_live_rng.uniform(18.0,32.0)
            return
        last_event=self._ia_last_significant_event()
        last_sig=float(getattr(self,'_ia_event_context',{}).get('last_significant_at') or 0.0)
        if last_sig and (now-last_sig)<18.0:
            self._exatinho_presence_next=now+self._ia_live_rng.uniform(12.0,24.0)
            return
        # Mais tempo parado = maior chance de um pequeno gesto, nunca de uma fala extra.
        choices=['curiosity','posture','lookaway']
        if idle_for>=75.0:
            choices += ['curiosity','humor']
        kind=self._ia_live_rng.choice(choices)
        duration={'curiosity':2.0,'posture':1.6,'lookaway':1.4,'humor':1.9}.get(kind,1.6)
        state={'curiosity':'CURIOSO','posture':'OBSERVANDO','lookaway':'IDLE','humor':'HUMOR'}.get(kind,'OBSERVANDO')
        reason=f'presence:{kind}'
        self._ia_behavior_transition(state,reason=reason,duration=duration)
        self._ia_live_reaction_until=now+min(0.55,duration*0.30)
        self._exatinho_last_presence_at=now
        self._exatinho_presence_count=getattr(self,'_exatinho_presence_count',0)+1
        self._exatinho_last_presence_kind=kind
        self._exatinho_presence_cooldown=now+24.0
        self._exatinho_presence_next=now+self._ia_live_rng.uniform(28.0,52.0)
        if last_event and kind=='humor' and idle_for>=95.0 and self._ia_live_rng.random()<0.18:
            # Não abre conversa nova; apenas usa uma frase curta de companhia.
            phrase='Ainda estou por aqui. Só acompanhando. 👀'
            self._ia_float_set_bubble(phrase,3200)
            self._ia_live_last_context_phrase_at=now

    def _exatinho_panel_render(self):
        if not hasattr(self, 'ia_sidebar_interaction'):
            return
        panel = self.ia_sidebar_interaction
        for child in panel.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass

        top = tk.Frame(panel, bg='#162033')
        top.pack(fill='x', padx=10, pady=(9, 4))
        tk.Label(top, text='EXATINHO', bg='#162033', fg=WHITE,
                 font=('Segoe UI Semibold', 11)).pack(side='left')
        tk.Label(top, text='Inteligência da Central', bg='#162033', fg='#94A3B8',
                 font=('Segoe UI', 7)).pack(side='left', padx=(7,0), pady=(3,0))
        close = tk.Label(top, text='×', bg='#162033', fg='#94A3B8',
                         font=('Segoe UI Semibold', 11), cursor='hand2')
