        if getattr(self, '_exatinho_first_interaction', True):
            resume=self._exatinho_startup_context or self._exatinho_startup_resume_context()
            if resume and int(resume.get('documents') or 0)>0:
                first_name=str(self.current_user.get('name') or 'você').strip().split()[0]
                greeting = f"Oi, {first_name}! Eu sou o Exatinho. Você estava trabalhando com {resume.get('company') or 'esta empresa'}; encontrei {int(resume.get('documents') or 0)} documento(s) na última operação."
            else:
                first_name=str(self.current_user.get('name') or 'você').strip().split()[0]
                greeting = f'Olá, {first_name}! Eu sou o Exatinho. Acompanho o que acontece na Central e posso ajudar quando precisar.'
        else:
            greeting = self._exatinho_context_message()
        panel_width=340
        content_wrap=panel_width-34
        tk.Label(panel, text=greeting, bg='#162033', fg='#E7EEF5',
                 font=('Segoe UI', 10), justify='left', wraplength=content_wrap,
                 anchor='w').pack(fill='x', padx=10, pady=(0, 8))

        snap=self._exatinho_session_snapshot()
        card=tk.Frame(panel,bg='#1B2940',highlightbackground='#2B3647',highlightthickness=1)
        card.pack(fill='x',padx=8,pady=(0,7))
        tk.Label(card,text=f"Agora  ·  {snap['screen']}",bg='#1B2940',fg='#F8FAFC',font=('Segoe UI Semibold',8),anchor='w').pack(fill='x',padx=8,pady=(7,1))
        detail=(f"{snap['tone']}  ·  {snap['documents']} doc(s)" if snap['documents'] else f"{snap['tone']}  ·  sem contagem recente")
        if snap['company']:
            detail += f"  ·  {snap['company']}"
        tk.Label(card,text=detail,bg='#1B2940',fg='#A8B5C6',font=('Segoe UI',7),anchor='w',justify='left',wraplength=max(200,content_wrap-14)).pack(fill='x',padx=8,pady=(0,6))
        ses=snap.get('session') or {}
        session_line=f"Sessão: {ses.get('sync',0)} busca(s) • {ses.get('audit',0)} auditoria(s) • {ses.get('danfe',0)} lote(s)"
        tk.Label(card,text=session_line,bg='#1B2940',fg='#7F8EA3',font=('Segoe UI',7),anchor='w',wraplength=max(200,content_wrap-14)).pack(fill='x',padx=8,pady=(0,7))

        recent_lines=self._exatinho_recent_activity_lines(3)
        if recent_lines:
            recent_wrap=tk.Frame(panel,bg='#162033')
            recent_wrap.pack(fill='x',padx=10,pady=(0,7))
            tk.Label(recent_wrap,text='ATIVIDADE RECENTE',bg='#162033',fg='#7F8EA3',font=('Segoe UI Semibold',7),anchor='w').pack(fill='x')
            tk.Label(recent_wrap,text='\n'.join(recent_lines),bg='#162033',fg='#CBD5E1',font=('Segoe UI',7),justify='left',anchor='w',wraplength=content_wrap).pack(fill='x',pady=(2,0))

        actions = tk.Frame(panel, bg='#162033')
        actions.pack(fill='x', padx=8, pady=(0, 8))
