    def _exatinho_open_pending(self):
        self._exatinho_close_panel()
        self._ia_float_set_bubble('Vamos olhar o que ficou para trás.', 2800)
        self._ia_behavior_transition('ATENÇÃO', reason='exatinho:pending', duration=1.3)
        try:
            self._show_pending()
        except Exception:
            pass

    def _exatinho_choose_spontaneous_phrase(self, screen, idle_for, last_event=None):
        """Escolhe uma fala espontânea curta, contextual e sem repetição imediata."""
        screen=str(screen or 'dashboard').lower()
        pools=[]
        if screen in self._exatinho_spontaneous:
            pools.extend(self._exatinho_spontaneous[screen])
        if idle_for >= 95:
            pools.extend(self._exatinho_spontaneous['humor'])
            pools.extend(self._exatinho_spontaneous['companhia'])
        else:
            pools.extend(self._exatinho_spontaneous['inspiracao'])
            pools.extend(self._exatinho_spontaneous['companhia'])
        if last_event:
            kind=str(last_event.get('type') or '')
            if kind in {'SYNC_SUCCESS','AUDIT_CONFORME','DANFE_BATCH_DONE'}:
                pools.extend(['Tudo resolvido por aqui. Podemos seguir quando você quiser.', 'Missão cumprida por enquanto.'])
            elif kind in {'SYNC_ERROR','AUDIT_ERROR','AUDIT_DIVERGENCIA','PENDING_REVIEW'}:
                pools.extend(['Estou de olho naquele ponto que ficou para revisar.', 'Sem pressa. O importante é entender antes de seguir.'])
        if not pools:
            pools=list(self._exatinho_spontaneous['generic'])
        recent=set(getattr(self,'_exatinho_recent_phrases',[])[-6:])
        choices=[x for x in dict.fromkeys(pools) if x not in recent]
        if not choices:
            choices=list(dict.fromkeys(pools))
        phrase=self._ia_live_rng.choice(choices)
        history=getattr(self,'_exatinho_recent_phrases',[])
        history.append(phrase)
        self._exatinho_recent_phrases=history[-6:]
        return phrase

    def _exatinho_spontaneous_expression(self, phrase):
        lower=str(phrase or '').lower()
        if any(tok in lower for tok in ('😄','😉','👀','café','piada','gostou','profunda','julgar')):
            return 'HUMOR'
        if any(tok in lower for tok in ('atenção','revisar','olhando','resolver','entender')):
            return 'CONCENTRADO'
        return 'CURIOSO'

    def _exatinho_cancel_opening_jobs(self):
        for attr in ('_exatinho_opening_job','_exatinho_opening_followup_job'):
            job=getattr(self,attr,None)
            if job is not None:
                try: self.after_cancel(job)
                except Exception: pass
                setattr(self,attr,None)

    def _exatinho_schedule_opening_greeting(self):
        if not hasattr(self,'ia_float') or getattr(self,'_exatinho_opening_done',False):
            return
        self._exatinho_cancel_opening_jobs()
        try:
            # Pequeno atraso para a janela estar pronta antes da apresentação.
            self._exatinho_opening_job=self.after(1500,self._exatinho_start_opening_greeting)
        except Exception:
            pass

    def _exatinho_start_opening_greeting(self):
        self._exatinho_opening_job=None
        if getattr(self,'_exatinho_opening_done',False) or not hasattr(self,'ia_float'):
            return
        self._exatinho_opening_done=True
        now=time.monotonic()
        self._ia_live_last_user_action_at=now
        self._ia_live_last_context_phrase_at=now
        self._ia_behavior_transition('CONFIRMAÇÃO',reason='exatinho:startup_greeting',duration=1.7)
        first_name=str(self.current_user.get('name') or 'você').strip().split()[0]
        self._ia_float_set_state('saudacao',f'Olá, {first_name}! Que bom ver você de volta.',3800,react=True)
        try:
            self._ia_emit_event('EXATINHO_GREETING',focus_label='Exatinho')
        except Exception:
            pass
        # Segunda frase operacional curta, mas somente se o usuário não interromper.
        try:
            self._exatinho_opening_followup_job=self.after(3600,self._exatinho_opening_followup)
        except Exception:
            pass

    def _exatinho_opening_followup(self):
        self._exatinho_opening_followup_job=None
        if not hasattr(self,'ia_float') or getattr(self,'_exatinho_panel_open',False):
            return
        if (time.monotonic()-getattr(self,'_ia_live_last_user_action_at',0.0)) < 3.0:
            return
        screen=str(getattr(self,'current_screen','') or '').lower()
        resume=self._exatinho_startup_context or self._exatinho_startup_resume_context()
        if resume and screen in {'cert','dashboard','sync'} and int(resume.get('documents') or 0)>0:
            phrase=f"Quer continuar de onde paramos? Encontrei {int(resume.get('documents') or 0)} documento(s) na última operação."
            target='documents'
        elif screen in {'cert','sync','dashboard'}:
            phrase='Bora buscar alguns XML?'
            target='sync'
        elif screen=='documents':
            phrase='Quer conferir alguns documentos?'
            target='documents'
        elif screen=='audit':
            phrase='Vamos conferir o que merece atenção?'
            target='audit'
        else:
            phrase='Por onde começamos?'
            target='dashboard'
        self._ia_live_last_context_phrase_at=time.monotonic()
        self._ia_behavior_transition('OBSERVANDO',reason='exatinho:startup_followup',duration=1.0)
        self._ia_float_set_bubble(phrase,4300)
        self._exatinho_focus_widget({'sync':getattr(self,'nav_sync',None),'documents':getattr(self,'nav_documents',None),'audit':getattr(self,'nav_audit',None),'dashboard':getattr(self,'nav_dashboard',None)}.get(target),0.82)

    def _ia_float_schedule_phrase(self):
        if not hasattr(self,'ia_float'): return
        try:
            # V124: falas espontâneas são deliberadamente raras.
            delay=self._ia_live_rng.randint(45000,75000)
            self._ia_float_phrase_job=self.after(delay,self._ia_float_idle_phrase)
        except Exception: pass

    def _ia_float_idle_phrase(self):
        if not hasattr(self,'ia_float'): return
        try:
            now=time.monotonic()
            idle_for=now-getattr(self,'_ia_live_last_user_action_at',now)
            recent_context=now-getattr(self,'_ia_live_last_context_phrase_at',0.0)
            last_phrase=now-getattr(self,'_ia_float_last_phrase_at',0.0)
            # Janela longa sem atividade + janela longa desde a última fala.
            if (not getattr(self,'_exatinho_panel_open',False)
                and self._ia_float_bubble_job is None
                and self._ia_float_base_pose in ('repouso','saudacao','dica')
                and getattr(self,'_ia_behavior_state','IDLE') in ('IDLE','OBSERVANDO')
                and idle_for>=52.0 and recent_context>=95.0 and (now-last_phrase)>=120.0):
                screen=self.current_screen or 'dashboard'
                last_event=self._ia_last_significant_event()
                if idle_for>=70.0 and self._ia_live_rng.random()<0.32:
                    humor_choices=[p for p in self._exatinho_spontaneous.get('humor',[]) if p not in set(getattr(self,'_exatinho_recent_phrases',[])[-6:])]
                    phrase=self._ia_live_rng.choice(humor_choices or self._exatinho_spontaneous.get('humor',['Estou por aqui.']))
                    hist=getattr(self,'_exatinho_recent_phrases',[])
                    hist.append(phrase); self._exatinho_recent_phrases=hist[-6:]
                else:
                    phrase=self._exatinho_choose_spontaneous_phrase(screen,idle_for,last_event)
                expression=self._exatinho_spontaneous_expression(phrase)
                duration=5200 if len(phrase) < 70 else 5800
                self._ia_float_last_phrase_at=now
                self._ia_live_last_context_phrase_at=now
                self._ia_behavior_transition(expression, reason='exatinho:spontaneous', duration=max(1.2,duration/1000.0))
                self._ia_float_set_bubble(phrase,duration)
        finally:
            self._ia_float_schedule_phrase()

    def _ia_float_on_screen(self, active):
        if not hasattr(self,'ia_float'): return
        if active=='dashboard': self._ia_float_set_state('repouso','Estou aqui para acompanhar sua operação.',2400)
        elif active=='sync': self._ia_float_set_state('repouso','Pronta para acompanhar a consulta XML.',2400)
        elif active=='nfse': self._ia_float_set_state('dica','As NFS-e vêm do Emissor Nacional. Posso acompanhar a busca.',2600)
        elif active=='documents': self._ia_float_set_state('dica','Posso ajudar a localizar documentos e representações.',2600)
        elif active=='audit': self._ia_float_set_state('analisando','Estou pronta para acompanhar a auditoria.',2800)
        elif active=='reports': self._ia_float_set_state('dica','Posso destacar os pontos mais importantes.',2600)
        elif active=='pending': self._ia_float_set_state('atencao','Posso ajudar a revisar os pontos de atenção.',2600)
        elif active=='history': self._ia_float_set_state('dica','Posso ajudar a interpretar o histórico fiscal.',2600)
        else: self._ia_float_set_state('repouso','O Exatinho está aqui para ajudar.',2200)

    def _sync_workspace_layout(self):
        """V146: a página sempre começa no topo e ocupa pelo menos a altura visível.

        O Canvas do Tk centraliza a área rolável quando ela é menor que a janela; isso deixava
        as telas curtas "boiando" no meio. Aqui a altura do conteúdo nunca é menor que a da janela.
        """
        try:
            canvas = self.workspace_canvas
            visible = max(canvas.winfo_width(), 1)
            width = max(visible, PAGE_MIN_WIDTH)
            height = max(canvas.winfo_height(), self.page_host.winfo_reqheight(), 1)
            canvas.itemconfigure(self._workspace_window, width=width, height=height)
            canvas.configure(scrollregion=(0, 0, width, height))
            # Rolagem horizontal de segurança: só aparece se a janela for mais estreita que o mínimo da página.
            need_h = width > visible + 1
            if need_h and not self.workspace_hscroll.winfo_ismapped():
                self.workspace_hscroll.pack(side='bottom', fill='x', before=canvas)
            elif not need_h and self.workspace_hscroll.winfo_ismapped():
                self.workspace_hscroll.pack_forget()
                canvas.xview_moveto(0)
        except Exception:
            pass

    def _workspace_watch(self):
        """V152: a altura pedida pelo conteúdo pode crescer sem que a janela mude (ex.: resultado de uma busca);
        confere de vez em quando e reajusta a área rolável para nada ficar espremido."""
        try:
            req = self.page_host.winfo_reqheight()
            if req != getattr(self, '_workspace_last_req', None):
                self._workspace_last_req = req
                self._sync_workspace_layout()
        except Exception:
            pass
        try: self.after(350, self._workspace_watch)
        except Exception: pass

    def _queue_workspace_layout(self):
        """V159: ao redimensionar a janela chegam dezenas de avisos por segundo; o layout é refeito uma vez só por rodada (sem tremer)."""
        if getattr(self, '_workspace_layout_job', None): return
        def run():
            self._workspace_layout_job = None
            self._sync_workspace_layout()
        try: self._workspace_layout_job = self.after_idle(run)
        except Exception: self._workspace_layout_job = None

    def _on_workspace_host_configure(self, event=None):
        self._queue_workspace_layout()

    def _on_workspace_canvas_configure(self, event):
        self._queue_workspace_layout()

    def _on_workspace_mousewheel(self, event):
        try:
            delta = -1 * int(event.delta / 120) if event.delta else 0
            if delta:
                self.workspace_canvas.yview_scroll(delta, 'units')
        except Exception:
            pass

    def _on_workspace_enter(self, event=None):
        pass

    def _on_workspace_leave(self, event=None):
        pass

    def _install_navigation_shortcuts(self):
        """V148: Ctrl+1..9 trocam de tela; F1 mostra a lista de atalhos."""
        order = [('nav_dashboard', self._show_dashboard), ('nav_sync', self._show_webservice_test), ('nav_documents', self._show_documents),
                 ('nav_companies', self._show_companies), ('nav_audit', self._show_audit), ('nav_pending', self._show_pending),
                 ('nav_history', self._show_history), ('nav_reports', self._show_reports), ('nav_cert', self._show_certificate_list)]
        order.append(('nav_nfse', self._show_nfse))
        self._nav_shortcut_labels = {}
        for number, (attr, handler) in enumerate(order, 1):
            number = number % 10   # o 10º item (NFS-e) usa Ctrl+0
            btn = getattr(self, attr, None)
            if btn is not None:
                self._nav_shortcut_labels[btn] = f'Ctrl+{number}'
            self.bind_all(f'<Control-Key-{number}>', lambda e, h=handler: (h(), 'break')[1], add='+')
        self.bind_all('<F1>', lambda e: (self._show_shortcuts_dialog(), 'break')[1], add='+')
        self.bind_all('<Control-Key-j>', lambda e: (self._chat_toggle(), 'break')[1], add='+')
        self.bind_all('<Control-Key-J>', lambda e: (self._chat_toggle(), 'break')[1], add='+')

    def _show_shortcuts_dialog(self):
        if getattr(self, '_shortcuts_win', None) is not None:
            try:
                self._shortcuts_win.lift(); return
            except Exception:
                self._shortcuts_win = None
        win = tk.Toplevel(self); self._shortcuts_win = win
        win.title('Atalhos de teclado'); win.configure(bg=BG); win.transient(self); win.resizable(False, False)
        win.bind('<Destroy>', lambda e: setattr(self, '_shortcuts_win', None) if e.widget is win else None)
        tk.Label(win, text='Atalhos de teclado', bg=BG, fg=TEXT, font=('Segoe UI Semibold', 14)).pack(anchor='w', padx=24, pady=(18, 2))
        tk.Label(win, text='Trabalhe sem tirar a mão do teclado.', bg=BG, fg=MUTED, font=('Segoe UI', 9)).pack(anchor='w', padx=24, pady=(0, 10))
        card = exato_ui.ModernCard(win, fill=WHITE, border=BORDER); card.pack(fill='x', padx=24, pady=(0, 18))
        rows = [('Ctrl+1', 'Início'), ('Ctrl+2', 'Buscar XML'), ('Ctrl+3', 'Documentos Fiscais'), ('Ctrl+4', 'Empresas'), ('Ctrl+5', 'Auditoria Fiscal'),
                ('Ctrl+6', 'Pendências'), ('Ctrl+7', 'Histórico'), ('Ctrl+8', 'Relatórios'), ('Ctrl+9', 'Certificado'), ('Ctrl+0', 'NFS-e'),
                ('Ctrl+K', 'Busca global'), ('Ctrl+J', 'Conversar com o Exatinho'), ('Ctrl+B', 'Buscar XML (atalho antigo)'), ('Ctrl+D', 'Documentos (atalho antigo)'), ('F1', 'Esta janela')]
        for i, (keys, what) in enumerate(rows):
            row = tk.Frame(card, bg=WHITE); row.pack(fill='x', padx=14, pady=(8 if i == 0 else 2, 8 if i == len(rows) - 1 else 2))
            tk.Label(row, text=keys, bg='#EEF2F7', fg=TEXT, font=('Segoe UI Semibold', 9), padx=8, pady=2, width=8).pack(side='left')
            tk.Label(row, text=what, bg=WHITE, fg=TEXT, font=('Segoe UI', 10)).pack(side='left', padx=12)
        ttk.Button(win, text='Fechar', style='Secondary.TButton', command=win.destroy).pack(anchor='e', padx=24, pady=(0, 16))
        win.update_idletasks()
        win.geometry(f"+{self.winfo_rootx() + max((self.winfo_width() - win.winfo_width()) // 2, 0)}+{self.winfo_rooty() + 60}")
        win.focus_set()

    def _rail_tip_schedule(self, btn):
        self._rail_tip_hide()
        if getattr(self, '_sidebar_mode', 'full') != 'rail':
            return
        self._rail_tip_job = self.after(350, lambda: self._rail_tip_show(btn))

    def _rail_tip_show(self, btn):
        self._rail_tip_job = None
        try:
            text = self._sidebar_nav_text.get(btn, '').split(None, 1)[1].strip()
            hint = getattr(self, '_nav_shortcut_labels', {}).get(btn)
            if hint: text += f'   ({hint})'
            tip = tk.Toplevel(self); tip.wm_overrideredirect(True); tip.configure(bg=DARK)
            tk.Label(tip, text=text, bg=DARK, fg=WHITE, font=('Segoe UI Semibold', 9), padx=10, pady=5).pack()
            tip.wm_geometry(f"+{btn.winfo_rootx() + btn.winfo_width() + 8}+{btn.winfo_rooty() + max((btn.winfo_height() - 28) // 2, 0)}")
            self._rail_tip_win = tip
        except Exception:
            self._rail_tip_win = None

    def _rail_tip_hide(self):
        job = getattr(self, '_rail_tip_job', None)
        if job:
            try: self.after_cancel(job)
            except Exception: pass
            self._rail_tip_job = None
        win = getattr(self, '_rail_tip_win', None)
        if win is not None:
            try: win.destroy()
            except Exception: pass
            self._rail_tip_win = None

    def _sidebar_nav_font(self, active=False):
        if getattr(self, '_sidebar_mode', 'full') == 'rail':
            return ("Segoe UI", 14)
        return ("Segoe UI Semibold", 10) if active else ("Segoe UI", 10)

    def _sidebar_apply_density(self, event=None):
        """V146: padrão responsivo do menu lateral.

        - largura da janela < RAIL_BELOW_WIDTH: menu compacto só com ícones (mais espaço para a página);
        - altura baixa (notebooks): some o título dos grupos e os itens ficam mais juntos;
        - altura muito baixa: o Exatinho do rodapé é ocultado. Nada é cortado.
        """
        try:
            h = int(self.sidebar.winfo_height()); w = int(self.winfo_width())
        except Exception:
            return
        if h <= 1 or w <= 1:
            return
        mode = 'rail' if w < RAIL_BELOW_WIDTH else 'full'
        level = 'normal' if h >= 650 else ('compact' if h >= 540 else 'tight')
        if (mode, level) == (getattr(self, '_sidebar_mode', 'full'), getattr(self, '_sidebar_density', '')) and getattr(self, '_sidebar_applied', False):
            return
        self._sidebar_applied = True
        self._sidebar_mode, self._sidebar_density = mode, level
        rail = mode == 'rail'
        self._sidebar_base_width = RAIL_WIDTH if rail else 232
        if not getattr(self, '_exatinho_sidebar_expanded', False):
            self.sidebar.configure(width=self._sidebar_base_width)
        # logo
        logo = getattr(self, 'sidebar_logo_label', None)
        if logo is not None:
            if rail and getattr(self, 'sidebar_mark_img', None) is not None:
                logo.config(image=self.sidebar_mark_img); logo.pack_configure(anchor='center')
            else:
                logo.config(image=self.sidebar_logo_img); logo.pack_configure(anchor='w')
        # títulos dos grupos
        for label, text in self._sidebar_labels:
            if level == 'normal' and not rail:
                label.config(text=text, font=('Segoe UI Semibold', 7)); label.pack_configure(pady=(8, 2))
            else:
                label.config(text='', font=('Segoe UI', 1)); label.pack_configure(pady=(4 if rail else (3 if level == 'compact' else 1), 0))
        # itens
        for btn in self._sidebar_navs:
            label = self._sidebar_nav_label.get(btn, '')
            if rail:
                btn.config(text='', compound='center', anchor='center', padx=0, pady={'normal': 8, 'compact': 5, 'tight': 3}[level], font=("Segoe UI", 10))
                btn.pack_configure(padx=8, pady=(1 if level != 'tight' else 0))
            else:
                btn.config(text='  ' + label, compound='left', anchor='w', padx=14, pady={'normal': 6, 'compact': 3, 'tight': 1}[level], font=("Segoe UI", 10))
                btn.pack_configure(padx=12, pady=(1 if level != 'tight' else 0))
        try:
            self._set_active_nav(getattr(self, 'current_screen', ''))
        except Exception:
            pass
        # rodapé com o Exatinho
        # rodapé com o Exatinho: no menu de ícones aparece só o mascote (clique abre o painel)
        try:
            if level == 'tight':
                self.sidebar_footer.pack_forget()
            else:
                self.sidebar_footer.pack_configure(padx=(4 if rail else 12))
                if not self.sidebar_footer.winfo_ismapped():
                    self.sidebar_footer.pack(side='bottom', fill='x', padx=(4 if rail else 12), pady=12)
            bubble = self.ia_float_bubble
            if rail and bubble.winfo_manager():
                bubble.pack_forget()
            elif not rail and not bubble.winfo_manager():
                bubble.pack(side='left', fill='x', expand=True, anchor='center')
            self.ia_float_img.pack_configure(padx=(0 if rail else 0, 0 if rail else 4))
        except Exception:
            pass
        try: self._update_pending_badge(getattr(self,'_pending_total',0))
        except Exception: pass
        # busca rápida do topo
        try:
            self.header_search.config(text='' if rail else ' Buscar...    Ctrl+K')
        except Exception:
            pass

    def _sidebar_section(self, text):
        label=tk.Label(self.sidebar,text=text,bg=SIDEBAR_BG,fg=SIDEBAR_MUTED,font=('Segoe UI Semibold',7),anchor='w')
        label.pack(fill='x',padx=22,pady=(8,2))
        self._sidebar_labels.append((label,text))
        return label

