    def _make_nav(self, text, command):
        glyph = text.split()[0]; label = text[len(glyph):].strip()
        btn=tk.Button(self.sidebar,text='  '+label,command=command,relief="flat",bd=0,anchor="w",compound='left',
                      bg=SIDEBAR_BG,fg=SIDEBAR_TEXT,activebackground=SIDEBAR_HOVER,activeforeground=WHITE,
                      font=("Segoe UI",10),padx=14,pady=6,cursor="hand2", highlightthickness=0)
        self.__dict__.setdefault('_sidebar_nav_label', {})[btn] = label
        btn.config(image=self._nav_icon(btn, False)); btn._icon_ref = btn.cget('image')
        bar = tk.Frame(btn, bg=RED, width=3); btn._accent_bar = bar
        btn.pack(fill="x", padx=12, pady=1)
        self._sidebar_navs.append(btn); self._sidebar_nav_text[btn]=text
        btn.bind('<Enter>',lambda e,b=btn:self._rail_tip_schedule(b),add='+'); btn.bind('<Leave>',lambda e:self._rail_tip_hide(),add='+'); btn.bind('<Button-1>',lambda e:self._rail_tip_hide(),add='+')
        btn.bind('<Enter>',lambda e,b=btn:(b.config(bg=SIDEBAR_HOVER) if b.cget('bg')!=NAV_ACTIVE else None),add='+')
        btn.bind('<Leave>',lambda e,b=btn:(b.config(bg=SIDEBAR_BG) if b.cget('bg')!=NAV_ACTIVE else None),add='+')
        return btn

    def _hide_all_frames(self):
        for name in ('nfse_frame','cert_frame','test_frame','dashboard_frame','companies_frame','documents_frame','reports_frame','pending_frame','history_frame','audit_frame','maintenance_frame','users_frame'):
            frame=getattr(self,name,None)
