    def _show_frame(self, frame, active):
        self._hide_all_frames()
        frame.pack(fill="both",expand=True,padx=(24 if getattr(self, "compact_ui", True) else 32),pady=(16 if getattr(self, "compact_ui", True) else 22))
        self.current_screen=active; self._set_active_nav(active); self._ia_float_on_screen(active); self.after(250,self._update_pending_badge)
        try: self._ia_emit_event('NAVIGATED',screen=active)
        except Exception: pass
        def reset_scroll():
            self._reset_scroll_job = None
            try:
                self._wheel.stop()
                self._sync_workspace_layout()
                self.workspace_canvas.yview_moveto(0)
            except Exception:
                pass
        # V148: uma única tarefa por troca de tela (antes eram duas, cada uma forçando um novo cálculo de layout)
        job = getattr(self, '_reset_scroll_job', None)
        if job is not None:
            try: self.after_cancel(job)
            except Exception: pass
        self._reset_scroll_job = self.after(40, reset_scroll)

