    def _cert_set_filter(self, key):
        self._cert_filter = key
        for k, chip in getattr(self, '_cert_chips', {}).items():
            if k == key:
                chip.config(bg=DARK, fg=WHITE, highlightbackground=DARK)
            else:
                chip.config(bg=WHITE, fg=MUTED, highlightbackground=BORDER)
        self._cert_apply_filter()

    @staticmethod
    def _cert_days_left(cert):
        try:
            dt = datetime.fromisoformat(str(cert.get("NotAfter", "")).replace("Z", "+00:00")).replace(tzinfo=None)
            return (dt - datetime.now()).days
        except Exception:
            return None

    def _cert_apply_filter(self):
        """Mostra apenas os certificados que combinam com a busca e o filtro, preservando a ordem alfabética."""
        tree = getattr(self, 'tree', None)
        certs = getattr(self, 'certificates', None) or []
        if tree is None:
            return
        if not certs:
            if getattr(self, '_cert_loaded_once', False):
                self._set_empty_state(tree, True, 'Nenhum certificado válido encontrado', 'Instale o certificado digital no Windows e clique em Atualizar.', 'Atualizar', self.refresh_certificates)
            return
        query = _normalize_search_text(self._cert_query.get()) if hasattr(self, '_cert_query') else ''
        digits = re.sub(r'\D', '', self._cert_query.get()) if hasattr(self, '_cert_query') else ''
        mode = getattr(self, '_cert_filter', 'all')
        selected_iid = tree.selection()
        shown = 0
        for idx, cert in enumerate(certs):
            iid = str(idx)
            if not tree.exists(iid):
                continue
            text = _normalize_search_text(f"{cert.get('FriendlyName') or ''} {cert.get('Subject') or ''}")
            doc_digits = re.sub(r'\D', '', str(cert.get('Document') or ''))
            ok = (not query or query in text) or bool(digits and digits in doc_digits)
            if ok and mode == 'token':
                ok = 'a3' in str(cert.get('TypeGuess') or '').lower() or 'token' in str(cert.get('TypeGuess') or '').lower()
            elif ok and mode == 'expiring':
                left = self._cert_days_left(cert)
                ok = left is not None and left <= 60
            if ok:
                tree.reattach(iid, '', shown)
                shown += 1
            else:
                tree.detach(iid)
        if hasattr(self, 'cert_count_label'):
            self.cert_count_label.config(text=f"{shown} de {len(certs)} certificado(s) válido(s) exibido(s)")
        if shown:
            self._set_empty_state(tree, False)
        else:
            self._set_empty_state(tree, True, 'Nenhum certificado encontrado', 'Nenhum certificado combina com a busca ou o filtro escolhido.')

    def _show_certificate_header_state(self):
        try:
            if getattr(self, 'nfse_frame', None) is not None:
                self._nfse_sync_company_from_certificate(); self._nfse_update_cert_label(); self._nfse_update_company_hint()
        except Exception:
            pass
        if hasattr(self, "header_context"):
            if self.selected:
                subject = self._nfse_cert_name(self.selected)
                left = self._cert_days_left(self.selected)
                if left is not None and left <= 30:
                    self.header_context.config(text=f"Cert.: {subject[:40]} • vence em {max(left, 0)} dia(s)", fg="#B45309" if left > 7 else RED)
                else:
                    self.header_context.config(text=f"Cert.: {subject[:62]}", fg=MUTED)
            else:
                self.header_context.config(text="Certificado não selecionado", fg=MUTED)

    def _set_active_nav(self, active):
        buttons={"cert":getattr(self,"nav_cert",None),"nfse":getattr(self,"nav_nfse",None),"sync":getattr(self,"nav_sync",None),"dashboard":getattr(self,"nav_dashboard",None),"companies":getattr(self,"nav_companies",None),"documents":getattr(self,"nav_documents",None),"reports":getattr(self,"nav_reports",None),"pending":getattr(self,"nav_pending",None),"history":getattr(self,"nav_history",None),"audit":getattr(self,"nav_audit",None),"users":getattr(self,"nav_users",None),"maintenance":getattr(self,"nav_maintenance",None)}
        for key,btn in buttons.items():
            if btn is None: continue
            on = key==active
            if on: btn.config(bg=NAV_ACTIVE,fg=WHITE,activebackground=NAV_ACTIVE,font=self._sidebar_nav_font(True))
            else: btn.config(bg=SIDEBAR_BG,fg=SIDEBAR_TEXT,activebackground=SIDEBAR_HOVER,font=self._sidebar_nav_font(False))
            try:
                btn.config(image=self._nav_icon(btn,on)); btn._icon_ref=btn.cget('image')
                bar=getattr(btn,'_accent_bar',None)
                if bar is not None:
                    if on: bar.place(x=0,y=8,width=3,relheight=1.0,height=-16); bar.lift()
                    else: bar.place_forget()
            except Exception: pass
        try:
            names={"cert":"Certificado","nfse":"NFS-e","sync":"Buscar XML","dashboard":"Início","companies":"Empresas","documents":"Documentos Fiscais","reports":"Relatórios","pending":"Pendências","history":"Histórico","audit":"Auditoria Fiscal","users":"Usuários","maintenance":"Manutenção"}
            if hasattr(self,'header_crumb'): self.header_crumb.config(text=names.get(active,''))
        except Exception: pass

