    def _refresh_processing_center(self, results=None):
        labels=getattr(self,'processing_labels',{})
        if not labels: return
        if getattr(self,'sync_running',False):
            for fam in ('nfe','nfce','cte'):
                if fam in labels: labels[fam].config(text='Em andamento',fg=BLUE)
            if 'nfe' in labels: labels['nfe'].config(text='Entrada + Saída em consulta',fg=BLUE)
            return
        results=results or {}
        for fam in ('nfe','nfce','cte'):
            label=labels.get(fam)
            if not label: continue
            rr=results.get(fam) or {}
            if fam=='nfe':
                if rr.get('deferred_actor'):
                    nxt=str(rr.get('deferred_label') or 'próximo fluxo')
                    color=ORANGE if int(rr.get('cooldown_remaining') or 0)>0 else GREEN
                    label.config(text=f'Pronto • próximo: {nxt}',fg=color)
                elif rr.get('ok'):
                    label.config(text='Entrada + Saída concluídas',fg=GREEN)
                elif rr:
                    label.config(text='Concluído com observações',fg=ORANGE)
                else:
                    label.config(text='Pronto para consulta',fg=MUTED)
            else:
                if rr.get('ok'): label.config(text='Concluído',fg=GREEN)
                elif rr: label.config(text='Concluído com observações',fg=ORANGE)
                else: label.config(text='Pronto para consulta',fg=MUTED)

    def _open_global_search_dialog(self):
        if getattr(self,'_global_search_win',None) is not None and self._global_search_win.winfo_exists():
            self._global_search_win.deiconify(); self._global_search_win.lift(); self._global_search_entry.focus_set(); self._global_search_entry.select_range(0,'end'); return
        win=tk.Toplevel(self); self._global_search_win=win; win.title('Busca global — Exato Central Fiscal'); win.geometry('980x560'); win.configure(bg=BG); win.transient(self)
        head=tk.Frame(win,bg=DARK); head.pack(fill='x')
        tk.Label(head,text='BUSCA GLOBAL',bg=DARK,fg=WHITE,font=('Segoe UI Semibold',12)).pack(side='left',padx=14,pady=10)
        tk.Label(head,text='Número • chave • empresa • tipo',bg=DARK,fg='#CBD5E1',font=('Segoe UI',8)).pack(side='left',padx=(0,10))
        body=tk.Frame(win,bg=BG); body.pack(fill='both',expand=True,padx=14,pady=14)
        search_row=tk.Frame(body,bg=BG); search_row.pack(fill='x',pady=(0,8))
        self._global_search_entry=ttk.Entry(search_row,font=('Segoe UI',11)); self._global_search_entry.pack(side='left',fill='x',expand=True,ipady=4); self._global_search_entry.bind('<Return>',lambda _e:self._run_global_search())
        ttk.Button(search_row,text='PESQUISAR',style='Primary.TButton',command=self._run_global_search).pack(side='left',padx=(8,0))
        quick=tk.Frame(body,bg=BG); quick.pack(fill='x',pady=(0,4))
        tk.Label(quick,text='Atalhos rápidos:',bg=BG,fg=MUTED,font=('Segoe UI Semibold',8)).pack(side='left')
        for label,cmd in [('Pendências',self._show_pending),('Documentos',self._show_documents),('Histórico',self._show_history)]:
            tk.Button(quick,text=label,command=cmd,bg='#E8EEF6',fg=TEXT,relief='flat',bd=0,cursor='hand2',font=('Segoe UI Semibold',7),padx=7,pady=3).pack(side='left',padx=(5,0))
        self._global_search_status=tk.Label(body,text='Digite número, chave, empresa, tipo ou valor para pesquisar na base local.',bg=BG,fg=MUTED,font=('Segoe UI',8)); self._global_search_status.pack(anchor='w',pady=(0,6))
        wrap=exato_ui.ModernCard(body, fill=WHITE, border=BORDER); wrap.pack(fill='both',expand=True)
        cols=('tipo','numero','empresa','direcao','data','valor','situacao'); self._global_search_tree=ttk.Treeview(wrap,columns=cols,show='headings',selectmode='browse')
        heads={'tipo':'Tipo','numero':'Nº','empresa':'Empresa','direcao':'Movimentação','data':'Emissão','valor':'Valor','situacao':'Situação'}; widths={'tipo':90,'numero':100,'empresa':340,'direcao':110,'data':105,'valor':110,'situacao':125}
        for c in cols: self._global_search_tree.heading(c,text=heads[c]); self._global_search_tree.column(c,width=widths[c],anchor='w')
        self._global_search_tree.column('numero',anchor='center'); self._global_search_tree.column('direcao',anchor='center'); self._global_search_tree.column('data',anchor='center'); self._global_search_tree.column('valor',anchor='e'); self._global_search_tree.column('situacao',anchor='center')
        self._global_search_tree.pack(side='left',fill='both',expand=True,padx=(4,0),pady=4); sc=ttk.Scrollbar(wrap,orient='vertical',command=self._global_search_tree.yview); self._global_search_tree.configure(yscrollcommand=sc.set); sc.pack(side='right',fill='y',padx=(0,4),pady=4)
        self._global_search_map={}; self._global_search_tree.bind('<Double-1>',self._global_search_open)
        self._global_search_entry.focus_set()

    def _run_global_search(self):
        q=self._global_search_entry.get().strip() if hasattr(self,'_global_search_entry') else ''
        for iid in self._global_search_tree.get_children(): self._global_search_tree.delete(iid)
        if not q:
            self._global_search_status.config(text='Digite número, chave, empresa ou tipo documental.')
            return
        try: rows=[r for r in db_list_documents(query=q,limit=2500) if r.get('status')!='Evento']  # V145: evento não é documento
        except Exception as exc:
            self._global_search_status.config(text=f'Erro na busca: {exc}',fg=RED); return
        self._global_search_map={}
        for i,r in enumerate(rows,1):
            iid=f'g_{i}'; self._global_search_map[iid]=r
            self._global_search_tree.insert('', 'end', iid=iid, values=(r.get('doc_type') or '—',r.get('number') or '—',r.get('company_name') or r.get('cnpj') or '—',r.get('direction') or '—',_format_user_date(r.get('issued_at')), _format_brl(r.get('value')),r.get('status') or '—'))
        self._global_search_status.config(text=f'{len(rows):,} resultado(s) encontrado(s).'.replace(',','.'),fg=GREEN if rows else MUTED)

    def _global_search_open(self,event=None):
        sel=self._global_search_tree.selection() if hasattr(self,'_global_search_tree') else ()
        row=self._global_search_map.get(sel[0]) if sel else None
        if not row: return
        try:
            path=open_document_fiscal_representation(row); self.set_status(f'Representação fiscal aberta: {Path(path).name}')
        except Exception as exc:
            messagebox.showerror('Representação fiscal',str(exc))

    def _refresh_documents_dashboard_visuals(self):
        """Refresh the capture dashboard using only documents inside the selected period."""
        try:
            docs=list(getattr(self,'last_documents',[]) or [])
            df,dt=getattr(self,'_capture_period_snapshot',('',''))
            docs=self._filter_documents_for_capture_view(docs,df,dt)
            total=len(docs)
            direction_counts={family:{'Entrada':0,'Saída':0} for family in ('nfe','nfce','cte')}
            family_counts={family:0 for family in ('nfe','nfce','cte')}
            for d in docs:
                fam=str(d.get('family') or d.get('doc_type') or '').casefold()
                fam_map={'nfe':'nfe','nfeproc':'nfe','nf-e':'nfe','nfce':'nfce','nfceproc':'nfce','nfc-e':'nfce','cte':'cte','cteproc':'cte'}
                fam=fam_map.get(fam,fam)
                if fam not in family_counts: continue
                family_counts[fam]+=1
                direction=str(d.get('direction') or d.get('direcao') or 'Entrada')
                if direction not in ('Entrada','Saída'): direction='Entrada'
                direction_counts[fam][direction]+=1
            for fam in ('nfe','nfce','cte'):
                if fam in getattr(self,'sync_card_counts',{}):
                    self.sync_card_counts[fam].config(text=f"{family_counts[fam]:,}".replace(',','.'))
                if fam in getattr(self,'sync_card_direction_counts',{}):
                    self.sync_card_direction_counts[fam].config(text=f"Entrada: {direction_counts[fam]['Entrada']}  •  Saída: {direction_counts[fam]['Saída']}")
            if hasattr(self,'total_docs_label'):
                self.total_docs_label.config(text=f'{total:,}'.replace(',','.'))
            if hasattr(self,'sync_summary_labels'):
                self.sync_summary_labels['presented'].config(text=f'{total:,}'.replace(',','.'))
                self.sync_summary_labels['new'].config(text=str(getattr(self,'_last_sync_new_count',0)))
                self.sync_summary_labels['existing'].config(text=str(getattr(self,'_last_sync_duplicate_count',0)))
            self._refresh_processing_center()
            if hasattr(self,'sync_completion_label'):
                state=getattr(self,'_last_sync_status','Pronto para consulta')
                color=GREEN if state in ('Concluído','Pronto para consulta') else ORANGE
                bg='#ECFDF3' if state in ('Concluído','Pronto para consulta') else '#FFFAEB'
                self.sync_completion_label.config(text='●  '+state,fg=color,bg=bg)
            if not hasattr(self,'docs_chart_canvas'): return
            cv=self.docs_chart_canvas; cv.delete('all'); cv.update_idletasks(); w=max(cv.winfo_width(),420); h=120
            counts={}
            for d in docs:
                date=str(d.get('data') or d.get('issued_at') or '')[:10]
                if date: counts[date]=counts.get(date,0)+1
            dates=sorted(counts)
            if not dates:
                cv.create_text(w/2,45,text='Nenhum documento no período',fill=MUTED,font=('Segoe UI',9)); return
            if len(dates)>31: dates=dates[-31:]
            maxv=max((counts.get(d,0) for d in dates),default=1) or 1
            left=12; right=w-10; bottom=h-24; chart_h=h-42; slot=(right-left)/max(1,len(dates)); bar_w=max(5,slot-3)
            for i,d in enumerate(dates):
                x=left+i*slot; bh=(counts.get(d,0)/maxv)*chart_h
                cv.create_rectangle(x,bottom-bh,x+bar_w,bottom,fill=NFCE_ACCENT,outline='')
                if i in (0,len(dates)//2,len(dates)-1):
                    cv.create_text(x+bar_w/2,bottom+11,text=_format_user_date(d)[:5],fill=MUTED,font=('Segoe UI',7))
            cv.create_line(left,bottom,right,bottom,fill='#E4E7EC')
            if hasattr(self,'docs_chart_subtitle'):
                self.docs_chart_subtitle.config(text=f'{maxv} documento(s) no dia de maior movimentação.' if maxv else 'Distribuição dos documentos encontrados no período.')
        except Exception:
            pass


    def _confirm_period(self):
        try:
            df,dt=self._get_capture_period()
        except ValueError as exc:
            messagebox.showerror('Período inválido',str(exc)); return
        if not df and not dt:
            label='Todo o período disponível'
        else:
            label=self._capture_period_label(df,dt)
        self._capture_period_snapshot=(df,dt)
        if hasattr(self,'sync_outside_period_label'): self.sync_outside_period_label.pack_forget()
        self._period_confirmed=True
        self.period_status.config(text=f'Período selecionado: {label}',fg=GREEN)
        self.progress_title.config(text='Período confirmado. Pronto para buscar XML')
        self.progress_subtitle.config(text=f'Os documentos serão consultados para {label.lower()}.')
        self._set_sync_controls(False)
        self._refresh_local_archive_status(self.cnpj_var.get().strip() if hasattr(self,'cnpj_var') else '')
        local_period_count=db_document_count(self.cnpj_var.get().strip(),df,dt) if getattr(self,'_cnpj_confirmed',False) else 0
        if local_period_count:
            self._write_result(f'Período selecionado: {label}.\n\nA Central já possui {local_period_count:,} documento(s) armazenado(s) neste período. Você pode clicar em “SALVAR XMLs + PDFs” sem fazer uma nova busca.\n\nSe quiser atualizar a base, clique em BUSCAR XML para consultar somente as novidades.'.replace(',','.'))
        else:
            self._write_result(f'Período selecionado: {label}.\n\nAgora clique em BUSCAR XML para consultar os documentos disponíveis.')
        self.set_status(f'Período selecionado: {label}.')

    def _get_capture_period(self):
        if not hasattr(self,'capture_from') or not hasattr(self,'capture_to'):
            return '',''
        df=_parse_user_date(self.capture_from.get(),'data inicial da captura') if self.capture_from.get().strip() else ''
        dt=_parse_user_date(self.capture_to.get(),'data final da captura') if self.capture_to.get().strip() else ''
        if df and dt and df>dt:
            raise ValueError('A data inicial da captura não pode ser maior que a data final.')
        return df,dt

    def _filter_documents_for_capture_view(self, documents, date_from='', date_to=''):
        docs=list(documents or [])
        if not date_from and not date_to:
            return docs
        out=[]
        for doc in docs:
            d=str(doc.get('data') or doc.get('issued_at') or '')[:10]
            if not d:
                continue
            if date_from and d<date_from: continue
            if date_to and d>date_to: continue
            out.append(doc)
        return out

    def _capture_period_label(self, date_from='', date_to=''):
        if not date_from and not date_to:
            return 'Todos os documentos disponíveis'
        left=_format_user_date(date_from) if date_from else 'início'
        right=_format_user_date(date_to) if date_to else 'fim'
        return f'{left} até {right}'

    def _refresh_local_archive_status(self, cnpj=None):
        if not hasattr(self,'local_archive_status'):
            return
        digits=re.sub(r'\D','',str(cnpj if cnpj is not None else (self.cnpj_var.get().strip() if hasattr(self,'cnpj_var') else '')))
        if len(digits)!=14:
            self.local_archive_status.config(text='Nenhum documento armazenado localmente.',fg=MUTED)
            self.local_archive_detail.config(text='Depois da captura, os XMLs permanecem dentro da Central e podem ser exportados quando você quiser.')
            if hasattr(self,'local_archive_save_btn'): self.local_archive_save_btn.config(state='disabled')
            return
        try:
            total=db_get_stats(digits).get('authorized',0)
            runs=db_list_runs(1,digits)
            last_sync=(runs[0].get('finished_at') or runs[0].get('started_at') or '') if runs else ''
            if last_sync:
                last_sync=_format_user_date(last_sync[:10])+' '+last_sync[11:16] if len(last_sync)>=16 else last_sync.replace('T',' ')
            self.local_archive_status.config(text=(f'{int(total):,} documento(s) armazenado(s) localmente • disponíveis após fechar e reabrir a Central.').replace(',','.'),fg=GREEN if total else MUTED)
            self.local_archive_detail.config(text='Última captura: '+(last_sync or 'ainda não realizada')+' • Salvar depois não exige nova busca.')
            if hasattr(self,'local_archive_save_btn'):
                df,dt=getattr(self,'_capture_period_snapshot',('',''))
                ready=bool(getattr(self,'_cnpj_confirmed',False) and getattr(self,'_period_confirmed',False))
                period_count=db_document_count(digits,df,dt) if ready else 0
                self.local_archive_save_btn.config(state='normal' if ready and period_count>0 else 'disabled')
        except Exception:
            self.local_archive_status.config(text='Documentos armazenados localmente.',fg=MUTED)
            self.local_archive_detail.config(text='Os documentos podem permanecer disponíveis mesmo após reiniciar o programa.')


    def _load_persisted_company_state(self, cnpj=None):
        """Load documents already stored locally for the selected company.
        This keeps the Central persistent across application restarts: synchronization
        only fetches novelties, while the local index remains the source for reports
        and organized export.
        """
        digits = re.sub(r'\D', '', str(cnpj if cnpj is not None else self.cnpj_var.get().strip()))
        if len(digits) != 14:
            self.last_documents = []
            self._reset_sync_cards()
            if hasattr(self, 'save_btn'): self.save_btn.config(state='disabled')
            if hasattr(self, 'pdf_btn'): self.pdf_btn.config(state='disabled')
            if hasattr(self,'local_archive_save_btn'): self.local_archive_save_btn.config(state='disabled')
            self._refresh_local_archive_status(digits)
            return []
        # Repair stale company names left by previous versions using the documents
        # actually tied to the consulted CNPJ.
        try:
            local_name = db_reconcile_company_name(digits, limit=100)
        except Exception:
            local_name = ''
        docs = db_load_documents_as_payload(digits, limit=100000)
        if local_name and local_name not in {f'Empresa_{digits}','Empresa não identificada'} and getattr(self, 'cnpj_confirmed', '') == digits:
            self.sync_company_label.config(text=f'Empresa: {local_name}', fg=TEXT)
            if hasattr(self,'cnpj_name_label'):
                self.cnpj_name_label.config(text='✓ Empresa identificada a partir dos documentos fiscais', fg=GREEN)
            if hasattr(self,'sync_company_header'):
                self.sync_company_header.config(text=local_name)
                self.sync_company_header_doc.config(text=_format_cnpj(digits))
        self.last_documents = list(docs)
        self._refresh_documents_dashboard_visuals()
        for family in ('nfe','nfce','cte'):
            count = db_family_document_count(digits, family)
            self._update_sync_card(family, count, 'Disponível' if count else 'Sem documentos')
        # The cards are contextual to the selected period; refresh their family and
        # Entrada/Saída counts from the same period-scoped document set.
        self._refresh_documents_dashboard_visuals()
        total = len(docs)
        if hasattr(self, 'total_docs_label'):
            self.total_docs_label.config(text=f'Total: {total:,} documentos'.replace(',', '.'))
        if hasattr(self, 'progress_title'):
            self.progress_title.config(text='Documentos disponíveis na Central' if total else 'Pronto para buscar XML')
        if hasattr(self, 'progress_subtitle'):
            self.progress_subtitle.config(text=(f'{total:,} documento(s) já armazenado(s). A próxima atualização buscará somente novidades.' if total else 'A Central Fiscal cuidará da atualização automaticamente.').replace(',', '.'))
        if hasattr(self, 'test_result') and total:
            self._write_result(f'Empresa carregada da Central.\n\nDocumentos armazenados: {total:,}\n\nOs arquivos permanecem disponíveis mesmo após fechar e reabrir o programa. Clique em “BUSCAR XML” para buscar apenas documentos novos.'.replace(',', '.'))
        if hasattr(self, 'sync_all_btn'): self._set_sync_controls(False)
        self._refresh_local_archive_status(digits)
        return docs

    def _open_active_company_menu(self):
        companies=db_list_companies(200)
        if not companies:
            messagebox.showinfo('Empresa ativa','Nenhuma empresa cadastrada na Central Fiscal ainda.')
            return
        menu=tk.Menu(self,tearoff=0)
        current=re.sub(r'\D','',self.cnpj_var.get().strip())
        for row in companies:
            cnpj=re.sub(r'\D','',str(row.get('cnpj') or ''))
            name=str(row.get('name') or cnpj)
            label=f'{name}  •  {_format_cnpj(cnpj)}'
            menu.add_command(label=label,command=lambda c=cnpj:self._activate_registered_company(c))
        try:
            x=self.sync_company_switch.winfo_rootx()+self.sync_company_switch.winfo_width()-260
            y=self.sync_company_switch.winfo_rooty()+self.sync_company_switch.winfo_height()
            menu.tk_popup(x,y)
        finally:
            menu.grab_release()

    def _activate_registered_company(self, cnpj):
        digits=re.sub(r'\D','',str(cnpj or ''))
        if len(digits)!=14: return
        self.cnpj_var.set(digits)
        self._on_cnpj_changed()
        self._confirm_cnpj()

    def _confirm_cnpj(self, event=None):
        raw=self.cnpj_var.get().strip()
        digits=re.sub(r'\D','',raw)
        if len(digits)!=14:
            self.cnpj_status_label.config(text='CNPJ inválido', fg='#B91C1C')
            self.cnpj_name_label.config(text='')
            messagebox.showerror('CNPJ inválido','Informe um CNPJ válido com 14 dígitos antes de continuar.')
            return 'break'
        if not _is_valid_cnpj(digits):
            self.cnpj_status_label.config(text='CNPJ inválido', fg='#B91C1C')
            self.cnpj_name_label.config(text='')
            messagebox.showerror('CNPJ inválido','Confira os números informados. O CNPJ não passou na validação de seus dígitos verificadores.')
            return 'break'

        # O CNPJ é confirmado independentemente do nome empresarial. O nome é uma
        # informação complementar procurada automaticamente em segundo plano.
        self._active_cnpj_snapshot=digits
        self.cnpj_confirmed=digits
        self.cnpj_status_label.config(text='✓ CNPJ confirmado', fg=GREEN)
        self.cnpj_name_label.config(text='Buscando nome da empresa automaticamente...', fg=BLUE)
        if hasattr(self,'sync_company_header'):
            self.sync_company_header.config(text='Empresa em identificação...')
            self.sync_company_header_doc.config(text=_format_cnpj(digits))
        self.sync_company_label.config(text='Nome da empresa: identificando...', fg=BLUE)
        self._set_cnpj_confirmed(True)
        self._load_persisted_company_state(digits)
        self.set_status('CNPJ confirmado. Identificando automaticamente o nome da empresa...')

        try:
            local_name=db_reconcile_company_name(digits, limit=200) or db_get_company_name(digits) or str((self.config_data.get('company_names') or {}).get(digits) or '').strip()
        except Exception:
            local_name=db_get_company_name(digits)
        if local_name and local_name not in {f'Empresa_{digits}','Empresa não identificada'}:
            self._finish_company_name_lookup(digits, {'ok':True,'name':local_name,'fantasy':'','status':'','source':'cadastro local','error':''})
            return 'break'

        def worker(snapshot):
            result=lookup_company_name_automatic(snapshot)
            self.after(0, lambda:self._finish_company_name_lookup(snapshot, result))
        threading.Thread(target=worker, args=(digits,), daemon=True).start()
        return 'break'

    def _finish_company_name_lookup(self, digits, result):
        current=re.sub(r'\D','',self.cnpj_var.get().strip())
        if current != digits or getattr(self,'cnpj_confirmed','') != digits:
            return
        name=str(result.get('name') or '').strip()
        if name:
            try: db_set_company_name(digits, name)
            except Exception: pass
            self.sync_company_label.config(text=f'Empresa: {name}', fg=TEXT)
            self.cnpj_name_label.config(text='✓ Empresa identificada automaticamente', fg=GREEN)
            if hasattr(self,'sync_company_header'):
                self.sync_company_header.config(text=name)
                self.sync_company_header_doc.config(text=_format_cnpj(digits))
            self.set_status(f'Empresa identificada: {name}. Selecione o período dos documentos.')
            return

        self.sync_company_label.config(text='Empresa: nome ainda não identificado', fg='#D97706')
        self.cnpj_name_label.config(text='CNPJ confirmado. O nome da empresa ainda não foi identificado.', fg='#D97706')
        if hasattr(self,'sync_company_header'):
            self.sync_company_header.config(text='Nome ainda não identificado')
            self.sync_company_header_doc.config(text=_format_cnpj(digits))
        self.set_status('CNPJ confirmado. O nome da empresa ainda não foi identificado; a consulta pode continuar.')

    def _set_cnpj_confirmed(self, confirmed):
        self._cnpj_confirmed=bool(confirmed)
        if hasattr(self,'cnpj_confirm_btn'):
            raw=re.sub(r'\D','',self.cnpj_var.get().strip())
            if confirmed:
                self.cnpj_confirm_btn.config(text='✓  CNPJ CONFIRMADO', state='disabled', style='Secondary.TButton')
            else:
                self.cnpj_confirm_btn.config(text='✓  CONFIRMAR CNPJ', state=('normal' if len(raw)==14 else 'disabled'), style='Primary.TButton')
        if hasattr(self,'capture_from_entry'):
            state='normal' if confirmed else 'disabled'
            self.capture_from_entry.config(state=state)
            self.capture_to_entry.config(state=state)
            self.period_confirm_btn.config(state=state)
            if hasattr(self,'auto_checkbutton'):
                self.auto_checkbutton.config(state=state)
            if hasattr(self,'pdf_auto_checkbutton'):
                self.pdf_auto_checkbutton.config(state=state)
            if confirmed:
                self.period_status.config(text='CNPJ confirmado. Informe o período dos documentos e clique em CONTINUAR.',fg=BLUE)
            else:
                self.period_status.config(text='Confirme o CNPJ da empresa para liberar esta etapa.',fg=MUTED)
                self._period_confirmed=False
        if not confirmed:
            self._period_confirmed=False
            self._set_sync_controls(False)

    def _on_cnpj_changed(self, event=None):
        raw=self.cnpj_var.get().strip(); digits=re.sub(r'\D','',raw)
        if digits != raw:
            self.cnpj_var.set(digits)
            digits=self.cnpj_var.get().strip()
        self._cnpj_confirmed=False
        self.cnpj_status_label.config(text=('Informe um CNPJ válido' if len(digits)!=14 else 'Pronto para confirmar'), fg=(MUTED if len(digits)!=14 else BLUE))
        self.sync_company_label.config(text='')
        if hasattr(self,'cnpj_name_label'):
            self.cnpj_name_label.config(text='')
        self._set_cnpj_confirmed(False)
        self.last_documents=[]
        self._reset_sync_cards()
        if hasattr(self,'sync_company_header'):
            self.sync_company_header.config(text='Nenhuma empresa confirmada')
            self.sync_company_header_doc.config(text=_format_cnpj(digits) if len(digits)==14 else '')
        if self.sync_running:
            return
        if getattr(self,'_active_cnpj_snapshot','') and digits != self._active_cnpj_snapshot:
            self.pending_syncs={}; self.last_response_info=None
        self._active_cnpj_snapshot=''
        self.set_status('CNPJ alterado. Confirme novamente para continuar.')

    def _refresh_nsu_from_saved(self):
        return

    def _close_webservice_test(self):
        self.last_response_info = None
        self.last_audit_result = None
        self.audit_sat_file = ''
        self.audit_source_files = []
        self._show_certificate_list()
        self.set_status("Certificados disponíveis.")

    def _run_webservice_test(self, ind_xml=0):
        cnpj=self.cnpj_var.get().strip();thumb=(self.selected.get('Thumbprint') or '').replace(' ','').upper();nsu='0'
        wait,control=nfe_cooldown_remaining(self.config_data,cnpj)
        if wait>0:
            next_actor=str(control.get('next_actor') or '1'); next_label,_=nfe_actor_meta(next_actor)
            messagebox.showinfo('NF-e — intervalo de segurança',f'A SEF/SC informou um intervalo de segurança para este CNPJ.\n\nPróximo fluxo: {next_label}.\nDisponível novamente em aproximadamente {_format_nfe_wait(wait)}.\n\nA Central não fará uma nova requisição agora para evitar novo bloqueio por consumo indevido.')
            return
        actor=choose_nfe_actor(self.config_data,cnpj)
        actor_label,_=nfe_actor_meta(actor)
        self.test_btn.config(state='disabled');self.xml_btn.config(state='disabled')
        self.test_result.config(state='normal');self.test_result.delete('1.0','end');self.progress_title.config(text='Consultando documentos...'); self.progress_subtitle.config(text='Aguarde enquanto o sistema consulta a SEF/SC.'); self._show_progress_bar(); self.progress_bar.start(10); self.test_result.insert('1.0','Conectando à SEF/SC e consultando os documentos...');self.test_result.config(state='disabled')
        self.set_status(f'Consultando Web Service NF-e da SEF/SC ({actor_label})...')
        homolog=bool(self.hom_var.get())
        def worker():
            ok,result,info=test_sef_nfe_webservice(thumb,cnpj,homologacao=homolog,ind_xml=ind_xml,ult_nsu=nsu,ind_ator=int(actor))
            cstat=str((info or {}).get('cstat') or '')
            reason=str((info or {}).get('motivo') or '')
            if cstat and cstat != 'não identificado':
                record_nfe_actor_result(self.config_data,cnpj,actor,cstat,reason or ('consulta diagnóstica concluída' if ok else 'consulta diagnóstica não concluída'))
            self.after(0,lambda:self._finish_webservice_test(ok,result,info))
        threading.Thread(target=worker,daemon=True).start()

    def _run_nfce_test(self):
        cnpj=self.cnpj_var.get().strip(); thumb=(self.selected.get('Thumbprint') or '').replace(' ','').upper(); nsu='0'
        for widget in (getattr(self,'test_btn',None),getattr(self,'xml_btn',None),getattr(self,'nfce_btn',None)):
            if widget: widget.config(state='disabled')
        self.test_result.config(state='normal'); self.test_result.delete('1.0','end'); self.progress_title.config(text='Consultando NFC-e...'); self.progress_subtitle.config(text='Aguarde enquanto o sistema consulta a SEF/SC.'); self._show_progress_bar(); self.progress_bar.start(10); self.test_result.insert('1.0','Consultando NFC-e...'); self.test_result.config(state='disabled')
        self.set_status('Consultando Web Service NFC-e da SEF/SC...')
        def worker():
            ok,result,info=test_sef_nfce_webservice(thumb,cnpj,ind_xml=1,ind_ator=3,ult_nsu=nsu)
            self.after(0,lambda:self._finish_webservice_test(ok,result,info))
        threading.Thread(target=worker,daemon=True).start()

    def _capture_next_batch(self):
        if not getattr(self,'_period_confirmed',False):
            messagebox.showinfo('Período', 'Confirme o período dos documentos antes de continuar.'); return
        """Manually capture one additional batch for each source from the saved checkpoint."""
        if self.sync_running:
            self.set_status('Já existe uma atualização em andamento.')
            return
        if not self.selected:
            messagebox.showwarning('Certificado', 'Selecione primeiro um certificado digital.')
            return
        cnpj = re.sub(r'\D', '', self.cnpj_var.get().strip())
        if len(cnpj) != 14:
            messagebox.showerror('CNPJ inválido', 'Informe um CNPJ válido antes de capturar o próximo lote.')
            return
        thumb=(self.selected.get('Thumbprint') or '').replace(' ','').upper()
        # V074: record the exact certificate identity used by this synchronization.
        try:
            sync_diag = WORK_DIR / 'ULTIMO_CERTIFICADO_USADO.txt'
            sync_diag.write_text(
                'Certificado usado nesta atualização\n'
                f"Nome: {self.selected.get('FriendlyName') or self.selected.get('Subject') or ''}\n"
                f"CPF/CNPJ: {self.selected.get('Document') or ''}\n"
                f"Thumbprint: {thumb}\n"
                f"Data/Hora: {datetime.now().isoformat(timespec='seconds')}\n",
                encoding='utf-8'
            )
        except Exception:
            pass
        try:
            capture_df,capture_dt=self._get_capture_period()
        except ValueError as exc:
            messagebox.showerror('Período inválido',str(exc)); return
        self._capture_period_snapshot=(capture_df,capture_dt)
        homologacao=bool(self.hom_var.get())
        diagnostic_run_dir = WORK_DIR / 'DIAGNOSTICO_WEBSERVICE' / f"{cnpj}_{datetime.now().strftime('%Y%m%d_%H%M%S')}_lote"
        try:
            diagnostic_run_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            diagnostic_run_dir=None
        self.last_documents = db_load_documents_as_payload(cnpj, limit=100000)
        self.sync_running=True; self.sync_cancel_requested=False; self._sync_started_at=datetime.now(); self._sync_run_id=db_start_run(cnpj)
        self._ia_float_set_state('processando','Analisando os documentos... isso pode levar alguns instantes.',3600)
        try: self._ia_emit_event('SYNC_STARTED',family='all',operation='Buscar XML',company=db_get_company_name(cnpj) or cnpj)
        except Exception: pass
        self._refresh_processing_center()
        self.config_data['active_sync']={'cnpj':cnpj,'started_at':self._sync_started_at.isoformat(timespec='seconds'),'run_id':self._sync_run_id}
        try: save_config(self.config_data)
        except Exception: pass
        self.pending_syncs={}
        starts={f:(0 if f=='nfe' else max(get_saved_nsu(self.config_data, cnpj, f), db_max_source_nsu(cnpj, f))) for f in ('nfe','nfce','cte')}
        for f in ('nfe','nfce','cte'):
            self._update_sync_card(f, db_family_document_count(cnpj, f), 'Capturando')
        self._set_sync_controls(True)
        self._set_global_sync_indicator(True, sum(db_family_document_count(cnpj, f) for f in ('nfe','nfce','cte')))
        self.progress_title.config(text='Capturando o próximo lote')
        self.progress_subtitle.config(text='Buscando mais documentos disponíveis para esta empresa.')
        self._show_progress_bar(); self.progress_bar.start(10)
        self._write_result('A captura do próximo lote começou. O sistema buscará mais documentos a partir do ponto salvo, sem repetir os documentos já armazenados.')
        self.set_status('Capturando o próximo lote em segundo plano.')

        def run_family(family, start_nsu, results, lock):
            if family=='nfe':
                # Manual NF-e continuation obeys the actor-specific scheduler. A 12h wait is
                # respected only after cStat=117; ordinary responses do not create a false block.
                wait, control = nfe_cooldown_remaining(self.config_data, cnpj)
                if wait>0:
                    next_actor=str(control.get('next_actor') or '1')
                    next_label,_=nfe_actor_meta(next_actor)
                    results[family]={'ok':False,'documents':[],'batches':0,'last_nsu':None,'next_nsu':None,
                                    'last_info':{'cstat':str(control.get('last_cstat') or ''),'motivo':str(control.get('last_end_reason') or '')},
                                    'batch_history':[],'new_count':0,'duplicate_count':0,'actor_results':[],
                                    'deferred_actor':next_actor,'deferred_label':next_label,'cooldown_remaining':wait,
                                    'end_reason':f'aguardando {_format_nfe_wait(wait)} para consultar {next_label}'}
                else:
                    actor=choose_nfe_actor(self.config_data,cnpj)
                    label,suffix=nfe_actor_meta(actor)
                    state_key=_sync_state_key(cnpj,suffix)
                    saved=get_saved_nsu(self.config_data,cnpj,suffix)
                    actor_max=db_max_actor_source_nsu(cnpj,'nfe',actor)
                    stream_start=min(saved,actor_max) if actor_max>0 else saved
                    fetch=lambda th,c,n,a=int(actor): test_sef_nfe_webservice(th,c,homologacao,1,n,a)
                    local_new=local_dup=0
                    def cb_nfe(evt, a=str(actor), lab=label):
                        nonlocal local_new,local_dup
                        info_evt=evt.get('info') or {}; docs=info_evt.get('documents') or []
                        for doc in docs:
                            doc['actor_code']=a; doc['actor_label']=lab
                        info_evt['actor_code']=a; info_evt['actor_label']=lab; evt['info']=info_evt
                        try:
                            nnew,ndup=db_upsert_documents(cnpj,docs); local_new+=nnew; local_dup+=ndup
                        except Exception as exc:
                            self.after(0,lambda e=str(exc):self.set_status('Banco local: '+e)); return
                        returned=info_evt.get('ultNSURet') or info_evt.get('ultNSU') or ''
                        if returned not in ('',None):
                            try: save_nsu_state(self.config_data,cnpj,state_key,returned,len(docs),metadata={'nfe_actor_filter':lab,'actor_bootstrapped':True})
                            except Exception: pass
                    res=sync_documents_automatically(fetch,thumb,cnpj,f'nfe_{actor}',start_nsu=stream_start,max_batches=1,progress_cb=cb_nfe,stop_cb=lambda:self.sync_cancel_requested,diagnostic_dir=diagnostic_run_dir,batch_limit=1)
                    res['new_count']=local_new; res['duplicate_count']=local_dup; res['stream_name']=label; res['state_key']=state_key; res['actor_code']=actor
                    info=res.get('last_info') or {}; cstat=str(info.get('cstat') or '')
                    if cstat and cstat != 'não identificado':
                        record_nfe_actor_result(self.config_data,cnpj,actor,cstat,res.get('end_reason',''))
                    control_after=get_nfe_sync_control(self.config_data,cnpj)
                    next_actor=str(control_after.get('next_actor') or ('1' if actor=='2' else '2')); next_label,_=nfe_actor_meta(next_actor)
                    res['deferred_actor']=next_actor; res['deferred_label']=next_label
                    until=_parse_iso_datetime(control_after.get('cooldown_until'))
                    res['cooldown_remaining']=max(0,int(((until or datetime.now())-datetime.now()).total_seconds()))
                    res['end_reason']=((res.get('end_reason') or '') + ' • ' if res.get('end_reason') else '') + f'próximo fluxo: {next_label} após o intervalo de segurança da SEF/SC'
                    streams=[res]
                docs=[]; batches=0; new_total=dup_total=0; hist=[]; reasons=[]; ok=True
                for r in streams:
                    docs.extend(r.get('documents') or []); batches+=int(r.get('batches') or 0); new_total+=int(r.get('new_count') or 0); dup_total+=int(r.get('duplicate_count') or 0); hist.extend(r.get('batch_history') or []); reasons.append(f"{r.get('stream_name','NF-e')}: {r.get('end_reason','')}"); ok=ok and bool(r.get('ok',False))
                results[family]={'ok':ok and not self.sync_cancel_requested,'documents':docs,'batches':batches,'last_nsu':None,'next_nsu':None,'last_info':(streams[-1].get('last_info') if streams else {}),'batch_history':hist,'new_count':new_total,'duplicate_count':dup_total,'actor_results':streams,'end_reason':' • '.join(x for x in reasons if x), 'deferred_actor':(streams[-1].get('deferred_actor') if streams else control.get('next_actor')), 'deferred_label':(streams[-1].get('deferred_label') if streams else nfe_actor_meta(control.get('next_actor') or '1')[0]), 'cooldown_remaining':(streams[-1].get('cooldown_remaining') if streams else wait)}
                return
            if family=='nfce':
                fetch=lambda th,c,n: test_sef_nfce_webservice(th,c,1,3,n)
            else:
                fetch=lambda th,c,n: test_sef_cte_webservice(th,c,1,2,n)
            new_total=dup_total=0
            def cb(evt):
                nonlocal new_total,dup_total
                docs=evt.get('info',{}).get('documents') or []
                saved_ok=False
                try:
                    nnew,ndup=db_upsert_documents(cnpj,docs); new_total+=nnew; dup_total+=ndup; saved_ok=True
                except Exception as exc:
                    self.after(0,lambda e=str(exc):self.set_status('Não foi possível guardar os documentos desta captura: '+e))
                if saved_ok:
                    returned=evt.get('info',{}).get('ultNSURet') or evt.get('info',{}).get('ultNSU')
                    if returned not in (None,''):
                        try:
                            returned_i=int(str(returned))
                            # A continuation request must never move the checkpoint backwards.
                            safe_floor=max(starts.get(family,0), db_max_source_nsu(cnpj,family))
                            if returned_i < safe_floor:
                                raise ValueError('O serviço retornou um ponto de atualização anterior ao já armazenado.')
                            with CONFIG_LOCK:
                                self.config_data.setdefault('_runtime_checkpoints',{})[_sync_state_key(cnpj,family)] = returned_i
                            meta={}
                            max_nsu=evt.get('info',{}).get('maxNSU') or ''
                            if max_nsu not in ('',None): meta['max_nsu']=int(str(max_nsu))
                            save_nsu_state(self.config_data, cnpj, family, returned_i, evt.get('info',{}).get('qtDfeRet') or evt.get('total_docs',0), metadata=meta)
                        except Exception as exc:
                            self.after(0,lambda e=str(exc):self.set_status('Não foi possível atualizar a atualização desta empresa: '+e))
                total_found=evt.get('total_docs',0)
                self.after(0,lambda f=family,c=total_found:self._update_sync_card(f,db_family_document_count(cnpj,f),'Capturando'))
            try:
                res=sync_documents_automatically(fetch,thumb,cnpj,family,start_nsu=start_nsu,max_batches=1,progress_cb=cb,stop_cb=lambda:self.sync_cancel_requested,diagnostic_dir=diagnostic_run_dir,batch_limit=1)
            except Exception as exc:
                res={'ok':False,'documents':[],'batches':0,'last_nsu':start_nsu,'message':str(exc),'last_info':{}}
            res['new_count']=new_total; res['duplicate_count']=dup_total
            with lock: results[family]=res

        def worker():
            from threading import Lock
            lock=Lock(); results={}; threads=[]
            for family in ('nfe','nfce','cte'):
                t=threading.Thread(target=run_family,args=(family,starts[family],results,lock),daemon=True);threads.append(t);t.start()
            for t in threads:t.join()
            payload={'ok':(not self.sync_cancel_requested and len(results)==3 and all((results.get(f) or {}).get('ok',False) for f in ('nfe','nfce','cte'))),'results':results,'cnpj':cnpj}
            self.after(0,lambda p=payload:self._finish_next_batch_capture(p))
        self.sync_thread=threading.Thread(target=worker,daemon=True); self.sync_thread.start()

    def _finish_next_batch_capture(self,payload):
        self.sync_running=False; self.sync_thread=None
        self._ia_float_set_state('concluido','Consulta concluída com sucesso!',3400)
        results=payload.get('results') or {}
        total_new=total_dup=0; continuation=False; problems=[]
        family_report=[]
        for family,res in results.items():
            total_new += int(res.get('new_count') or 0); total_dup += int(res.get('duplicate_count') or 0)
            continuation = continuation or bool(res.get('continuation_available'))
            if not res.get('ok',False): problems.append(SUPPORTED_FAMILIES.get(family,family))
            received=len(res.get('documents') or [])
            family_report.append(f"{SUPPORTED_FAMILIES.get(family,family)}: {received} recebido(s) • {int(res.get('new_count') or 0)} novo(s) • {int(res.get('duplicate_count') or 0)} já existente(s)")
            if res.get('ok') and res.get('last_nsu') is not None:
                try:
                    meta={}
                    info=res.get('last_info') or {}
                    if info.get('maxNSU') not in ('',None): meta['max_nsu']=int(str(info.get('maxNSU')))
                    save_nsu_state(self.config_data,payload.get('cnpj',''),family,res.get('last_nsu'),len(res.get('documents') or []),metadata=meta)
                except Exception: pass
        cnpj=payload.get('cnpj','')
        for family in ('nfe','nfce','cte'):
            self._update_sync_card(family,db_family_document_count(cnpj,family),'Concluído' if not problems else 'Verificar')
        self.last_documents=db_load_documents_as_payload(cnpj,limit=100000)
        cdf,cdt=getattr(self,'_capture_period_snapshot',('',''))
        self.last_documents=self._filter_documents_for_capture_view(self.last_documents,cdf,cdt)
        self.sync_cancel_requested=False
        self._set_sync_controls(False)
        self._hide_progress_bar()
        if problems:
            status='Captura concluída com observações'
            self.progress_title.config(text=status)
            self.progress_subtitle.config(text='Algumas fontes não puderam concluir este lote. Os documentos já armazenados foram preservados.')
        else:
            self.progress_title.config(text='Mais documentos consultados')
            self.progress_subtitle.config(text=f'{total_new} novo(s) nesta captura • {total_dup} já existente(s).')
        self._set_global_sync_indicator(False)
        self._refresh_processing_center(results)
        self._update_remaining_batches_label(cnpj)
        remaining_text=''
        vals=[estimate_remaining_batches(self.config_data, cnpj, f) for f in ('nfe','nfce','cte')]
        if all(v == 0 for v in vals if v is not None) and any(v is not None for v in vals):
            remaining_text='\nTudo o que estava disponível no momento desta captura foi alcançado.'
        else:
            remaining_text=''
        cumul=(f"\n\nTotais na Central: NF-e {db_family_document_count(cnpj,'nfe')} • NFC-e {db_family_document_count(cnpj,'nfce')} • CT-e {db_family_document_count(cnpj,'cte')}")
        self._write_result(('Atualização concluída com observações.' if problems else 'Mais documentos consultados com sucesso.') + '\n\n' + '\n'.join(family_report) + f'\n\nNovos documentos: {total_new}\nJá existentes: {total_dup}' + cumul + remaining_text + '\n\nOs documentos permanecem disponíveis na Central.')
        if self.last_documents:
            self.save_btn.config(state='normal'); self.pdf_btn.config(state='normal')
        if hasattr(self,'audit_btn') and getattr(self,'_cnpj_confirmed',False) and getattr(self,'_period_confirmed',False):
            self.audit_btn.config(state='normal')
        if self._sync_run_id:
            db_update_run(self._sync_run_id,'Concluído com observações' if problems else 'Concluído',finished=True,total_found=len(self.last_documents),new_count=total_new,duplicate_count=total_dup,error_text=', '.join(problems))
        self.config_data.pop('active_sync',None)
        try: save_config(self.config_data)
        except Exception: pass
        self.set_status('Mais documentos consultados.' if not problems else 'Atualização concluída com observações.')
        self._refresh_dashboard_async()
        if getattr(self,'auto_sync_var',None) and self.auto_sync_var.get(): self._schedule_auto_sync()
    def _show_audit_from_documents(self):
        """Open Audit already contextualized to the current Documents Fiscal screen.

        The company, exact period and document families currently visible in the selected
        period are carried into the audit so the user does not need to retype context.
        XMLs already stored locally remain the audit source; only the SAT source is requested
        when no compatible file can be reused. The audit reconciliation engine is untouched.
        """
        if not getattr(self,'_cnpj_confirmed',False) or not getattr(self,'_period_confirmed',False):
            messagebox.showinfo('Auditoria','Confirme o CNPJ e o período dos documentos antes de auditar.')
            return
        capture_from=self.capture_from.get().strip() if hasattr(self,'capture_from') else ''
        capture_to=self.capture_to.get().strip() if hasattr(self,'capture_to') else ''
        try:
            df=_parse_user_date(capture_from,'data inicial da captura') if capture_from else ''
            dt=_parse_user_date(capture_to,'data final da captura') if capture_to else ''
        except Exception:
            df=dt=''
        period_docs=self._filter_documents_for_capture_view(getattr(self,'last_documents',[]),df,dt)
        available=[]
        for fam in ('nfe','nfce'):
            if any(str(d.get('family') or '').casefold()==fam and str(d.get('status') or '').casefold()!='evento' for d in period_docs):
                available.append(fam)

        # Reset any previous audit result before changing context.
        self.last_audit_result=None; self.audit_source_files=[]; self.audit_sat_file=''; self.audit_page=0
        self._show_audit()

        # Set the inherited period only after the Audit frame exists; in older versions
        # this assignment happened before construction of audit_from/audit_to and was lost.
        if hasattr(self,'audit_from'):
            self.audit_from.set(capture_from)
            self.audit_to.set(capture_to)
            self.audit_period_label.config(text=f'{capture_from} até {capture_to}' if capture_from and capture_to else 'Período não informado')
        if available:
            self.audit_selected_families=list(available)
            self.audit_family_var.set(available[0] if len(available)==1 else 'multi')
            labels=' + '.join(SUPPORTED_FAMILIES[f] for f in available)
            self.audit_family_hint.config(text=f'Contexto herdado de Buscar XML: {labels}. Os XMLs armazenados deste período já estão disponíveis para a conciliação.',fg=GREEN)
            self.audit_progress_label.config(text=f'Contexto herdado de Documentos Fiscais • {labels} • {capture_from} até {capture_to}. Se já houver Excel SAT compatível, ele será reutilizado automaticamente.',fg=BLUE)
            self._audit_refresh_family_buttons()
        self._refresh_audit()
        self.after(150, self._run_sat_audit)

    def _run_sync_all(self):
        if not getattr(self,'_period_confirmed',False):
            self._confirm_period()
            if not getattr(self,'_period_confirmed',False):
                return
        """Start one background job; navigation never interrupts it."""
        if self.sync_running:
            self.set_status('Já existe uma atualização em andamento.')
            return
        if not self.selected:
            messagebox.showwarning('Certificado', 'Selecione primeiro um certificado digital.')
            return
        cnpj=re.sub(r'\D','', self.cnpj_var.get().strip())
        if len(cnpj)!=14:
            messagebox.showerror('CNPJ inválido','Informe um CNPJ válido antes de sincronizar.')
            return
        thumb=(self.selected.get('Thumbprint') or '').replace(' ','').upper()
        try:
            capture_df,capture_dt=self._get_capture_period()
        except ValueError as exc:
            messagebox.showerror('Período inválido',str(exc)); return
        self._capture_period_snapshot=(capture_df,capture_dt)
        # V025 introduced a new local database. When a legacy NSU exists from V024 but
        # the new database has no documents for that company/family, the first V026 sync
        # must bootstrap from NSU=0; otherwise the Central could incorrectly appear empty.
        starts={}
        boot=self.config_data.setdefault('v028_bootstrap', {})
        # Cada fluxo tem seu próprio ponto de continuidade. NF-e e CT-e usam
        # cursores independentes por papel para evitar que um fluxo consuma o outro.
        for f in ('nfe','nfce'):
            key=_sync_state_key(cnpj,f)
            if f == 'nfe' and _nfe_requires_full_resync(self.config_data, cnpj):
                starts[f] = 0
                self.use_saved_var.set(True)
                continue
            if not boot.get(key, False):
                starts[f] = (self.nsu_var.get().strip() or '0') if (f=='nfe' and not self.use_saved_var.get()) else 0
            else:
                starts[f] = get_saved_nsu(self.config_data,cnpj,f) if self.use_saved_var.get() else ((self.nsu_var.get().strip() or '0') if f=='nfe' else '0')
        starts['cte_emitente']=get_saved_nsu(self.config_data,cnpj,'cte_emitente')
        starts['cte_tomador']=get_saved_nsu(self.config_data,cnpj,'cte_tomador')
        starts['cte']=0  # compatibilidade da thread principal; CT-e usa dois cursores internos
        homologacao=bool(self.hom_var.get())
        self._active_cnpj_snapshot=cnpj
        diagnostic_run_dir = WORK_DIR / 'DIAGNOSTICO_WEBSERVICE' / f"{cnpj}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        try:
            diagnostic_run_dir.mkdir(parents=True, exist_ok=True)
            (diagnostic_run_dir / 'README.txt').write_text(
                'Esta pasta contém cópias da resposta bruta do Web Service SEF/SC, o lote descompactado e os XMLs brutos extraídos, exclusivamente para diagnóstico.\n',
                encoding='utf-8'
            )
        except Exception:
            diagnostic_run_dir = None
        # The local database is persistent across restarts. Keep its documents visible
        # while the Web Services fetch only the incremental novelties.
        persisted_docs = db_load_documents_as_payload(cnpj, limit=100000)
        self.last_documents = self._filter_documents_for_capture_view(persisted_docs, capture_df, capture_dt)
        self.sync_running=True; self.sync_cancel_requested=False; self._sync_started_at=datetime.now(); self._sync_run_id=db_start_run(cnpj)
        self._ia_float_set_state('processando','Analisando os documentos... isso pode levar alguns instantes.',3600)
        try: self._ia_emit_event('SYNC_STARTED',family='all',operation='Buscar XML',company=db_get_company_name(cnpj) or cnpj)
        except Exception: pass
        self.config_data['active_sync']={'cnpj':cnpj,'started_at':self._sync_started_at.isoformat(timespec='seconds'),'run_id':self._sync_run_id}
        try: save_config(self.config_data)
        except Exception: pass
        self.pending_syncs={}
        initial_counts={f:sum(1 for d in self.last_documents if str(d.get('family') or '').casefold()==f) for f in ('nfe','nfce','cte')}
        for f in ('nfe','nfce','cte'):
            self._update_sync_card(f, initial_counts.get(f,0), 'Sincronizando')
        self._set_sync_controls(True)
        self._set_global_sync_indicator(True, sum(initial_counts.values()))
        self.progress_title.config(text='Buscando XMLs...')
        self.progress_subtitle.config(text='A busca continua em segundo plano. O resultado exibido respeita o período selecionado.')
        self._show_progress_bar(); self.progress_bar.start(10)
        self._write_result(f'Busca iniciada.\n\nPeríodo do resultado: {self._capture_period_label(capture_df,capture_dt)}\n\nA Central pode avançar pelos lotes necessários para concluir a distribuição por NSU. Apenas os documentos do período escolhido aparecem no resultado; documentos de outros períodos permanecem armazenados e serão sinalizados ao final.')
        self.set_status('Atualização em andamento em segundo plano.')

        def run_family(family,start_nsu,results,lock):
            def execute_stream(fetch, state_key, stream_label, stream_start, actor_code=''):
                local_new=local_dup=0
                def cb(evt):
                    nonlocal local_new,local_dup
                    info_evt=evt.get('info') or {}
                    docs=info_evt.get('documents') or []
                    if actor_code:
                        for doc in docs:
                            doc['actor_code']=str(actor_code)
                            doc['actor_label']=stream_label
                        info_evt['actor_code']=str(actor_code)
                        info_evt['actor_label']=stream_label
                    evt['info']=info_evt
                    try:
                        nnew,ndup=db_upsert_documents(cnpj,docs)
                        local_new+=nnew; local_dup+=ndup
                        try: self._refresh_inflight_capture_ui(cnpj)
                        except Exception: pass
                    except Exception as exc:
                        self.after(0,lambda e=str(exc):self.set_status('Banco local: '+e))
                        return
                    info=evt.get('info') or {}
                    returned=info.get('ultNSURet') or info.get('ultNSU') or ''
                    if returned not in (None,''):
                        try:
                            meta={'nfe_actor_filter':stream_label, 'actor_bootstrapped': True} if family=='nfe' else {}
                            max_nsu=info.get('maxNSU') or ''
                            if max_nsu not in ('',None): meta['max_nsu']=int(str(max_nsu))
                            save_nsu_state(self.config_data,cnpj,state_key,returned,len(docs),metadata=meta)
                        except Exception as exc:
                            self.after(0,lambda e=str(exc):self.set_status('Não foi possível atualizar a atualização: '+e))
                    batch_no=int(evt.get('batch') or 0)
                    def refresh_live(f=family,b=batch_no,q=len(docs),st=stream_label):
                        try:
                            live_all=db_load_documents_as_payload(cnpj,limit=100000)
                            cdf,cdt=getattr(self,'_capture_period_snapshot',('',''))
                            self.last_documents=self._filter_documents_for_capture_view(live_all,cdf,cdt)
                            period_counts={fam_:sum(1 for d in self.last_documents if str(d.get('family') or '').casefold()==fam_) for fam_ in ('nfe','nfce','cte')}
                            for fam_ in ('nfe','nfce','cte'):
                                status_=f'Buscando • lote {b}' if fam_==f else ('Aguardando' if period_counts[fam_]==0 else 'Disponível')
                                self._update_sync_card(fam_,period_counts[fam_],status_)
                            self._refresh_documents_dashboard_visuals()
                            self._set_sync_controls(True)
                            self.progress_title.config(text=f'Buscando XMLs • {SUPPORTED_FAMILIES.get(f,f)}')
                            self.progress_subtitle.config(text=f'Lote {b} concluído • {q} documento(s) neste lote • {len(self.last_documents)} documento(s) no período até agora.')
                            self.set_status(f'{SUPPORTED_FAMILIES.get(f,f)} ({st}): lote {b} capturado ({q} documento(s)).')
                            try: self._ia_emit_event('SYNC_BATCH',family=f,documents=q,batch=b,company=db_get_company_name(cnpj) or cnpj)
                            except Exception: pass
                        except Exception:
                            pass
                    self.after(0,refresh_live)
                diag_family = f"{family}_{actor_code}" if actor_code else family
                r=sync_documents_automatically(fetch,thumb,cnpj,diag_family,start_nsu=stream_start,progress_cb=cb,stop_cb=lambda:self.sync_cancel_requested,diagnostic_dir=diagnostic_run_dir)
                r['new_count']=local_new; r['duplicate_count']=local_dup; r['stream_name']=stream_label; r['state_key']=state_key
                # User-facing correction for cStat 657 is intentionally isolated here:
                # the validated request function remains untouched. 657 is not the
                # one-hour consumption-indefinite block; it is the official rejection
                # for an org-code mismatch.
                info_657=r.get('last_info') or {}
                if str(info_657.get('cstat') or '').strip()=='657':
                    r['retry_after_hours']=0
                    r['end_reason']=nfe_cstat_user_message('657',info_657.get('motivo'))
                    r['message']=nfe_cstat_user_message('657',info_657.get('motivo'))
                return r

            if family=='nfe':
                # Keep the validated independent actor-specific flows. The orchestrator
                # may now run the opposite actor in the same search only when the first
                # actor did not reach cStat=117 (the SEF/SC wait condition).
                remaining_wait, control = nfe_cooldown_remaining(self.config_data, cnpj)
                if remaining_wait > 0:
                    next_actor = str(control.get('next_actor') or '1')
                    next_label = 'Emitente / Saída' if next_actor=='1' else 'Destinatário / Entrada'
                    results[family] = {
                        'ok': False, 'documents': [], 'batches': 0, 'last_nsu': None, 'next_nsu': None,
                        'last_info': {'cstat': str(control.get('last_cstat') or ''), 'motivo': str(control.get('last_end_reason') or '')},
                        'batch_history': [], 'new_count': 0, 'duplicate_count': 0, 'actor_results': [],
                        'deferred_actor': next_actor, 'deferred_label': next_label,
                        'cooldown_remaining': remaining_wait,
                        'end_reason': f'aguardando {_format_nfe_wait(remaining_wait)} para consultar {next_label}',
                    }
                else:
                    def execute_nfe_actor(actor):
                        label, suffix = nfe_actor_meta(actor)
                        state_key=_sync_state_key(cnpj,suffix)
                        state_item=get_sync_state_item(self.config_data,cnpj,suffix)
                        saved=get_saved_nsu(self.config_data,cnpj,suffix)
                        actor_max=db_max_actor_source_nsu(cnpj,'nfe',actor)
                        boot_actor=str(state_item.get('bootstrap_actor_code') or '')
                        if boot_actor=='9':
                            stream_start=min(saved,actor_max) if actor_max>0 else 0
                        else:
                            stream_start=min(saved,actor_max) if actor_max>0 else saved
                        fetch=lambda th,c,n,a=int(actor): test_sef_nfe_webservice(th,c,homologacao,1,n,a)
                        r=execute_stream(fetch,state_key,label,stream_start,actor_code=actor)
                        r['stream_name']=label; r['state_key']=state_key; r['actor_code']=actor
                        info=r.get('last_info') or {}; cstat=str(info.get('cstat') or '')
                        if cstat and cstat != 'não identificado':
                            record_nfe_actor_result(self.config_data, cnpj, actor, cstat, r.get('end_reason',''))
                        control_after=get_nfe_sync_control(self.config_data,cnpj)
                        next_actor=str(control_after.get('next_actor') or ('1' if actor=='2' else '2'))
                        next_label='Emitente / Saída' if next_actor=='1' else 'Destinatário / Entrada'
                        until=_parse_iso_datetime(control_after.get('cooldown_until'))
                        r['deferred_actor']=next_actor; r['deferred_label']=next_label
                        r['cooldown_remaining']=max(0,int(((until or datetime.now())-datetime.now()).total_seconds()))
                        return r

                    actor = choose_nfe_actor(self.config_data, cnpj)
                    first = execute_nfe_actor(actor)
                    streams=[first]
                    # If the first actor completed normally (including 137/138-style
                    # responses), immediately consult the opposite independent stream.
                    if nfe_can_chain_actor(first) and not self.sync_cancel_requested:
                        next_actor='1' if str(actor)=='2' else '2'
                        second = execute_nfe_actor(next_actor)
                        streams.append(second)

                    docs=[]; batches=0; new_total=dup_total=0; hist=[]; reasons=[]; ok=True
                    for r in streams:
                        docs.extend(r.get('documents') or []); batches+=int(r.get('batches') or 0); new_total+=int(r.get('new_count') or 0); dup_total+=int(r.get('duplicate_count') or 0)
                        hist.extend(r.get('batch_history') or []); reasons.append(f"{r.get('stream_name','NF-e')}: {r.get('end_reason','')}")
                        ok=ok and bool(r.get('ok',False))
                    last_info=streams[-1].get('last_info') if streams else {}
                    control_after=get_nfe_sync_control(self.config_data,cnpj)
                    next_actor=str(control_after.get('next_actor') or '1')
                    next_label='Emitente / Saída' if next_actor=='1' else 'Destinatário / Entrada'
                    cooldown_remaining,_=nfe_cooldown_remaining(self.config_data,cnpj)
                    results[family]={'ok':ok and not self.sync_cancel_requested,
                                     'documents':docs,'batches':batches,'last_nsu':None,'next_nsu':None,
                                     'last_info':last_info,'batch_history':hist,'new_count':new_total,'duplicate_count':dup_total,
                                     'actor_results':streams,'end_reason':' • '.join(x for x in reasons if x),
                                     'deferred_actor':next_actor,'deferred_label':next_label,'cooldown_remaining':cooldown_remaining}
            else:
                if family=='nfce':
                    fetch=lambda th,c,n: test_sef_nfce_webservice(th,c,1,3,n)
                    state_key=_sync_state_key(cnpj,'nfce'); stream_label='Geral'
                    results[family]=execute_stream(fetch,state_key,stream_label,start_nsu)
                else:
                    # CT-e: dois fluxos independentes, um para documentos emitidos
                    # pela empresa e outro para documentos tomados/destinados a ela.
                    streams=[]
                    for actor,label,suffix in ((1,'Emitente / Saída','cte_emitente'),(2,'Tomador / Entrada','cte_tomador')):
                        if self.sync_cancel_requested: break
                        state_key=_sync_state_key(cnpj,suffix)
                        stream_start=starts.get(suffix,get_saved_nsu(self.config_data,cnpj,suffix))
                        fetch=lambda th,c,n,a=actor: test_sef_cte_webservice(th,c,1,a,n)
                        streams.append(execute_stream(fetch,state_key,label,stream_start))
                    docs=[]; batches=0; new_count=dup_count=0; hist=[]; reasons=[]; ok=True; last_info={}
                    for r in streams:
                        docs.extend(r.get('documents') or []); batches+=int(r.get('batches') or 0); new_count+=int(r.get('new_count') or 0); dup_count+=int(r.get('duplicate_count') or 0); hist.extend(r.get('batch_history') or []); last_info=r.get('last_info') or last_info; reasons.append(f"{r.get('stream_name')}: {r.get('end_reason','')}"); ok=ok and bool(r.get('ok',False))
                    results[family]={'ok':ok and len(streams)==2 and not self.sync_cancel_requested,'documents':docs,'batches':batches,'last_nsu':None,'next_nsu':None,'last_info':last_info,'batch_history':hist,'new_count':new_count,'duplicate_count':dup_count,'actor_results':streams,'end_reason':' • '.join(x for x in reasons if x)}

        def worker():
            from threading import Lock
            lock=Lock(); results={}; threads=[]
            for family in ('nfe','nfce','cte'):
                t=threading.Thread(target=run_family,args=(family,starts[family],results,lock),daemon=True); threads.append(t); t.start()
            for t in threads: t.join()
            # Final UI state comes from the durable local index, not only from this
            # synchronization session. This makes the same company reusable after restart.
            try:
                combined = db_load_documents_as_payload(cnpj, limit=100000)
            except Exception:
                combined=[]
                for family in ('nfe','nfce','cte'):
                    combined.extend(list((results.get(family) or {}).get('documents') or []))
            nfe_deferred=bool((results.get('nfe') or {}).get('deferred_actor'))
            payload={'ok':(not self.sync_cancel_requested and len(results)==3 and all((results.get(f) or {}).get('ok',False) for f in ('nfe','nfce','cte')) and not nfe_deferred),'documents':combined,'results':results,'cnpj':cnpj,'diagnostic_dir':str(diagnostic_run_dir) if diagnostic_run_dir else ''}
            self.after(0,lambda p=payload:self._finish_sync_all(p))
        self.sync_thread=threading.Thread(target=worker,daemon=True); self.sync_thread.start()

    def _refresh_inflight_capture_ui(self, cnpj):
        """Refresh only the safe, period-scoped UI while background capture continues."""
        try:
            df,dt=getattr(self,'_capture_period_snapshot',('',''))
            local=db_load_documents_as_payload(cnpj,limit=100000,date_from=df,date_to=dt)
            self.last_documents=local
            self.after(0,lambda: self._set_sync_controls(True))
            self.after(0,lambda: self.progress_subtitle.config(text=f'{len(local):,} documento(s) já disponíveis neste período • busca continua em segundo plano.'.replace(',','.')) if hasattr(self,'progress_subtitle') else None)
            self.after(0,self._refresh_documents_dashboard_visuals)
        except Exception:
            pass

    def _set_sync_controls(self,running):
        confirmed_period=getattr(self,'_period_confirmed',False); confirmed_cnpj=getattr(self,'_cnpj_confirmed',False); ready=confirmed_cnpj and confirmed_period
        has_docs=bool(getattr(self,'last_documents',[]))
        if running:
            self.sync_all_btn.config(state='disabled'); self.cancel_sync_btn.config(state='normal')
            self.save_btn.config(state='normal' if ready and has_docs else 'disabled')
            self.pdf_btn.config(state='normal' if ready and has_docs else 'disabled')
            if hasattr(self,'local_archive_save_btn'): self.local_archive_save_btn.config(state='disabled')
            if hasattr(self,'audit_btn'): self.audit_btn.config(state='disabled')
            self.cancel_sync_btn.pack(side='right'); return
        self.cancel_sync_btn.config(state='disabled')
        try:self.cancel_sync_btn.pack_forget()
        except Exception:pass
        self.sync_all_btn.config(state='normal' if ready else 'disabled')
        if ready:
            try:
                df,dt=getattr(self,'_capture_period_snapshot',('',''))
                has_docs = db_document_count(self.cnpj_var.get().strip(),df,dt) > 0
            except Exception:
                has_docs = bool(getattr(self,'last_documents',[]))
        self.save_btn.config(state='normal' if ready and has_docs else 'disabled')
        self.pdf_btn.config(state='normal' if ready and has_docs else 'disabled')
        if hasattr(self,'local_archive_save_btn'):
            self.local_archive_save_btn.config(state='normal' if ready and has_docs else 'disabled')
        if hasattr(self,'audit_btn'): self.audit_btn.config(state='normal' if ready and has_docs else 'disabled')

    def _cancel_sync(self):
        if self.sync_running:
            self.sync_cancel_requested=True; self.set_status('Cancelamento solicitado. O lote atual será finalizado com segurança.')

    def _set_global_sync_indicator(self,running,total=0):
        if hasattr(self,'header_sync'):
            self.header_sync.config(text=(f'● Sincronizando • {int(total):,} encontrados'.replace(',','.') if running else ''))
        if hasattr(self,'progress_subtitle') and running:
            self.progress_subtitle.config(text=f'{int(total):,} documento(s) encontrados até agora • processo em segundo plano.'.replace(',','.'))

    def _refresh_sync_view(self):
        if hasattr(self,'sync_company_label'):
            cnpj_now=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
            self.sync_company_label.config(text=db_get_company_name(cnpj_now) or '')
        self._update_remaining_batches_label(cnpj_now if 'cnpj_now' in locals() else None)
        if self.sync_running:
            self._set_global_sync_indicator(True, sum(int(self.sync_card_counts[f].cget('text').replace('.','') or '0') for f in self.sync_card_counts))
            self.progress_title.config(text='Busca em andamento')
            self._show_progress_bar(); self.progress_bar.start(10)

    def _show_progress_bar(self):
        if hasattr(self,'progress_bar') and not self.progress_bar.winfo_manager():
            self.progress_bar.pack(**getattr(self,'_progress_bar_pack',{'fill':'x','padx':14,'pady':(0,6)}))

    def _hide_progress_bar(self):
        if hasattr(self,'progress_bar'):
            self.progress_bar.stop()
            try: self.progress_bar.pack_forget()
            except Exception: pass

    def _write_result(self,text):
        if not hasattr(self,'test_result'): return
        self.test_result.config(state='normal');self.test_result.delete('1.0','end');self.test_result.insert('1.0',text);self.test_result.config(state='disabled')

    def _capture_control_snapshot(self, cnpj=None):
        """Build a user-friendly snapshot of captured totals and remaining estimates."""
        cnpj = re.sub(r'\D','', str(cnpj if cnpj is not None else (self.cnpj_var.get().strip() if hasattr(self,'cnpj_var') else '')))
        snapshot={'cnpj':cnpj,'saved_at':datetime.now().isoformat(timespec='seconds'),'families':{}}
        for family in ('nfe','nfce','cte'):
            item=get_sync_state_item(self.config_data, cnpj, family) if len(cnpj)==14 else {}
            try:
                current=max(0,int(item.get('last_saved_nsu') or 0))
            except Exception:
                current=0
            try:
                max_nsu=max(0,int(item.get('max_nsu') or 0))
            except Exception:
                max_nsu=0
            remaining_docs=max(0,max_nsu-current) if max_nsu else None
            remaining_batches=estimate_remaining_batches(self.config_data, cnpj, family) if len(cnpj)==14 else None
            snapshot['families'][family]={
                'name':SUPPORTED_FAMILIES[family],
                'captured':db_family_document_count(cnpj,family) if len(cnpj)==14 else 0,
                'remaining_documents_estimate':remaining_docs,
                'remaining_batches_estimate':remaining_batches,
                'last_nsu':current,
                'max_nsu':max_nsu,
            }
        return snapshot

    def _save_capture_control(self):
        """Save a readable snapshot so the office can keep track of remaining capture work."""
        cnpj=re.sub(r'\D','', self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
        if len(cnpj)!=14:
            messagebox.showerror('CNPJ inválido','Informe um CNPJ válido antes de salvar o controle de captura.')
            return
        snapshot=self._capture_control_snapshot(cnpj)
        company=db_get_company_name(cnpj) or cnpj
        lines=[
            'EXATO CENTRAL FISCAL',
            'CONTROLE DE CAPTURA DE DOCUMENTOS',
            '',
            f'Empresa: {company}',
            f'CNPJ: {cnpj}',
            f'Atualizado em: {datetime.now().strftime("%d/%m/%Y %H:%M:%S")}',
            '',
        ]
        for family in ('nfe','nfce','cte'):
            info=snapshot['families'][family]
            rem_docs=info['remaining_documents_estimate']
            rem_batches=info['remaining_batches_estimate']
            rem_docs_text=f"aprox. {rem_docs} documento(s)" if rem_docs is not None else 'não disponível'
            rem_batches_text=f"aprox. {rem_batches} lote(s)" if rem_batches is not None else 'não disponível'
            lines += [
                f"{info['name']}:",
                f"  Documentos na Central: {info['captured']}",
                f"  Documentos restantes (estimativa): {rem_docs_text}",
                f"  Documentos ainda disponíveis: {rem_batches_text}",
                '',
            ]
        lines += [
            'Observação:',
            'Os valores de documentos e lotes restantes são estimativas baseadas no ponto de atualização informado pelo serviço.',
            'A próxima atualização continuará automaticamente do ponto salvo.',
        ]
        base_dir=WORK_DIR/'CONTROLES_CAPTURA'
        try: base_dir.mkdir(parents=True,exist_ok=True)
        except Exception: pass
        default_name=f"Controle_Captura_{cnpj}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
        try:
            from tkinter import filedialog
            path=filedialog.asksaveasfilename(
                title='Salvar controle de captura',
                initialdir=str(base_dir),
                initialfile=default_name,
                defaultextension='.txt',
                filetypes=[('Acompanhamento da captura','*.txt'),('Todos os arquivos','*.*')]
            )
            if not path:
                return
        except Exception as exc:
            messagebox.showerror('Acompanhamento da captura',f'Não foi possível abrir a janela de salvamento.\n\n{exc}')
            return
        try:
            Path(path).write_text('\n'.join(lines),encoding='utf-8')
            self.config_data.setdefault('capture_control',{})[_sync_state_key(cnpj,'geral')]={
                'updated_at':snapshot['saved_at'],
                'path':str(path),
                'snapshot':snapshot,
            }
            save_config(self.config_data)
            if False: self.save_capture_btn.config(state='normal')
            self.set_status('Acompanhamento da captura salvo com sucesso.')
            messagebox.showinfo('Acompanhamento da captura','Acompanhamento da captura salvo com sucesso.')
        except Exception as exc:
            messagebox.showerror('Acompanhamento da captura',f'Não foi possível salvar o controle.\n\n{exc}')

    def _persist_capture_control_state(self, cnpj=None):
        """Persist the latest remaining-capture snapshot without prompting the user."""
        cnpj=re.sub(r'\D','', str(cnpj if cnpj is not None else (self.cnpj_var.get().strip() if hasattr(self,'cnpj_var') else '')))
        if len(cnpj)!=14:
            return
        snapshot=self._capture_control_snapshot(cnpj)
        self.config_data.setdefault('capture_control_state',{})[_sync_state_key(cnpj,'geral')]=snapshot
        try: save_config(self.config_data)
        except Exception: pass

    def _update_remaining_batches_label(self, cnpj=None):
        if not hasattr(self,'remaining_batches_label'): return
        cnpj = re.sub(r'\D','', str(cnpj if cnpj is not None else (self.cnpj_var.get().strip() if hasattr(self,'cnpj_var') else '')))
        labels=[]
        for family in ('nfe','nfce','cte'):
            value=estimate_remaining_batches(self.config_data, cnpj, family) if len(cnpj)==14 else None
            item=get_sync_state_item(self.config_data, cnpj, family) if len(cnpj)==14 else {}
            try:
                current=int(item.get('last_saved_nsu') or 0); max_nsu=int(item.get('max_nsu') or 0)
                remaining_docs=max(0,max_nsu-current) if max_nsu else None
            except Exception:
                remaining_docs=None
            if family=='nfce' and remaining_docs is not None:
                labels.append(f"NFC-e ~{remaining_docs} documento(s) / {value if value is not None else '—'} lote(s)")
            else:
                labels.append(f"{SUPPORTED_FAMILIES[family]} {value if value is not None else '—'} lote(s)")
        self.remaining_batches_label.config(text='Documentos ainda disponíveis: ' + ' | '.join(labels))
        if len(cnpj)==14:
            self._persist_capture_control_state(cnpj)

    def _reset_sync_cards(self):
        for family in ('nfe','nfce','cte'):
            if family in getattr(self,'sync_card_counts',{}): self.sync_card_counts[family].config(text='0')
            if family in getattr(self,'sync_card_direction_counts',{}): self.sync_card_direction_counts[family].config(text='Entrada: 0  •  Saída: 0')
            if family in getattr(self,'sync_card_status',{}): self.sync_card_status[family].config(text='Aguardando',fg=MUTED)
            if family in getattr(self,'sync_card_canvases',{}):
                try:
                    cv=self.sync_card_canvases[family]; cv.delete('all'); cv.update_idletasks(); w=max(cv.winfo_width(),140); cv.create_rectangle(0,12,w,16,fill='#EEF2F6',outline='')
                except Exception: pass
        if hasattr(self,'total_docs_label'): self.total_docs_label.config(text='Total: 0 documentos')
        if hasattr(self,'remaining_batches_label'): self.remaining_batches_label.config(text='Documentos ainda disponíveis: NF-e — | NFC-e — | CT-e —')

    def _update_sync_card(self, family, count, status):
        if family not in getattr(self,'sync_card_counts',{}): return
        self.sync_card_counts[family].config(text=f'{int(count):,}'.replace(',','.'))
        status_text=str(status or '')
        status_color = GREEN if status_text in ('Concluído','Sem novos') else (RED if ('Bloqueado' in status_text or '657' in status_text) else (ORANGE if ('Aguardar' in status_text or 'Próximo' in status_text or 'Verificar' == status_text) else MUTED))
        self.sync_card_status[family].config(text=status_text,fg=status_color)
        total=sum(int(self.sync_card_counts[f].cget('text').replace('.','') or '0') for f in ('nfe','nfce','cte') if f in self.sync_card_counts)
        if hasattr(self,'sync_card_canvases') and family in self.sync_card_canvases:
            try:
                cv=self.sync_card_canvases[family]; cv.delete('all'); cv.update_idletasks(); w=max(cv.winfo_width(),140); cv.create_rectangle(0,12,w,16,fill='#EEF2F6',outline=''); ratio=min(1.0,max(0.0,float(count)/max(1,total))); cv.create_rectangle(0,12,int(w*ratio),16,fill=self.sync_card_counts[family].cget('fg'),outline='')
            except Exception: pass
        if hasattr(self,'total_docs_label'): self.total_docs_label.config(text=f'Total: {total:,} documentos'.replace(',','.'))
        if hasattr(self,'remaining_batches_label'): self._update_remaining_batches_label()
        if hasattr(self,'progress_subtitle') and status!='Concluído': self.progress_subtitle.config(text=f'{total:,} documento(s) encontrados até agora.'.replace(',','.'))

    def _finish_sync_all(self,payload):
        self.sync_running=False; self.sync_thread=None
        self._ia_float_set_state('concluido','Consulta concluída com sucesso!',3400)
        self.pending_syncs={}
        results=payload.get('results') or {}
        finished_cnpj=payload.get('cnpj','')
        cdf,cdt=getattr(self,'_capture_period_snapshot',('',''))
        total_new=0; total_dup=0
        for family,res in results.items():
            self.pending_syncs[family]={'last_nsu':res.get('last_nsu'),'docs':len(res.get('documents') or [])}
            if res.get('ok') and res.get('last_nsu') is not None:
                try:
                    meta={}; info=res.get('last_info') or {}
                    if info.get('maxNSU') not in ('',None): meta['max_nsu']=int(str(info.get('maxNSU')))
                    if res.get('end_reason'): meta['end_reason']=res.get('end_reason')
                    if res.get('batches') is not None: meta['last_batch_count']=int(res.get('batches') or 0)
                    save_nsu_state(self.config_data,finished_cnpj,family,res.get('last_nsu'),len(res.get('documents') or []),metadata=meta)
                    self.config_data.setdefault('v028_bootstrap',{})[_sync_state_key(finished_cnpj,family)]=True
                except Exception: pass
            total_new += int(res.get('new_count') or 0); total_dup += int(res.get('duplicate_count') or 0)
        deferred_only=any(bool((r or {}).get('deferred_actor')) for r in results.values()) and not any((not bool((r or {}).get('ok',False))) and not bool((r or {}).get('deferred_actor')) for r in results.values())
        try:
            bad_657=next(((r.get('last_info') or {}) for r in results.values() if str((r.get('last_info') or {}).get('cstat') or '').strip()=='657'),None)
            if bad_657:
                self._ia_emit_event('SYNC_ERROR',family='nfe',cstat='657',error=nfe_cstat_user_message('657',bad_657.get('motivo')),company=db_get_company_name(finished_cnpj) or finished_cnpj)
            elif payload.get('ok'):
                self._ia_emit_event('SYNC_SUCCESS',family='all',documents=len(self.last_documents),new_documents=total_new,company=db_get_company_name(finished_cnpj) or finished_cnpj)
            else:
                self._ia_emit_event('SYNC_ERROR',family='all',error='Uma ou mais fontes não foram concluídas.',company=db_get_company_name(finished_cnpj) or finished_cnpj)
        except Exception:
            pass
        status='Concluído' if payload.get('ok') else ('Cancelado' if self.sync_cancel_requested else ('Aguardando próxima janela' if deferred_only else 'Concluído com observações'))
        if self._sync_run_id:
            err_text='Cancelado pelo usuário' if self.sync_cancel_requested else ('' if payload.get('ok') or deferred_only else 'Uma ou mais fontes não foram concluídas.')
            try: db_update_run(self._sync_run_id,status,finished=True,total_found=sum(len((r or {}).get('documents') or []) for r in results.values()),new_count=total_new,duplicate_count=total_dup,error_text=err_text)
            except Exception: pass
        # Never expose the full local archive as the current search result.
        try:
            all_local=db_load_documents_as_payload(finished_cnpj,limit=100000)
        except Exception:
            all_local=[]
        self.last_documents=self._filter_documents_for_capture_view(all_local,cdf,cdt)
        # Counts are scoped to the requested period.
        period_counts={f:sum(1 for d in self.last_documents if str(d.get('family') or '').lower()==f) for f in ('nfe','nfce','cte')}
        for family in ('nfe','nfce','cte'):
            rr=results.get(family) or {}; info=rr.get('last_info') or {}; cstat=str(info.get('cstat') or '')
            if family=='nfe' and cstat=='657': card_status='Rejeição cStat 657'
            elif family=='nfe' and rr.get('deferred_actor'): card_status='Aguardar próximo fluxo'
            elif family=='nfe' and cstat in {'117','137'} and not period_counts.get(family,0): card_status='Sem novos documentos'
            elif rr.get('ok'): card_status='Concluído'
            else: card_status='Verificar'
            self._update_sync_card(family,period_counts.get(family,0),card_status)
        # Outside-period notice is intentionally based only on documents returned by this run.
        outside=_outside_period_documents(results,cdf,cdt)
        if hasattr(self,'sync_outside_period_label'):
            if outside:
                parts=[]
                months_pt={1:'Janeiro',2:'Fevereiro',3:'Março',4:'Abril',5:'Maio',6:'Junho',7:'Julho',8:'Agosto',9:'Setembro',10:'Outubro',11:'Novembro',12:'Dezembro'}
                for ym in sorted(outside):
                    try:
                        parsed=datetime.strptime(ym+'-01','%Y-%m-%d')
                        pretty=f'{months_pt.get(parsed.month, ym)}/{parsed.year}'
                    except Exception:
                        pretty=ym
                    parts.append(f'{outside[ym]["count"]} documento(s) em {pretty}')
                self.sync_outside_period_label.config(text='ⓘ Há documentos disponíveis fora do período: ' + ' • '.join(parts) + '. Amplie o período para capturá-los.',fg=BLUE)
                self.sync_outside_period_label.pack(fill='x',padx=22,pady=(0,8),after=self.test_result)
            else:
                self.sync_outside_period_label.pack_forget()
        self._last_sync_new_count=total_new
        self._last_sync_duplicate_count=total_dup
        self._last_sync_status='Concluído' if payload.get('ok') else ('Aguardando próxima janela' if deferred_only else 'Verificar')
        self._refresh_documents_dashboard_visuals()
        self._refresh_processing_center(results)
        run_phrase='concluída' if payload.get('ok') else ('aguardando próxima janela' if deferred_only else 'finalizada com observações')
        self._write_result(f'Busca {run_phrase}.\n\nPeríodo do resultado: {self._capture_period_label(cdf,cdt)}\nDocumentos apresentados neste período: {len(self.last_documents)}\nNovos nesta busca: {total_new}\nJá existentes: {total_dup}\n\nOs documentos capturados fora do período permanecem armazenados para futuras consultas.')
        self.sync_cancel_requested=False
        self._set_sync_controls(False)
        self._hide_progress_bar(); self.progress_title.config(text='Busca concluída' if payload.get('ok') else ('Aguardando próxima janela' if deferred_only else 'Busca concluída com observações'))
        self.progress_subtitle.config(text=f'{len(self.last_documents):,} documento(s) no período • {total_new} novos • {total_dup} já existentes'.replace(',','.'))
        self._set_global_sync_indicator(False)
        detail_lines=[]
        for fam in ('nfe','nfce','cte'):
            rr=results.get(fam) or {}; info=rr.get('last_info') or {}; cstat=str(info.get('cstat') or '')
            reason=str(rr.get('end_reason') or '').strip()
            if reason: detail_lines.append(f'{SUPPORTED_FAMILIES.get(fam,fam)}: {reason}')
            if fam=='nfe' and rr.get('deferred_actor'):
                wait=int(rr.get('cooldown_remaining') or 0); next_label=str(rr.get('deferred_label') or 'próximo fluxo')
                detail_lines.append(f'NF-e: próximo fluxo — {next_label}.' if wait<=0 else f'NF-e: {next_label} ficará disponível após {_format_nfe_wait(wait)}.')
            if fam=='nfe' and cstat and cstat not in {'117','137'}:
                detail_lines.append(f'NF-e: cStat {cstat} — {str(info.get("motivo") or "consulte os detalhes").strip()}')
        if detail_lines:
            current=self.test_result.get('1.0','end-1c') if hasattr(self,'test_result') else ''
            self._write_result(current+'\n\nDetalhes da busca:\n'+'\n'.join(detail_lines))
        self.config_data.pop('active_sync',None)
        try: save_config(self.config_data)
        except Exception: pass
        self._update_remaining_batches_label(finished_cnpj)
        self.set_status(f'Busca finalizada: {len(self.last_documents)} documento(s) no período.')
        self._refresh_dashboard_async()
        self._refresh_pending()
        if getattr(self,'auto_sync_var',None) and self.auto_sync_var.get(): self._schedule_auto_sync()
        # V129: after the validated single-company sync completes, optionally save
        # the period-scoped documents and advance the automatic multi-company queue.
        if getattr(self,'_multi_company_run_active',False):
            try:
                self._multi_company_sync_finished(finished_cnpj,payload)
            except Exception as exc:
                self._record_multi_company_result('Concluído c/ observações',f'Falha ao continuar a fila automática: {exc}',0)


    def _run_auto_sync(self, family):
        if not self.selected:
            return
        cnpj=self.cnpj_var.get().strip()
        thumb=(self.selected.get('Thumbprint') or '').replace(' ','').upper()
        self._sync_family_pending = family
        if self.use_saved_var.get():
            start_nsu=get_saved_nsu(self.config_data, cnpj, family)
            self.nsu_var.set(str(start_nsu))
        else:
            start_nsu='0'
        try:
            int(str(start_nsu or '0'))
        except Exception:
            messagebox.showerror('Posição inválida','Informe uma posição inicial válida (somente números).')
            return
        for widget in (self.sync_all_btn,self.save_btn,self.pdf_btn):
            widget.config(state='disabled')
        family_label='NF-e' if family=='nfe' else ('NFC-e' if family=='nfce' else 'CT-e (Entrada)')
        self.test_result.config(state='normal');self.test_result.delete('1.0','end');self.progress_title.config(text=f'Sincronizando {family_label}...'); self.progress_subtitle.config(text='O sistema está trabalhando automaticamente.'); self._show_progress_bar(); self.progress_bar.start(10); self.test_result.insert('1.0',f'Iniciando atualização de {family_label}...\n\nO sistema está trabalhando automaticamente.');self.test_result.config(state='disabled')
        self.set_status(f'Sincronizando {family_label} pela SEF/SC...')

        def progress(evt):
            info=evt.get('info') or {}
            docs=len(info.get('documents') or [])
            returned=info.get('ultNSURet') or info.get('ultNSU') or '?'
            max_nsu=info.get('maxNSU') or '?'
            text=(f"Sincronizando {family_label}...\n\n"
                  f"Lote processado: {evt['batch']}\n"
                  f"Documentos encontrados neste lote: {docs}\n"
                  f"Documentos encontrados até agora: {evt['total_docs']}\n\n"
                  f"O sistema continuará automaticamente.")
            self.after(0,lambda t=text:self._append_sync_progress(t))

        homolog = bool(self.hom_var.get()) if family=='nfe' else False
        def worker():
            if family=='nfe':
                fetch=lambda th,c,n: test_sef_nfe_webservice(th,c,homolog,1,n)
            else:
                fetch=lambda th,c,n: test_sef_nfce_webservice(th,c,1,3,n)
            try:
                result=sync_documents_automatically(fetch,thumb,cnpj,family,start_nsu=start_nsu,progress_cb=progress)
            except Exception as exc:
                result={'ok':False,'documents':[],'batches':0,'last_nsu':start_nsu,'message':str(exc),'last_info':{}}
            self.after(0,lambda:self._finish_auto_sync(family,result))
        threading.Thread(target=worker,daemon=True).start()

    def _append_sync_progress(self, text):
        self.test_result.config(state='normal')
        self.test_result.delete('1.0','end')
        self.test_result.insert('1.0',text)
        self.test_result.config(state='disabled')
        first_line=(text.splitlines()[0] if text else 'Processando...')
        self.progress_title.config(text=first_line)
        if 'Documentos encontrados até agora:' in text:
            last=text.split('Documentos encontrados até agora:')[-1].splitlines()[0].strip()
            self.progress_subtitle.config(text=f'{last} documento(s) encontrados até agora.')

    def _finish_auto_sync(self, family, result):
        self.last_response_info=result.get('last_info') or {}
        self.last_documents=list(result.get('documents') or [])
        all_text=(result.get('message') or '')
        family_label='NF-e' if family=='nfe' else ('NFC-e' if family=='nfce' else 'CT-e (Entrada)')
        all_text=(f"Atualização de {family_label} concluída ✅\n\n"
                  f"Consultas realizadas: {result.get('batches',0)}\n"
                  f"Documentos recuperados: {len(self.last_documents)}\n\n"
                  f"Os documentos estão prontos para salvar ou gerar o relatório em PDF.")
        self.test_result.config(state='normal');self.test_result.delete('1.0','end');self.test_result.insert('1.0',all_text);self.test_result.config(state='disabled')
        self._sync_family=family; self._sync_last_nsu=result.get('last_nsu',self.nsu_var.get())
        for widget in (self.sync_all_btn,): widget.config(state='normal')
        self.save_btn.config(state=('normal' if self.last_documents else 'disabled'))
        self.pdf_btn.config(state=('normal' if self.last_documents else 'disabled'))
        self.set_status(f'{len(self.last_documents)} documento(s) recuperado(s) na atualização {family_label}.')

    def _toggle_auto_fiscal_pdf(self):
        enabled=bool(self.generate_fiscal_pdf_var.get())
        self.config_data['generate_fiscal_pdf_auto']=enabled
        try: save_config(self.config_data)
        except Exception: pass
        self.set_status('Geração automática de PDFs fiscais ativada.' if enabled else 'Geração automática de PDFs fiscais desativada.')


    def _toggle_auto_sync(self):
        enabled=bool(self.auto_sync_var.get())
        self.config_data['auto_sync_enabled']=enabled
        try: save_config(self.config_data)
        except Exception: pass
        if enabled: self._schedule_auto_sync(); self.set_status('Atualização automática ativada (a cada 12 horas).')
        else:
            if self._auto_job is not None:
                try: self.after_cancel(self._auto_job)
                except Exception: pass
                self._auto_job=None
            self.set_status('Atualização automática desativada.')

    def _schedule_auto_sync(self):
        if self._auto_job is not None:
            try: self.after_cancel(self._auto_job)
            except Exception: pass
        self._auto_job=self.after(12*60*60*1000,self._auto_sync_tick)

    def _auto_sync_tick(self):
        self._auto_job=None
        if getattr(self,'auto_sync_var',None) and self.auto_sync_var.get() and not self.sync_running:
            self._run_sync_all()
        elif getattr(self,'auto_sync_var',None) and self.auto_sync_var.get():
            self._schedule_auto_sync()

    def _dashboard_live_tick(self):
        if hasattr(self,'dash_session_summary'):
            sc=getattr(self,'_exatinho_session_counters',{}) or {}
            self.dash_session_summary.config(text=f"Nesta sessão: {sc.get('sync',0)} busca(s) • {sc.get('audit',0)} auditoria(s) • {sc.get('danfe',0)} geração(ões) em lote • {sc.get('pending',0)} ocorrência(s) de atenção.",fg=TEXT)
        try: self._refresh_dashboard_operational_center()
        except Exception: pass
        try:
            if getattr(self,'dashboard_frame',None) is not None and getattr(self,'current_screen',None)=='dashboard' and hasattr(self,'dash_office_labels'):
                if getattr(self,'sync_running',False):
                    self.dash_office_labels['state'].config(text='Processando busca XML',fg=BLUE)
                    self.dash_office_labels['action'].config(text='Acompanhar Centro de Processamento',fg=BLUE)
                elif getattr(self,'audit_running',False):
                    self.dash_office_labels['state'].config(text='Processando auditoria',fg=BLUE)
                    self.dash_office_labels['action'].config(text='Aguardar conclusão da auditoria',fg=BLUE)
                else:
                    pending_label=str(self.dash_values.get('pending').cget('text') if hasattr(self,'dash_values') and self.dash_values.get('pending') else '0')
                    pending_count=int(pending_label or 0) if pending_label.isdigit() else 0
                    self.dash_office_labels['state'].config(text=(f'Pronto • {pending_count} pendência(s)' if pending_count else 'Pronto'),fg=(ORANGE if pending_count else GREEN))
        except Exception:
            pass
        try:
            self._dashboard_live_job=self.after(1000,self._dashboard_live_tick)
        except Exception:
            self._dashboard_live_job=None

    _CARD_ICONS = {'Valor autorizado': 'dinheiro', 'Entradas': 'entrada', 'Saídas': 'saida', 'Documentos': 'documentos', 'Autorizados': 'check', 'Pendências': 'pendencias',
                   'NFS-e prestadas': 'nfse', 'NFS-e tomadas': 'nfse', 'NFS-e canceladas': 'cancelada'}
    _CARD_SOFT = {RED: '#FFF1F2', GREEN: '#ECFDF3', '#2563EB': '#E0F2FE', '#D97706': '#FFFBEB'}

    def _build_card(self,parent,title,value,subtitle,accent):
        """V157: cartão de indicador com ícone em círculo suave, título discreto e valor grande."""
        frame=exato_ui.ModernCard(parent, fill=WHITE, border="#E4E7EC")
        row=tk.Frame(frame,bg=WHITE); row.pack(fill='x',padx=16,pady=(14,2))
        chip=tk.Label(row,image=exato_ui.icon_chip(self._CARD_ICONS.get(title,'documentos'),42,accent,self._CARD_SOFT.get(accent,'#EEF2F7')),bg=WHITE,bd=0); chip.image=chip.cget('image'); chip.pack(side='left')
        txt=tk.Frame(row,bg=WHITE); txt.pack(side='left',padx=(12,0),fill='x',expand=True)
        tk.Label(txt,text=title,bg=WHITE,fg="#64748B",font=('Segoe UI Semibold',9),anchor='w').pack(fill='x')
        value_label=tk.Label(txt,text=value,bg=WHITE,fg=TEXT,font=('Segoe UI Semibold',20),anchor='w'); value_label.pack(fill='x')
        tk.Label(frame,text=subtitle,bg=WHITE,fg=MUTED,font=('Segoe UI',8),anchor='w').pack(fill='x',padx=16,pady=(2,12))
        return frame,value_label

    def _show_dashboard(self):
        if getattr(self,'dashboard_frame',None) is None:
            self.dashboard_frame=tk.Frame(self.page_host,bg=BG); self._build_dashboard_contents()
        self._show_frame(self.dashboard_frame,'dashboard'); self._refresh_today_panel(); self._refresh_dashboard_async()

    def _set_empty_state(self, tree, show, title='', text='', action_label='', action=None):
        """Cartão de orientação sobre uma tabela vazia (em vez de um quadro em branco)."""
        states = self.__dict__.setdefault('_empty_states', {})
        frame = states.get(tree)
        if frame is not None:
            try: frame.destroy()
            except Exception: pass
            states.pop(tree, None)
        if not show:
            return
        frame = tk.Frame(tree.master, bg=WHITE)
        _chip = tk.Label(frame, image=exato_ui.icon_chip('documentos', 56, '#94A3B8', '#F1F5F9'), bg=WHITE, bd=0); _chip.image = _chip.cget('image'); _chip.pack(pady=(0, 6))
        tk.Label(frame, text=title, bg=WHITE, fg=TEXT, font=('Segoe UI Semibold', 12)).pack(pady=(2, 2))
        tk.Label(frame, text=text, bg=WHITE, fg=MUTED, font=('Segoe UI', 9), wraplength=420, justify='center').pack()
        if action_label and action:
            ttk.Button(frame, text=action_label, style='Primary.TButton', command=action).pack(pady=(12, 0))
        frame.place(relx=0.5, y=44, anchor='n')
        frame.lift()
        states[tree] = frame

    @staticmethod
    def _doc_status_badge(status):
        status = str(status or '')
        return {'Autorizado': ('● Autorizado', ''), 'Cancelado': ('✕ Cancelado', 'cancelado'), 'Evento': ('◌ Evento', 'evento')}.get(status, (status, ''))

    @staticmethod
    def _run_status_badge(status):
        status = str(status or '')
        if status == 'Concluído': return '✓ Concluído', 'run_ok'
        if status == 'Em andamento': return '↻ Em andamento', 'run_busy'
        if status == 'Cancelado': return '⊘ Cancelado', 'run_cancel'
        if status == 'Aguardando próxima janela': return '◷ Aguardando próxima janela', 'run_wait'
        if status: return '⚠ ' + status, 'run_warn'
        return status, ''

    def _toast(self, text, kind='info', ms=5000):
        """Aviso rápido no canto superior direito; some sozinho. kind: ok | warn | error | info."""
        colors = {'ok': GREEN, 'warn': '#D97706', 'error': RED, 'info': '#2563EB'}
        icons = {'ok': '✓', 'warn': '⚠', 'error': '✕', 'info': 'ℹ'}
        old = getattr(self, '_toast_frame', None)
        if old is not None:
            try: old.destroy()
            except Exception: pass
        job = getattr(self, '_toast_job', None)
        if job:
            try: self.after_cancel(job)
            except Exception: pass
        color = colors.get(kind, colors['info'])
        soft = {'ok': '#ECFDF3', 'warn': '#FFFBEB', 'error': '#FFF1F2', 'info': '#E0F2FE'}.get(kind, '#E0F2FE')
        icon_name = {'ok': 'check', 'warn': 'alerta', 'error': 'cancelada', 'info': 'pendencias'}.get(kind, 'pendencias')
        frame = exato_ui.ModernCard(self, fill=WHITE, border=BORDER, radius=14)
        chip = tk.Label(frame, image=exato_ui.icon_chip(icon_name, 34, color, soft), bg=WHITE, bd=0); chip.image = chip.cget('image'); chip.pack(side='left', padx=(14, 4), pady=12)
        tk.Label(frame, text=str(text), bg=WHITE, fg=TEXT, font=('Segoe UI', 10), wraplength=340, justify='left').pack(side='left', padx=(8, 14), pady=12)
        close = tk.Label(frame, text='×', bg=WHITE, fg=MUTED, font=('Segoe UI', 12), cursor='hand2'); close.pack(side='right', padx=(0, 12))
        for w in (frame, close):
            w.bind('<Button-1>', lambda e: self._toast_hide(), add='+')
        frame.place(relx=1.0, x=-18, y=62, anchor='ne'); frame.lift()
        self._toast_frame = frame
        self._toast_job = self.after(ms, self._toast_hide)

    def _toast_hide(self):
        frame = getattr(self, '_toast_frame', None)
        self._toast_frame = None; self._toast_job = None
        if frame is not None:
            try: frame.destroy()
            except Exception: pass

    @staticmethod
    def _toast_for_event(kind, payload, company=''):
        """Traduz um evento interno em (mensagem, tipo) de aviso; None quando não vale um aviso."""
        who = f' — {company}' if company else ''
        if kind == 'SYNC_SUCCESS':
            n = int(payload.get('new_documents') or 0)
            return (f'Busca concluída{who}: {n} documento(s) novo(s).' if n else f'Busca concluída{who}: nenhum documento novo.'), 'ok'
        if kind == 'SYNC_ERROR':
            return str(payload.get('error') or 'A busca não foi concluída.')[:160], 'error'
        if kind == 'LOCAL_XML_EXPORT_DONE':
            n, errs, st = int(payload.get('documents') or 0), int(payload.get('errors') or 0), payload.get('status')
            if st == 'cancelled': return 'Salvamento cancelado.', 'info'
            if errs: return f'{n} XML(s) salvo(s), com {errs} erro(s).', 'warn'
            return f'{n} XML(s) salvo(s) com sucesso.', 'ok'
        if kind == 'MULTI_COMPANY_SEARCH_DONE':
            return ('Busca automática concluída.' if payload.get('status') == 'success' else 'Busca automática concluída com pontos de atenção.'), ('ok' if payload.get('status') == 'success' else 'warn')
        if kind == 'DANFE_BATCH_DONE':
            g, errs = int(payload.get('generated') or 0), int(payload.get('errors') or 0)
            return (f'{g} representação(ões) gerada(s).' if not errs else f'{g} representação(ões) gerada(s), {errs} com erro.'), ('ok' if not errs else 'warn')
        if kind == 'AUDIT_CONFORME': return 'Auditoria concluída: tudo conferido.', 'ok'
        if kind == 'AUDIT_DIVERGENCIA': return 'Auditoria concluída com divergências.', 'warn'
        if kind == 'AUDIT_ERROR': return 'A auditoria não foi concluída.', 'error'
        return None

    def _today_action(self, key):
        {'companies': self._show_companies, 'certificate': self._show_certificate_list, 'pending': self._show_pending,
         'documents': self._show_documents, 'sync': self._show_webservice_test}.get(key, self._show_dashboard)()

    def _refresh_today_panel(self):
        """Atualiza o painel "Hoje" com o que precisa de atenção, e um botão que leva à tela certa."""
        if not hasattr(self, 'today_body'):
            return
        try:
            items = build_today_items(db_list_companies(500), self.selected, getattr(self, 'certificates', []),
                                      db_list_runs(50), _audit_history_load())
        except Exception as exc:
            items = [{'severity': 'atencao', 'title': 'Não foi possível montar o resumo de hoje', 'detail': str(exc)[:90], 'action': 'dashboard', 'action_label': 'Atualizar'}]
        for child in self.today_body.winfo_children():
            child.destroy()
        colors = {'alta': (RED, '#FEF2F2'), 'atencao': ('#D97706', '#FFFBEB'), 'ok': (GREEN, '#EDF9F2')}
        urgent = sum(1 for i in items if i['severity'] != 'ok')
        self.today_summary.config(text=(f'{urgent} item(ns) pedem atenção' if urgent else 'Tudo certo por enquanto') + f"  ·  {datetime.now().strftime('%d/%m/%Y')}")
        for item in items[:6]:
            fg, soft = colors[item['severity']]
            row = tk.Frame(self.today_body, bg=WHITE); row.pack(fill='x', pady=3)
            tk.Frame(row, bg=fg, width=4).pack(side='left', fill='y')
            box = tk.Frame(row, bg=soft); box.pack(side='left', fill='x', expand=True)
            text = tk.Frame(box, bg=soft); text.pack(side='left', fill='x', expand=True, padx=12, pady=7)
            tk.Label(text, text=item['title'], bg=soft, fg=TEXT, font=('Segoe UI Semibold', 10), anchor='w').pack(fill='x')
            if item.get('detail'):
                tk.Label(text, text=item['detail'], bg=soft, fg=MUTED, font=('Segoe UI', 8), anchor='w').pack(fill='x')
            ttk.Button(box, text=item['action_label'], style='CompactSecondary.TButton',
                       command=lambda k=item['action']: self._today_action(k)).pack(side='right', padx=10, pady=6)

