        self.company_table_body=tk.Frame(self.company_table_canvas,bg=WHITE)
        self._company_canvas_window=self.company_table_canvas.create_window((0,0),window=self.company_table_body,anchor='nw')
        self.company_table_canvas.configure(yscrollcommand=self.company_table_scroll.set)
        self.company_table_body.bind('<Configure>',lambda e:self.company_table_canvas.configure(scrollregion=self.company_table_canvas.bbox('all')))
        self.company_table_canvas.bind('<Configure>',lambda e:self.company_table_canvas.itemconfigure(self._company_canvas_window,width=e.width))
        self.company_table_scroll.pack(side='right',fill='y')
        self.company_table_canvas.pack(side='left',fill='both',expand=True)

        legend=tk.Frame(self.companies_frame,bg=BG)
        legend.pack(fill='x',padx=24,pady=(0,6))
        left_leg=tk.Frame(legend,bg=BG); left_leg.pack(side='left')
        sep=tk.Frame(legend,bg=BORDER,width=1,height=22); sep.pack(side='left',padx=8,pady=1)
        right_leg=tk.Frame(legend,bg=BG); right_leg.pack(side='left')
        tk.Label(left_leg,text='LEGENDA — ATUALIZAÇÃO',bg=BG,fg=MUTED,font=('Segoe UI Semibold',7)).pack(side='left',padx=(0,6))
        for label,desc,bg_p,fg_p,icon in [
            ('Atualizada','≤ 24h','#DCFCE7','#15803D','●'),
            ('Atenção','24h–72h','#FEF3C7','#D97706','●'),
            ('Desatualizada','> 72h / nunca','#FEE2E2','#DC2626','●')]:
            pill=tk.Frame(left_leg,bg=bg_p)
            pill.pack(side='left',padx=(0,7))
            tk.Label(pill,text=f'{icon}  {label}',bg=bg_p,fg=fg_p,font=('Segoe UI Semibold',7)).pack(side='left',padx=(6,2),pady=3)
            tk.Label(pill,text=f'— {desc}',bg=bg_p,fg=fg_p,font=('Segoe UI',7)).pack(side='left',padx=(0,6),pady=3)
        tk.Label(right_leg,text='LEGENDA — ÚLTIMA BUSCA',bg=BG,fg=MUTED,font=('Segoe UI Semibold',7)).pack(side='left',padx=(0,6))
        search_legend_items=[
            ('Concluída','#DCFCE7','#15803D','✓'),('Observação','#FEF3C7','#D97706','⚠'),
            ('Aguardando','#EEF2F7','#475569','◷'),('Não realizada','#EEF2F7','#64748B','—'),
            ('Erro','#FEE2E2','#DC2626','✕'),('Andamento','#E0F2FE','#0369A1','↻'),
            ('Cancelada','#E0F2FE','#2563EB','⊘')]
        if getattr(self,'compact_ui',True):
            search_legend_items=search_legend_items[:4]
