    def _company_search_focus_in(self,event=None):
        if getattr(self,'_company_query_placeholder',False):
            self._company_query_placeholder=False
            self.company_query.set('')
            try: self.company_query_entry.configure(foreground=TEXT)
            except Exception: pass

    def _company_search_focus_out(self,event=None):
        if not str(self.company_query.get()).strip():
            self._company_query_placeholder=True
            self.company_query.set('Pesquisar por nome ou CNPJ...')

    def _refresh_companies(self):
        if not hasattr(self,'company_table_body'):
            return
        for child in self.company_table_body.winfo_children():
            child.destroy()
        self._company_row_records={}
        self._company_row_widgets={}
        self._selected_company_iid=None
        self._selected_company_cnpj=''
        now=datetime.now(); rows=db_list_companies(); visible_rows=[]; counts={'Atualizada':0,'Atenção':0,'Desatualizada':0}
        q=('' if getattr(self,'_company_query_placeholder',False) else (self.company_query.get() if hasattr(self,'company_query') else '')).strip().casefold()
        filt_label=self.company_filter.get() if hasattr(self,'company_filter') else 'Todas'
        filt={'Todas':'Todas','Atualizadas':'Atualizada','Atenção':'Atenção','Desatualizadas':'Desatualizada'}.get(filt_label,filt_label)
        for r in rows:
            name=str(r.get('name') or '').strip(); cnpj=str(r.get('cnpj') or '')
            if q and q not in name.casefold() and q not in cnpj: continue
            update_status=_company_update_status(r.get('last_sync'),now)
            if filt!='Todas' and update_status!=filt: continue
            counts[update_status]+=1; visible_rows.append((r,update_status))
        visible=len(visible_rows)
        if hasattr(self,'company_summary_cards'):
            self.company_summary_cards['shown'].config(text=f'{visible:,}'.replace(',','.'))
            self.company_summary_cards['updated'].config(text=f'{counts["Atualizada"]:,}'.replace(',','.'))
            self.company_summary_cards['attention'].config(text=f'{counts["Atenção"]:,}'.replace(',','.'))
            self.company_summary_cards['stale'].config(text=f'{counts["Desatualizada"]:,}'.replace(',','.'))

        for idx,(r,update_status) in enumerate(visible_rows,1):
            iid=str(idx); base_bg='#FFFFFF' if idx % 2 else '#FAFBFC'
            name=str(r.get('name') or r.get('cnpj') or '').strip()
            cnpj_raw=re.sub(r'\D','',str(r.get('cnpj') or ''))
            docs=f'{int(r.get("documents") or 0):,}'.replace(',','.')
            last=r.get('last_sync') or ''
            last_display=_format_user_date(last[:10]) + (f' {last[11:16]}' if len(last)>=16 else '') if last else 'Nunca'
            search_label=_company_search_status_label(r.get('last_search_status'),r.get('last_search_error'))
            record={'cnpj':cnpj_raw,'name':name,'values':(name,_format_cnpj(cnpj_raw),docs,last_display,update_status,search_label)}
            self._company_row_records[iid]=record

            row=tk.Frame(self.company_table_body,bg=base_bg,height=38,highlightthickness=0)
            row.pack(fill='x')
            row.pack_propagate(False)
            for cidx,(_,_,weight) in enumerate(self._company_col_specs):
                row.grid_columnconfigure(cidx,weight=max(1,int(weight*100)),uniform='company_cols_row')
            name_lbl=self._company_make_cell(row,0,name,anchor='w',font=('Segoe UI',9),bg=base_bg)
            cnpj_lbl=self._company_make_cell(row,1,_format_cnpj(cnpj_raw),anchor='center',font=('Segoe UI',8),bg=base_bg)
            docs_lbl=self._company_make_cell(row,2,docs,anchor='center',font=('Segoe UI',9),bg=base_bg)
            last_lbl=self._company_make_cell(row,3,last_display,anchor='center',font=('Segoe UI',8),fg=TEXT if last else MUTED,bg=base_bg)
            update_cell=tk.Frame(row,bg=base_bg)
            update_cell.grid(row=0,column=4,sticky='nsew',padx=3,pady=4)
            ubg,ufg,utxt=self._company_status_style(update_status)
            update_pill=self._make_company_pill(update_cell,utxt,ubg,ufg)
            search_cell=tk.Frame(row,bg=base_bg)
            search_cell.grid(row=0,column=5,sticky='nsew',padx=3,pady=4)
            sbg,sfg,stxt=self._company_search_style(search_label)
            search_pill=self._make_company_pill(search_cell,stxt,sbg,sfg)
            widgets={'row':row,'name':name_lbl,'cnpj':cnpj_lbl,'docs':docs_lbl,'last':last_lbl,'update_cell':update_cell,'update_pill':update_pill,'search_cell':search_cell,'search_pill':search_pill,'base_bg':base_bg}
            self._company_row_widgets[iid]=widgets
            for w in (row,name_lbl,cnpj_lbl,docs_lbl,last_lbl,update_cell,update_pill,search_cell,search_pill):
                self._company_bind_tree_event(w,iid,False)
                self._company_bind_tree_event(w,iid,True)
            tk.Frame(self.company_table_body,bg='#E5E7EB',height=1).pack(fill='x')

        self.after_idle(lambda:self.company_table_canvas.configure(scrollregion=self.company_table_canvas.bbox('all')))

    def _use_selected_company(self):
        cnpj=re.sub(r'\D','',str(getattr(self,'_selected_company_cnpj','') or ''))
        if not cnpj:
            return
        rec=None
        for item in getattr(self,'_company_row_records',{}).values():
            if re.sub(r'\D','',str(item.get('cnpj') or '')) == cnpj:
                rec=item; break
        self._show_webservice_test(); self.cnpj_var.set(cnpj); self._active_cnpj_snapshot=''; self._on_cnpj_changed(); self.set_status(f'Empresa selecionada: {rec.get("name") if rec else cnpj}.')

    def _import_companies_excel_dialog(self):
        path=filedialog.askopenfilename(title='Importar empresas do Excel',filetypes=[('Planilha Excel','*.xlsx'),('Todos os arquivos','*.*')])
        if not path:
            return
        try:
            report=import_companies_from_excel(path)
            self._refresh_companies()
            msg=(f"Empresas novas: {report['imported']}\n"
                 f"Empresas atualizadas: {report['updated']}\n"
                 f"Duplicadas ignoradas: {report['duplicates']}\n"
                 f"Linhas inválidas: {report['invalid']}")
            if report['errors']:
                msg += '\n\nOcorrências:\n' + '\n'.join(report['errors'][:8])
            messagebox.showinfo('Importação de empresas',msg)
            self.set_status(f"Importação concluída: {report['imported']} nova(s), {report['updated']} atualizada(s).")
        except Exception as exc:
            messagebox.showerror('Importação de empresas',str(exc))

    def _auto_search_default_period(self):
        now=datetime.now()
        first=now.replace(day=1)
        if now.month==12:
            next_month=now.replace(year=now.year+1,month=1,day=1)
        else:
            next_month=now.replace(month=now.month+1,day=1)
        last=next_month-timedelta(days=1)
        return first.strftime('%d/%m/%Y'),last.strftime('%d/%m/%Y')

    def _auto_search_config(self):
        cfg=self.config_data.setdefault('auto_search',{})
        cfg.setdefault('save_xml_auto',False)
        cfg.setdefault('root_folder','')
        cfg.setdefault('generate_pdf_auto',bool(self.config_data.get('generate_fiscal_pdf_auto',True)))
        return cfg

