        if not self.selected:
            messagebox.showwarning('Certificado','Selecione primeiro um certificado digital antes de iniciar a busca automática.')
            return
        companies=db_list_companies(5000)
        if not companies:
            answer=messagebox.askyesno('Busca automática','Nenhuma empresa está cadastrada. Deseja importar uma planilha Excel agora?')
            if answer:
                self._import_companies_excel_dialog()
                companies=db_list_companies(5000)
