        tk.Label(head,text='Usará o certificado atualmente selecionado para todas as empresas desta execução.',bg=BG,fg=BLUE,font=('Segoe UI Semibold',8)).pack(anchor='w',pady=(3,0))

        period=exato_ui.ModernCard(top, fill=WHITE, border=BORDER); period.pack(fill='x',padx=18,pady=(0,8))
