        current_to=str(self.capture_to.get()).strip() if hasattr(self,'capture_to') else ''
        saved_from=str(self.config_data.get('auto_search',{}).get('period_from') or '')
        saved_to=str(self.config_data.get('auto_search',{}).get('period_to') or '')
