        self._multi_period_from_entry.pack(side='left',pady=8)
        tk.Label(period,text='até',bg=WHITE,fg=MUTED,font=('Segoe UI',9)).pack(side='left',padx=5)
        self._multi_period_to_entry=ttk.Entry(period,textvariable=self._multi_period_to,width=11)
        self._multi_period_to_entry.pack(side='left',pady=8)
        tk.Label(period,text=f'{len(companies)} empresa(s) cadastrada(s)',bg=WHITE,fg=BLUE,font=('Segoe UI Semibold',8)).pack(side='right',padx=12)

        opt=exato_ui.ModernCard(top, fill=WHITE, border=BORDER); opt.pack(fill='x',padx=18,pady=(0,8))
        self._multi_save_xml=tk.BooleanVar(value=bool(self._auto_search_config().get('save_xml_auto')))
        self._multi_generate_pdf=tk.BooleanVar(value=bool(self._auto_search_config().get('generate_pdf_auto',True)))
        self._multi_save_xml_chk=tk.Checkbutton(opt,text='Salvar XML automaticamente',variable=self._multi_save_xml,bg=WHITE,fg=TEXT,activebackground=WHITE,selectcolor=WHITE,font=('Segoe UI Semibold',9),command=self._multi_update_root_controls)
        self._multi_save_xml_chk.pack(side='left',padx=(12,6),pady=8)
        add_info(opt,'Salvar XML automaticamente','Quando ativado, escolha uma pasta raiz. Cada cliente terá sua própria subpasta e a estrutura fiscal validada continuará sendo criada dentro dela.')
        self._multi_generate_pdf_chk=tk.Checkbutton(opt,text='Gerar PDF fiscal junto',variable=self._multi_generate_pdf,bg=WHITE,fg=TEXT,activebackground=WHITE,selectcolor=WHITE,font=('Segoe UI',9))
        self._multi_generate_pdf_chk.pack(side='left',padx=(10,6),pady=8)
        self._multi_root_var=tk.StringVar(value=str(self._auto_search_config().get('root_folder') or ''))
        tk.Label(opt,text='Pasta raiz:',bg=WHITE,fg=MUTED,font=('Segoe UI Semibold',8)).pack(side='left',padx=(12,4))
        self._multi_root_entry=ttk.Entry(opt,textvariable=self._multi_root_var,width=36)
        self._multi_root_entry.pack(side='left',fill='x',expand=True,padx=(2,4),pady=6)
