        action_bar=tk.Frame(top,bg=BG); action_bar.pack(fill='x',padx=18,pady=(0,10))
        self._multi_import_btn=ttk.Button(action_bar,text='IMPORTAR EMPRESAS (EXCEL)',style='Secondary.TButton',command=self._multi_import_companies_and_refresh); self._multi_import_btn.pack(side='left')
        self._multi_cancel_btn=ttk.Button(action_bar,text='FECHAR',style='Secondary.TButton',command=self._close_multi_company_dialog); self._multi_cancel_btn.pack(side='right')
        self._multi_start_btn=ttk.Button(action_bar,text='INICIAR BUSCA AUTOMÁTICA',style='Primary.TButton',command=self._start_multi_company_search,state='disabled'); self._multi_start_btn.pack(side='right',padx=(0,8))
        self._multi_confirm_btn=ttk.Button(action_bar,text='CONFIRMAR CONFIGURAÇÃO',style='Blue.TButton',command=self._confirm_multi_company_config); self._multi_confirm_btn.pack(side='right',padx=(0,8))
