        lh=tk.Frame(list_card,bg=WHITE); lh.pack(fill='x',padx=12,pady=(9,4))
        tk.Label(lh,text='EMPRESAS QUE SERÃO PROCESSADAS',bg=WHITE,fg=TEXT,font=('Segoe UI Semibold',9)).pack(side='left')
