    def _refresh_document_company_choices(self):
        if not hasattr(self,'doc_company_cb'): return
        vals=['Todas']+[f"{r.get('name') or r.get('cnpj')} — {_format_cnpj(r.get('cnpj'))}" for r in db_list_companies()]
        self.doc_company_cb['values']=vals
        if self.doc_company.get() not in vals: self.doc_company.set('Todas')

    def _refresh_documents_list(self):
        if not hasattr(self,'doc_tree'): return
        for i in self.doc_tree.get_children(): self.doc_tree.delete(i)
        self._refresh_document_company_choices()
        fam={'NF-e':'nfe','NFC-e':'nfce','CT-e':'cte','NFS-e':'nfse'}.get(self.doc_family.get(),'')
        direction='' if self.doc_direction.get()=='Todas' else self.doc_direction.get(); status='' if self.doc_status.get()=='Todas' else self.doc_status.get(); export_status='' if self.doc_export_status.get()=='Todos' else self.doc_export_status.get()
        company=self.doc_company.get(); cnpj=''
        if company!='Todas': cnpj=re.sub(r'\D','',company.rsplit('—',1)[-1])
        try: df=_parse_user_date(self.doc_from.get(),'data inicial') if self.doc_from.get().strip() else ''; dt=_parse_user_date(self.doc_to.get(),'data final') if self.doc_to.get().strip() else ''
        except ValueError as exc: messagebox.showerror('Período inválido',str(exc)); return
        if df and dt and df>dt: messagebox.showerror('Período inválido','A data inicial não pode ser maior que a data final.'); return
        query=self.doc_query.get().strip() if hasattr(self,'doc_query') else ''
        rows=db_list_documents(cnpj=cnpj,family=fam,direction=direction,status=status,query=query,limit=5000,date_from=df,date_to=dt,export_status=export_status)
        rows=[r for r in rows if r.get('status')!='Evento']  # V145: evento não é documento
        self.doc_count_label.config(text=f'{len(rows):,}'.replace(',','.')+' documento(s)')
        try:
            archive_stats=db_local_archive_stats(cnpj,df,dt)
            size_mb=archive_stats['bytes']/1024/1024
            self.doc_archive_status_label.config(text=f"ARQUIVO FISCAL LOCAL: {archive_stats['documents']:,} documento(s) • {size_mb:.1f} MB • {archive_stats['exported']:,} exportado(s) • {archive_stats['not_exported']:,} ainda não exportado(s)".replace(',', '.'))
        except Exception:
            pass
        if hasattr(self,'doc_summary_labels'):
            counts={'total':len(rows),'nfe':0,'nfce':0,'cte':0,'nfse':0,'entrada':0,'saida':0}
            for r in rows:
                rf=str(r.get('family') or r.get('doc_type') or '').casefold()
                key={'nfe':'nfe','nfeproc':'nfe','nf-e':'nfe','nfce':'nfce','nfceproc':'nfce','nfc-e':'nfce','cte':'cte','cteproc':'cte','nfse':'nfse','nfs-e':'nfse'}.get(rf)
                if key: counts[key]+=1
                d=str(r.get('direction') or '')
                if d=='Entrada': counts['entrada']+=1
                elif d=='Saída': counts['saida']+=1
            for key,lab in self.doc_summary_labels.items(): lab.config(text=f"{counts.get(key,0):,}".replace(',','.'))
        self._doc_row_map={}
        for idx,r in enumerate(rows,1):
            iid=f'doc_{idx}'; self._doc_row_map[iid]=r
            badge,tag=self._doc_status_badge(r.get('status'))
            if r.get('status')=='Cancelado' and r.get('exported_any'): badge,tag='✕ Cancelado · já exportado','cancelado_exportado'
            self._tree_pill_insert(self.doc_tree, iid, self._doc_pills(r.get('status'),bool(r.get('exported_any'))), (r.get('doc_type'),r.get('number'),r.get('company_name') or r.get('cnpj'),r.get('direction'),_format_user_date(r.get('issued_at')), _format_brl(r.get('value')),badge, '✓ Exportado' if r.get('exported_any') else '○ Não exportado'), tags=((tag,) if tag else ()))
        try: archive_total=int(db_local_archive_stats('')['documents'])
        except Exception: archive_total=len(rows)
        if rows:
            self._set_empty_state(self.doc_tree,False)
        elif archive_total==0:
            self._set_empty_state(self.doc_tree,True,'Nenhum documento ainda','O Arquivo Fiscal Local está vazio. Faça a primeira busca para trazer os XMLs da empresa.','Buscar XML',self._show_webservice_test)
        else:
            self._set_empty_state(self.doc_tree,True,'Nenhum documento com esses filtros','Ajuste ou limpe os filtros acima para ver os documentos do Arquivo Fiscal Local.')
        self._on_document_selection()

    def _select_all_documents(self):
        if not hasattr(self,'doc_tree'): return
        items=self.doc_tree.get_children()
        if not items: return
        self.doc_tree.selection_set(items)
        self._on_document_selection()

    def _clear_document_selection(self):
        if not hasattr(self,'doc_tree'): return
        self.doc_tree.selection_remove(self.doc_tree.selection())
        self._on_document_selection()

    def _generate_selected_representations_batch(self):
        rows=self._selected_document_rows()
        if not rows: return
        if len(rows)==1:
            return self._open_selected_document_representation()
        self._ia_float_set_state('processando',f'Vou preparar {len(rows)} representações fiscais.',3200)
        try: self._ia_emit_event('DANFE_BATCH_STARTED',documents=len(rows),operation='Representações fiscais')
        except Exception: pass
        self.doc_batch_rep_btn.config(state='disabled')
        def worker():
            generated=0; reused=0; errors=[]
            for row in rows:
                try:
                    if str(row.get('family') or '').casefold()=='nfse':
                        _ensure_reportlab(); npath=_nfse_cache_pdf_path(row); ncancel=str(row.get('status') or '')=='Cancelado'
                        if npath.exists() and npath.stat().st_size>=1000 and not ncancel:
                            reused+=1
                        else:
                            nfse_pdf.generate_nfse_pdf([{'xml':bytes(row.get('xml') or b''),'cnpj':row.get('cnpj') or '','situacao':'Cancelada' if ncancel else 'Autorizada'}],str(npath),db_get_company_name(row.get('cnpj') or ''),LOGO_PATH if LOGO_PATH.exists() else None); generated+=1
                        continue
                    fam=_document_family_from_row(row)
                    xml=row.get('xml') or b''
                    if isinstance(xml,memoryview): xml=xml.tobytes()
                    if fam not in SUPPORTED_FAMILIES or not xml:
                        raise ValueError('XML original indisponível ou tipo não identificado.')
                    path=_fiscal_document_cache_path(row)
                    if path.exists() and path.stat().st_size>=1000:
                        reused+=1; continue
                    payload={'xml':bytes(xml),'family':fam,'doc_type':row.get('doc_type') or row.get('tipo') or fam,
                             'chave':row.get('access_key') or row.get('chave') or '', 'numero':row.get('number') or row.get('numero') or '',
                             'serie':row.get('series') or row.get('serie') or '', 'data':str(row.get('issued_at') or row.get('data') or '')[:10],
                             'direcao':row.get('direction') or row.get('direcao') or ''}
                    generate_fiscal_representation_pdf([payload],str(path),family=fam)
                    generated+=1
                except Exception as exc:
                    errors.append(f"{row.get('doc_type') or 'Documento'} nº {row.get('number') or '—'}: {exc}")
            self.after(0,lambda:self._finish_batch_representations(generated,reused,errors))
        threading.Thread(target=worker,daemon=True).start()

    def _finish_batch_representations(self,generated,reused,errors):
        self.doc_batch_rep_btn.config(state='normal' if self._selected_document_rows() else 'disabled')
        total=generated+reused+len(errors)
        if errors:
            self._ia_float_set_state('atencao',f'{generated} representação(ões) gerada(s); {len(errors)} ocorrência(s) pedem revisão.',3600)
            try: self._ia_emit_event('DANFE_BATCH_DONE',generated=generated,errors=len(errors))
            except Exception: pass
            msg=f'{generated} PDF(s) gerado(s) e {reused} já existente(s).\n\nOcorrências: {len(errors)}\n'+'\n'.join(errors[:8])
            messagebox.showwarning('Geração em lote concluída',msg)
            self.set_status(f'Geração em lote concluída com {len(errors)} ocorrência(s).')
        else:
            self._ia_float_set_state('concluido',f'Pronto. {total} representação(ões) conferidas.',3200)
            messagebox.showinfo('Geração em lote concluída',f'{generated} PDF(s) gerado(s).\n{reused} PDF(s) já existente(s).')
            self.set_status(f'{total} representação(ões) fiscais preparadas.')

    def _selected_document_rows(self):
        sel=self.doc_tree.selection() if hasattr(self,'doc_tree') else ()
        mapping=getattr(self,'_doc_row_map',{}) or {}
        return [mapping[iid] for iid in sel if iid in mapping]

    def _selected_document_row(self):
        rows=self._selected_document_rows()
        return rows[0] if rows else None

    def _on_document_selection(self,event=None):
        selected_rows=self._selected_document_rows(); row=selected_rows[0] if selected_rows else None; state='normal' if row else 'disabled'
        for name in ('doc_rep_btn','doc_xml_btn','doc_copy_btn','doc_folder_btn','doc_save_xml_btn'):
            if hasattr(self,name): getattr(self,name).config(state=state)
        if hasattr(self,'doc_batch_rep_btn'):
            self.doc_batch_rep_btn.config(state='normal' if selected_rows else 'disabled')
        if hasattr(self,'doc_save_new_xml_btn'):
            self.doc_save_new_xml_btn.config(state='normal' if getattr(self,'_doc_row_map',{}) else 'disabled')
        if not row:
            if hasattr(self,'doc_action_hint'): self.doc_action_hint.config(text='Selecione um ou mais documentos para ver as ações disponíveis. SALVAR XMLs usa o Arquivo Fiscal Local; SALVAR XMLs NOVOS considera somente a pasta escolhida.')
            return
        fam=_document_family_from_row(row); label={'nfe':'VER/GERAR DANFE','nfce':'VER/GERAR DANFE NFC-e','cte':'VER/GERAR DACTE'}.get(fam,'VER/GERAR REPRESENTAÇÃO')
        self.doc_rep_btn.config(text=label)
        if len(selected_rows)>1:
            self.doc_action_hint.config(text=f'{len(selected_rows)} documentos selecionados • SALVAR XMLs exporta o conteúdo local • SALVAR XMLs NOVOS exporta somente o que ainda não foi registrado na pasta escolhida.')
        else:
            self.doc_action_hint.config(text=f"{row.get('doc_type') or SUPPORTED_FAMILIES.get(fam,fam)} nº {row.get('number') or '—'} • {row.get('company_name') or row.get('cnpj') or 'empresa'} • {('Exportado' if row.get('exported_any') else 'Ainda não exportado')} • SALVAR XMLs usa o XML já armazenado.")

    def _save_new_document_xmls(self):
        """Export only documents not yet registered for the chosen destination root.
        If nothing is selected, use the current filtered list; selection still takes precedence.
        """
        rows=self._selected_document_rows()
        if not rows:
            rows=list((getattr(self,'_doc_row_map',{}) or {}).values())
        if not rows:
            messagebox.showinfo('Salvar XMLs novos','Não há documentos no filtro atual para exportação.'); return
        self._export_document_rows(rows, only_new=True)

    def _show_export_progress(self, total_documents, total_companies, operation_title='Salvando XMLs'):
        """Display a lightweight, non-modal progress window for local XML exports."""
        try:
            win=getattr(self,'_export_progress_window',None)
            if win is not None and win.winfo_exists():
                return win
        except Exception:
            pass
        win=tk.Toplevel(self)
        self._export_progress_window=win
        self._export_progress_queue=queue.Queue()
        self._export_finish_queue=queue.Queue()
        win.title(operation_title)
        win.transient(self)
        win.resizable(False,False)
        try: win.iconphoto(False,self._app_icon)
        except Exception: pass
        outer=exato_ui.ModernCard(win, fill=WHITE, border=BORDER)
        outer.pack(fill='both',expand=True,padx=1,pady=1)
        tk.Label(outer,text='EXPORTANDO XMLs',bg=WHITE,fg=TEXT,font=('Segoe UI Semibold',13)).pack(anchor='w',padx=22,pady=(18,2))
        tk.Label(outer,text='Arquivo Fiscal Local → pasta escolhida',bg=WHITE,fg=MUTED,font=('Segoe UI',8)).pack(anchor='w',padx=22,pady=(0,14))
        self._export_progress_company=tk.StringVar(value='Preparando...')
        self._export_progress_percent=tk.StringVar(value='0%')
        self._export_progress_detail=tk.StringVar(value=f'{total_documents:,} documento(s) • {total_companies} empresa(s)'.replace(',','.'))
        row=tk.Frame(outer,bg=WHITE); row.pack(fill='x',padx=22)
        tk.Label(row,textvariable=self._export_progress_company,bg=WHITE,fg=TEXT,font=('Segoe UI Semibold',9),anchor='w').pack(side='left',fill='x',expand=True)
        tk.Label(row,textvariable=self._export_progress_percent,bg=WHITE,fg=RED,font=('Segoe UI Semibold',10),anchor='e').pack(side='right')
        style_name='Exato.Export.Horizontal.TProgressbar'
        try:
            style=ttk.Style(win)
            style.configure(style_name,thickness=9,troughcolor='#E2E8F0',background=RED,bordercolor='#E2E8F0',lightcolor=RED,darkcolor=RED)
        except Exception:
            style_name='Horizontal.TProgressbar'
        self._export_progress_bar=ttk.Progressbar(outer,orient='horizontal',mode='determinate',maximum=100,value=0,style=style_name)
        self._export_progress_bar.pack(fill='x',padx=22,pady=(8,8))
        tk.Label(outer,textvariable=self._export_progress_detail,bg=WHITE,fg=MUTED,font=('Segoe UI',8),anchor='w',justify='left').pack(fill='x',padx=22)
        action=tk.Frame(outer,bg=WHITE); action.pack(fill='x',padx=22,pady=(18,18))
        self._export_progress_cancel_btn=ttk.Button(action,text='CANCELAR',style='Secondary.TButton',command=self._cancel_export_progress)
        self._export_progress_cancel_btn.pack(side='right')
        win.protocol('WM_DELETE_WINDOW',self._cancel_export_progress)
        win.update_idletasks()
        try:
            px=max(0,self.winfo_rootx() + (self.winfo_width()-win.winfo_width())//2)
            py=max(0,self.winfo_rooty() + 110)
            win.geometry(f'+{px}+{py}')
        except Exception: pass
        self._poll_export_progress()
        return win

    def _poll_export_progress(self):
        """Drain worker updates on the Tk main thread without cross-thread widget access."""
        q=getattr(self,'_export_progress_queue',None)
        fq=getattr(self,'_export_finish_queue',None)
        win=getattr(self,'_export_progress_window',None)
        if q is None:
            return
        try:
            while True:
                percent,company_text,detail_text=q.get_nowait()
                try:
                    if win is not None and win.winfo_exists():
                        value=max(0,min(100,float(percent)))
                        self._export_progress_bar['value']=value
                        if company_text: self._export_progress_company.set(str(company_text))
                        if detail_text: self._export_progress_detail.set(str(detail_text))
                        self._export_progress_percent.set(f'{int(round(value))}%')
                except Exception:
                    pass
        except queue.Empty:
            pass
        if fq is not None:
            try:
                finish=fq.get_nowait()
            except queue.Empty:
                finish=None
            if finish is not None:
                try: finish()
                except Exception: pass
                return
        try:
            if win is not None and win.winfo_exists():
                self.after(50,self._poll_export_progress)
        except Exception:
            pass

    def _update_export_progress(self, percent, company_text='', detail_text=''):
        """Queue a worker progress update for the Tk main thread."""
        q=getattr(self,'_export_progress_queue',None)
        if q is None:
            return
        try: q.put_nowait((percent,company_text,detail_text))
        except Exception: pass

    def _cancel_export_progress(self):
        event=getattr(self,'_export_cancel_event',None)
        if event is not None:
            event.set()
        try:
            if hasattr(self,'_export_progress_cancel_btn'):
                self._export_progress_cancel_btn.config(state='disabled',text='CANCELANDO...')
            if hasattr(self,'_export_progress_company'):
                self._export_progress_company.set('Cancelamento solicitado. Finalizando a empresa atual com segurança...')
        except Exception: pass

    def _close_export_progress(self):
        win=getattr(self,'_export_progress_window',None)
        self._export_progress_window=None
        self._export_progress_queue=None
        self._export_finish_queue=None
        for attr in ('_export_progress_bar','_export_progress_company','_export_progress_percent','_export_progress_detail','_export_progress_cancel_btn'):
            try: delattr(self,attr)
            except Exception: pass
        try:
            if win is not None and win.winfo_exists(): win.destroy()
        except Exception: pass

    def _export_document_rows(self, rows, only_new=False, with_pdf=False, auto_folder=False):
        """auto_folder (V152): usa a pasta já escolhida antes, sem perguntar, e avisa só por aviso rápido (sem janelas)."""
        rows=list(rows or [])
        if not rows: return
        from tkinter import filedialog
        configured_root=str(self._auto_search_config().get('root_folder') or '').strip()
        initial_dir=configured_root if configured_root and Path(configured_root).exists() else None
        quiet=bool(auto_folder and initial_dir)
        if quiet:
            folder=configured_root
        else:
            dialog_kwargs={'title':'Escolha a pasta onde os XMLs serão salvos'}
            if initial_dir: dialog_kwargs['initialdir']=initial_dir
            folder=filedialog.askdirectory(**dialog_kwargs)
        if not folder: return
        root_folder=str(folder)
        if only_new:
            rows=db_filter_unexported(rows,root_folder)
            if not rows:
                if quiet:
                    try: self._toast('Nada novo para salvar: tudo já está na pasta dos clientes.','info')
                    except Exception: pass
                else:
                    messagebox.showinfo('Salvar XMLs novos','Todos os documentos selecionados já foram registrados como exportados para esta pasta.')
                return
        cfg=self._auto_search_config(); cfg['root_folder']=root_folder
        try: save_config(self.config_data)
        except Exception: pass
        try: Path(root_folder).mkdir(parents=True,exist_ok=True)
        except Exception as exc:
            messagebox.showerror('Pasta dos clientes',f'Não foi possível acessar a pasta selecionada.\n\n{exc}'); return
        groups={}
        for row in rows:
            cnpj_digits=re.sub(r'\D','',str(row.get('cnpj') or ''))
            if len(cnpj_digits)!=14: continue
            groups.setdefault(cnpj_digits,[]).append(row)
        if not groups:
            messagebox.showinfo('Salvar XMLs','Nenhum dos documentos possui um CNPJ válido para exportação.'); return
        self._set_export_controls(True); self.set_status('Salvando XMLs do Arquivo Fiscal Local...')
        self._export_cancel_event=threading.Event()
        self._show_export_progress(len(rows),len(groups))
        try: self._ia_emit_event('LOCAL_XML_EXPORT_STARTED',documents=len(rows),companies=len(groups),operation='Salvar XMLs novos' if only_new else 'Salvar XMLs')
        except Exception: pass
        def worker():
            total_saved=0; all_errors=[]; per_company=[]; fully_exported=[]; completed_docs=0; canceled=False
            group_items=list(groups.items())
            total_docs=len(rows)
            for company_index,(cnpj_digits,doc_rows) in enumerate(group_items,1):
                company_name=db_get_company_name(cnpj_digits) or cnpj_digits
                base_pct=(completed_docs/total_docs*100.0) if total_docs else 0.0
                self._update_export_progress(base_pct, f'Empresa {company_index} de {len(group_items)} • {company_name}', f'{completed_docs:,} de {total_docs:,} documento(s) concluído(s)'.replace(',','.'))
                if self._export_cancel_event.is_set():
                    canceled=True; break
                try:
                    saved,errors=save_documents_any(doc_rows,root_folder,cnpj_digits,self.config_data,self.selected,run_legacy_migration=False,generate_companion_pdf=False,nfse_pdf=with_pdf)
                    xml_count=sum(1 for item in saved if str(item).lower().endswith('.xml'))
                    total_saved += xml_count
                    completed_docs=min(total_docs,completed_docs+xml_count)
                    per_company.append(f"{company_name}: {xml_count} XML(s)")
                    all_errors.extend(errors)
                    if not errors and xml_count==len(doc_rows): fully_exported.extend(doc_rows)
                    pct=(completed_docs/total_docs*100.0) if total_docs else 100.0
                    self._update_export_progress(pct, f'Empresa {company_index} de {len(group_items)} • {company_name} ✓', f'{completed_docs:,} de {total_docs:,} documento(s) concluído(s)'.replace(',','.'))
                except Exception as exc:
                    all_errors.append(f'{cnpj_digits}: {type(exc).__name__}: {exc}')
                if self._export_cancel_event.is_set():
                    canceled=True; break
            if fully_exported: db_mark_documents_exported(fully_exported,root_folder)
            if not canceled and not all_errors:
                self._update_export_progress(100,'Exportação concluída ✓',f'{total_saved:,} XML(s) salvo(s) com sucesso.'.replace(',','.'))
            def finish():
                self._set_export_controls(False)
                self._close_export_progress()
                msg=f'{total_saved} XML(s) salvo(s) com sucesso.'
                if canceled:
                    msg += '\n\nExportação cancelada com segurança. Os documentos já processados permanecem salvos; os demais continuam disponíveis no Arquivo Fiscal Local.'
                if only_new: msg += f'\nSomente novos nesta pasta: {len(rows)} documento(s).'
                if per_company: msg += '\n\n'+'\n'.join(per_company[:12])
                if len(per_company)>12: msg += f'\n… e mais {len(per_company)-12} empresa(s).'
                if all_errors:
                    msg += f'\n\n{len(all_errors)} ocorrência(s):\n'+'\n'.join(str(err) for err in all_errors[:10])
                    messagebox.showwarning('Salvar XMLs',msg); status='Salvar XMLs concluído com observações.'
                    try:self._ia_emit_event('LOCAL_XML_EXPORT_DONE',documents=total_saved,errors=len(all_errors),status='attention')
                    except Exception:pass
                elif canceled:
                    messagebox.showinfo('Salvar XMLs',msg); status='Salvar XMLs cancelado com segurança.'
                    try:self._ia_emit_event('LOCAL_XML_EXPORT_DONE',documents=total_saved,errors=0,status='cancelled')
                    except Exception:pass
                else:
                    if quiet:
                        try: self._toast(f'{total_saved} XML(s) salvo(s) na pasta dos clientes.','ok',7000)
                        except Exception: pass
                    else:
                        messagebox.showinfo('Salvar XMLs',msg)
                    status='Salvar XMLs concluído a partir do Arquivo Fiscal Local.'
                    try:self._ia_emit_event('LOCAL_XML_EXPORT_DONE',documents=total_saved,errors=0,status='success')
                    except Exception:pass
                self.set_status(status); self._write_result(f'{total_saved} XML(s) exportado(s) do Arquivo Fiscal Local para: {root_folder}')
                try:self._refresh_documents_list()
                except Exception:pass
            try:
                self._export_finish_queue.put_nowait(finish)
            except Exception:
                pass
        threading.Thread(target=worker,daemon=True).start()

    def _save_selected_document_xmls(self):
        rows=self._selected_document_rows()
        if not rows:
            return
        self._export_document_rows(rows, only_new=False)

    def _open_selected_document(self,event=None):
        self._open_selected_document_representation()

    def _open_selected_document_representation(self):
        row=self._selected_document_row()
        if not row: return
        try:
            path=open_nfse_representation(row) if str(row.get('family') or '').casefold()=='nfse' else open_document_fiscal_representation(row); self.set_status(f'Representação fiscal aberta: {Path(path).name}')
        except Exception as exc: messagebox.showerror('Representação fiscal',str(exc))

    def _open_selected_document_xml(self):
        row=self._selected_document_row()
        if not row: return
        try:
            path=save_document_xml_for_view(row); self.set_status(f'XML aberto para visualização: {Path(path).name}')
        except Exception as exc: messagebox.showerror('XML',str(exc))

    def _copy_selected_document_key(self):
        self._copy_selected_document_keys()

    def _copy_selected_document_keys(self):
        rows=self._selected_document_rows()
        if not rows: return
        keys=[str(r.get('access_key') or '').strip() for r in rows if str(r.get('access_key') or '').strip()]
        if not keys:
            messagebox.showinfo('Chave de acesso','Os documentos selecionados não possuem chave de acesso disponível.'); return
        self.clipboard_clear(); self.clipboard_append('\n'.join(keys)); self.update_idletasks(); self.set_status(f'{len(keys)} chave(s) de acesso copiada(s) para a área de transferência.')

    def _open_selected_document_folder(self):
        row=self._selected_document_row()
        if not row: return
        path=_document_view_xml_path(row)
        try: _open_default_path(path.parent)
        except Exception as exc: messagebox.showerror('Pasta do documento',str(exc))

    def _document_context_menu(self,event=None):
        if not event or not hasattr(self,'doc_tree'): return
        iid=self.doc_tree.identify_row(event.y)
        if not iid: return
        self.doc_tree.selection_set(iid); self._on_document_selection()
        menu=tk.Menu(self,tearoff=0)
