    def _audit_selected_families(self):
        return [f for f in ('nfe','nfce') if f in getattr(self,'audit_selected_families',[])]

    def _audit_set_family(self,family):
        fam=_audit_ui_family(family)
        if not fam: return
        selected=self._audit_selected_families()
        if fam in selected: selected.remove(fam)
        else: selected.append(fam)
        self.audit_selected_families=selected
        self.audit_family_var.set(selected[0] if len(selected)==1 else ('multi' if len(selected)>1 else ''))
        self._audit_refresh_family_buttons()
        if not selected:
            hint='Selecione um ou mais tipos. Cada tipo será auditado separadamente.'
            msg='Escolha NF-e, NFC-e ou ambos e importe os Excel(s) oficiais do SAT.'
        elif len(selected)==1:
            f=selected[0]; hint=f'Selecionado: {SUPPORTED_FAMILIES[f]} · Modelo {AUDIT_FAMILY_MODELS[f]}. O Excel deve conter somente registros desse tipo.'; msg=f'Auditoria configurada para {SUPPORTED_FAMILIES[f]} · Modelo {AUDIT_FAMILY_MODELS[f]}.'
        else:
            labels=' + '.join(SUPPORTED_FAMILIES[f] for f in selected); models=' + '.join(AUDIT_FAMILY_MODELS[f] for f in selected)
            hint=f'Selecionados: {labels} · Modelos {models}. Cada tipo será conciliado separadamente.'; msg=f'Auditoria consolidada: {labels}. A conciliação interna permanece independente por tipo.'
        self.audit_family_hint.config(text=hint,fg=GREEN if selected else MUTED)
        if hasattr(self,'audit_progress_label'): self.audit_progress_label.config(text=msg,fg=BLUE)
        if hasattr(self,'audit_status_message'): self.audit_status_message.config(text=msg)

    def _audit_refresh_family_buttons(self):
        selected=set(self._audit_selected_families())
        for key,btn in getattr(self,'audit_family_buttons',{}).items():
            active=key in selected; display=SUPPORTED_FAMILIES.get(key,key); model=AUDIT_FAMILY_MODELS.get(key,'')
            btn.config(text=f'☑ {display}  ·  Modelo {model}' if active else f'☐ {display}  ·  Modelo {model}',bg=RED if active else '#F2F4F7',fg=WHITE if active else TEXT,activebackground=RED,activeforeground=WHITE)

    def _audit_refresh_mascot(self,state='conforme'):
        """Render the official Exato IA mascot with true transparency and safe framing."""
        mapping={
            'conforme':'exato_ia_conforme_transparent.png',
            'feliz':'exato_ia_conforme_transparent.png',
            'alerta':'mascote_alerta_full_transparent.png',
            'atencao':'mascote_analisando_full_transparent.png',
            'analisando':'mascote_analisando_full_transparent.png',
            'dica':'mascote_dica_full_transparent.png',
        }
        path=MASCOT_ASSET_DIR/mapping.get(state,'exato_ia_transparente.png')
        if not path.exists(): path=MASCOT_EXATO_IA_PATH
        try:
            from PIL import Image,ImageTk,ImageOps
            im=Image.open(path).convert('RGBA')
            # Remove any fully transparent outer waste and then add controlled safe margins.
            alpha=im.getchannel('A'); bbox=alpha.getbbox()
            if bbox: im=im.crop(bbox)
            target=(205,205) if not getattr(self,'compact_ui',True) else (185,185)
            contained=ImageOps.contain(im,target,Image.Resampling.LANCZOS)
            canvas_img=Image.new('RGBA',(target[0],target[1]),(0,0,0,0))
            ox=(target[0]-contained.width)//2; oy=(target[1]-contained.height)//2
            canvas_img.alpha_composite(contained,(ox,oy))
            self.audit_mascot_img=ImageTk.PhotoImage(canvas_img)
            bg=getattr(self,'_audit_ai_bg', None)
            if not bg and hasattr(self,'audit_ai_left'):
                try:bg=self.audit_ai_left.cget('bg')
                except Exception:bg='#F8FAFC'
            bg=bg or '#F8FAFC'
            self.audit_mascot_label.config(image=self.audit_mascot_img,bg=bg)
        except Exception:
            try:
                self.audit_mascot_img=tk.PhotoImage(file=str(path)); self.audit_mascot_label.config(image=self.audit_mascot_img,bg=getattr(self,'_audit_ai_bg', self.audit_ai_left.cget('bg') if hasattr(self,'audit_ai_left') else '#F8FAFC'))
            except Exception:
                self.audit_mascot_label.config(text='Exato IA',fg=GREEN,font=('Segoe UI Semibold',13),bg=getattr(self,'_audit_ai_bg','white'))

    def _audit_apply_ai_theme(self,status='conforme'):
        if status=='conforme':
            bg='#F8FAFC'; accent=GREEN; call='#FEF2F2'; border='#E7EEF5'; nextbg='#F8FAFC'; icon='✓'; side='Tudo certo por aqui!'
        elif status=='divergencia':
            bg='#F8FAFC'; accent=RED; call='#FEF2F2'; border='#E7EEF5'; nextbg='#F8FAFC'; icon='!'; side='Vale revisar os documentos destacados.'
        else:
            bg='#F8FAFC'; accent=ORANGE; call='#FFFBEB'; border='#E7EEF5'; nextbg='#F8FAFC'; icon='!'; side='Vamos conferir esses pontos com calma.'
