    def _audit_render_empty_summary(self):
        for w in self.audit_summary.winfo_children(): w.destroy()
        cards=[('DOCUMENTOS CONCILIADOS','—',BLUE,'•'),('SEM CORRESPONDÊNCIA','—',BLUE,'•'),('DIVERGÊNCIAS DE DADOS','—',BLUE,'•'),('VALOR CONCILIADO','—',BLUE,'R$')]
        for i,(label,value,color,ico) in enumerate(cards):
            f=exato_ui.ModernCard(self.audit_summary, fill=WHITE, border=BORDER); f.pack(side='left',fill='both',expand=True,padx=(0 if i==0 else 6,0)); body=tk.Frame(f,bg=WHITE); body.pack(fill='both',expand=True,padx=9,pady=7); tk.Label(body,text=label,bg=WHITE,fg=MUTED,font=('Segoe UI Semibold',7)).pack(anchor='w'); tk.Label(body,text=value,bg=WHITE,fg=TEXT,font=('Segoe UI Semibold',15 if i<3 else 12)).pack(anchor='w',pady=(1,0))


    def _audit_render_summary(self,result):
        for w in self.audit_summary.winfo_children(): w.destroy()
        ai=result.get('ai_analysis') or analyze_audit_result(result); c=ai.get('counts',{})
        unmatched=int(c.get('pendencias',0) or 0)+int(c.get('xml_only',0) or 0)
        cards=[('DOCUMENTOS CONCILIADOS',str(c.get('conforme',0)+c.get('divergencia',0)),GREEN,'✓'),('SEM CORRESPONDÊNCIA',str(unmatched),RED if unmatched else GREEN,'!' if unmatched else '✓'),('DIVERGÊNCIAS DE DADOS',str(c.get('divergencia',0)),RED if c.get('divergencia') else GREEN,'!' if c.get('divergencia') else '✓'),('VALOR CONCILIADO',_format_brl(result.get('matched_sat_total') or Decimal('0.00')),BLUE,'R$')]
        for i,(label,value,color,ico) in enumerate(cards):
            f=exato_ui.ModernCard(self.audit_summary, fill=WHITE, border=BORDER); f.pack(side='left',fill='both',expand=True,padx=(0 if i==0 else 6,0)); body=tk.Frame(f,bg=WHITE); body.pack(fill='both',expand=True,padx=9,pady=7); row=tk.Frame(body,bg=WHITE); row.pack(fill='x'); tk.Label(row,text=ico,bg=color,fg=WHITE,font=('Segoe UI Semibold',10),width=2).pack(side='left',padx=(0,7)); tk.Label(row,text=label,bg=WHITE,fg=MUTED,font=('Segoe UI Semibold',7),justify='left').pack(side='left'); tk.Label(body,text=value,bg=WHITE,fg=TEXT,font=('Segoe UI Semibold',15 if i<3 else 12)).pack(anchor='w',pady=(3,0))
        if hasattr(self,'audit_status_title'):
            self.audit_status_title.config(text=('CONFORME' if ai.get('status')=='conforme' else ('DIVERGÊNCIA' if ai.get('status')=='divergencia' else 'ATENÇÃO')))
            self.audit_status_message.config(text='Todos os documentos do período foram conciliados com sucesso.' if ai.get('status')=='conforme' else ('Há diferenças nos dados conferidos.' if ai.get('status')=='divergencia' else 'Alguns documentos precisam de conferência.'))
            self._audit_apply_ai_theme(ai.get('status','conforme'))


    def _refresh_audit(self):
        if not hasattr(self,'audit_frame'): return
        cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
        name=db_get_company_name(cnpj) or 'Nenhuma empresa selecionada'
        fam=getattr(self,'audit_family_var',tk.StringVar(value='')).get() if hasattr(self,'audit_family_var') else ''
        family_text=(f' • {SUPPORTED_FAMILIES.get(fam, "")}' if fam else '')
        self.audit_context.config(text=f'Empresa: {name}  •  CNPJ: {_format_cnpj(cnpj)}{family_text}')
        self.audit_meta_labels['empresa'].config(text=name)
        self.audit_meta_labels['cnpj'].config(text=_format_cnpj(cnpj) or '—')
        if hasattr(self,'audit_period_label'):
            if getattr(self,'last_audit_result',None):
                self.audit_period_label.config(text=f"{_format_user_date(self.last_audit_result.get('period_start',''))} até {_format_user_date(self.last_audit_result.get('period_end',''))}")
            else:
                self.audit_period_label.config(text=f"{self.audit_from.get()} até {self.audit_to.get()}" if self.audit_from.get() and self.audit_to.get() else '—')
        self._audit_refresh_family_buttons()
        if not getattr(self,'last_audit_result',None):
            self.audit_pdf_btn.config(state='disabled'); self._audit_rebuild_table()

    def _audit_ask_exato_ia(self):
        question=str(getattr(self,'audit_ai_question_var',tk.StringVar(value='')).get() or '').strip()
        result=getattr(self,'last_audit_result',None) or {}
        if not result:
            if hasattr(self,'audit_ai_callout'): self.audit_ai_callout.config(text='Exato IA: ainda não tenho uma auditoria carregada para analisar. Importe o Excel e eu entro em ação.')
            self.set_status('Conclua uma auditoria antes de conversar com o Exato IA.'); return
        if not question:
            if hasattr(self,'audit_ai_question_entry'): self.audit_ai_question_entry.focus_set()
            self.set_status('Digite uma pergunta para o Exato IA.'); return
        cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''; company=db_get_company_name(cnpj) or ''
        try:
            history=list(getattr(self,'audit_ai_chat_history',[]))
            answer=exato_ia_answer_question(question,result,company,history)
            history.append({'question':question,'answer':answer,'timestamp':datetime.now().isoformat(timespec='seconds')}); self.audit_ai_chat_history=history[-8:]
            self._audit_add_chat_bubble('Você',question,user=True); self._audit_add_chat_bubble('Exato IA',answer,user=False)
            self.audit_ai_question_var.set('')
            self._audit_refresh_mascot('dica'); self.audit_ai_tag.config(text='EXATO IA  |  ANÁLISE DA SUA PERGUNTA'); self.set_status('Exato IA respondeu à sua pergunta.')
        except Exception as exc:
            try:
                (WORK_DIR/'SAT_AUDITORIA').mkdir(parents=True,exist_ok=True); (WORK_DIR/'SAT_AUDITORIA'/'ULTIMO_ERRO_EXATO_IA.txt').write_text(__import__('traceback').format_exc(),encoding='utf-8')
            except Exception: pass
            self._audit_add_chat_bubble('Exato IA','Não consegui concluir essa resposta agora. Tente reformular a pergunta; sua auditoria continua preservada.',user=False,warning=True)
            self.set_status('Exato IA não conseguiu responder agora.')

    def _audit_add_chat_bubble(self,speaker,text,user=False,warning=False):
        if not hasattr(self,'audit_ai_chat_host'): return
        host_bg=self.audit_ai_chat_canvas.cget('bg') if hasattr(self,'audit_ai_chat_canvas') else '#F8FAFC'
        frame=tk.Frame(self.audit_ai_chat_host,bg=host_bg); frame.pack(fill='x',pady=(0,5))
        bg='#F8FAFC' if user else ('#FFF3DD' if warning else '#FEF2F2')
        fg=TEXT; border='#D9E2EC' if user else ('#F1D49B' if warning else '#E7EEF5')
        card=exato_ui.ModernCard(frame, fill=bg, border=border)
        card.pack(side='right' if user else 'left',fill='x',expand=True,padx=(48,0) if user else (0,48))
        tk.Label(card,text=speaker.upper(),bg=bg,fg=(BLUE if user else (ORANGE if warning else GREEN)),font=('Segoe UI Semibold',7),anchor='w').pack(anchor='w',padx=9,pady=(5,0))
        try:
            self.audit_ai_chat_canvas.update_idletasks(); width=max(220,self.audit_ai_chat_canvas.winfo_width()-88)
        except Exception: width=420
        msg=tk.Message(card,text=str(text or ''),bg=bg,fg=fg,font=('Segoe UI',8),justify='left',anchor='w',width=width)
        msg.pack(fill='x',padx=9,pady=(2,6))
        getattr(self,'audit_ai_chat_messages',[]).append(msg)
        try:
            self.audit_ai_chat_canvas.update_idletasks(); self.audit_ai_chat_canvas.configure(scrollregion=self.audit_ai_chat_canvas.bbox('all')); self.audit_ai_chat_canvas.yview_moveto(1.0)
        except Exception: pass



    def _audit_reflow_layout(self,event=None):
        """Keep AI and next-step text inside their live geometry at any window size."""
        try:
            w=max(260,self.audit_ai_mid.winfo_width()-28)
            if hasattr(self,'audit_ai_title'): self.audit_ai_title.config(wraplength=max(230,w))
            if hasattr(self,'audit_ai_message'): self.audit_ai_message.config(wraplength=max(230,w))
            if hasattr(self,'audit_ai_callout'): self.audit_ai_callout.config(width=max(230,w-12))
            for msg in getattr(self,'audit_ai_chat_messages',[]):
                if msg.winfo_exists(): msg.config(width=max(220,w-72))
            nw=max(150,self.audit_ai_next.winfo_width()-24)
            if hasattr(self,'audit_ai_next_title'): self.audit_ai_next_title.config(wraplength=nw)
            if hasattr(self,'audit_ai_next_step'): self.audit_ai_next_step.config(wraplength=nw)
            if hasattr(self,'audit_ai_chat_canvas'):
                self.audit_ai_chat_canvas.configure(scrollregion=self.audit_ai_chat_canvas.bbox('all'))
        except Exception:
            pass

    def _audit_write(self,text):
        if hasattr(self,'audit_progress_label'):
            clean=str(text or '').split('\n')[-1].strip() or 'Processando auditoria...'
            self.audit_progress_label.config(text=clean,fg=BLUE)

    def _audit_new(self):
        self.last_audit_result=None; self.audit_source_files=[]; self.audit_sat_file=''; self.audit_selected_families=[]; self.audit_page=0; self.audit_ai_chat_history=[]
        self.audit_family_var.set(''); self._audit_refresh_family_buttons()
        self.audit_pdf_btn.config(state='disabled'); self.audit_filter_var.set('Todos'); self.audit_type_filter_var.set('Todos'); self.audit_search_var.set('')
        self.audit_family_hint.config(text='Selecione o tipo que corresponde ao Excel do SAT.',fg=MUTED)
        self.audit_progress_label.config(text='Escolha NF-e ou NFC-e e importe o Excel oficial do SAT para começar.',fg=MUTED)
        self._audit_render_empty_summary(); self._audit_rebuild_table(); self._refresh_audit(); self._audit_update_ai_empty()

    def _audit_update_ai_empty(self):
        self._audit_refresh_mascot('conforme')
        self.audit_ai_title.config(text='Aguardando auditoria...')
        self.audit_ai_message.config(text='Selecione NF-e, NFC-e ou ambos e importe os Excel(s) oficiais do SAT para eu começar a conferir.')
        self.audit_ai_chat_messages=[]
        if hasattr(self,'audit_ai_chat_host'):
            for w in self.audit_ai_chat_host.winfo_children(): w.destroy()
            self.audit_ai_callout=tk.Message(self.audit_ai_chat_host,text='Traga os dados. Eu cuido da parte chata da conferência. 😄',bg='#FEF2F2',fg=TEXT,font=('Segoe UI',8),justify='left',anchor='w',width=500,padx=9,pady=6)
            self.audit_ai_callout.pack(fill='x',pady=(0,4))
        self.audit_ai_tag.config(text='EXATO IA  |  ANÁLISE INTELIGENTE')
        try:
            st=str(ai.get('status') or 'atencao')
            ev='AUDIT_CONFORME' if st=='conforme' else ('AUDIT_DIVERGENCIA' if st=='divergencia' else 'AUDIT_ERROR')
            self._ia_emit_event(ev,family=fam,documents=int(result.get('sat_count') or 0),error=ai.get('message','') if st!='conforme' else '')
        except Exception: pass
        self.audit_ai_question_var.set('')
        self.audit_ai_next_title.config(text='Aguardando conferência')
        self.audit_ai_next_step.config(text='Escolha o tipo de documento e importe o Excel correspondente.')
        self._audit_apply_ai_theme('conforme')
        self.after(50,self._audit_reflow_layout)


    def _audit_rebuild_table(self):
        if not hasattr(self,'audit_tree'): return
        for item in self.audit_tree.get_children(): self.audit_tree.delete(item)
        result=getattr(self,'last_audit_result',None) or {}
        rows=list(result.get('display_rows') or _audit_display_rows(result))
        term=str(self.audit_search_var.get() or '').strip().casefold()
        type_filt=str(self.audit_type_filter_var.get() or 'Todos')
        filt=str(self.audit_filter_var.get() or 'Todos')
        if type_filt!='Todos':
            rows=[r for r in rows if str(r.get('modelo') or '').strip()==type_filt]
        if filt!='Todos':
            if filt=='Atenção':
                rows=[r for r in rows if _audit_status_label_for_row(r)=='Atenção']
            else:
                rows=[r for r in rows if _audit_status_label_for_row(r)==filt]
        if term:
            rows=[r for r in rows if term in ' '.join([str(r.get('numero') or ''),str(r.get('data') or ''),str(r.get('modelo') or ''),str(r.get('valor_sat') or ''),str(r.get('valor_xml') or ''),str(r.get('observacao') or '')]).casefold()]
        self.audit_filtered_rows=rows
        pages=max(1,(len(rows)+self.audit_page_size-1)//self.audit_page_size)
        self.audit_page=max(0,min(self.audit_page,pages-1))
        start_idx=self.audit_page*self.audit_page_size; subset=rows[start_idx:start_idx+self.audit_page_size]
        self._audit_row_map={}
        for pos,r in enumerate(subset,start_idx):
            st=_audit_status_label_for_row(r)
            tag={'Conforme':'ok','Sem correspondência':'missing','Divergência':'diff','Atenção':'attention'}.get(st,'')
            iid=f'audit_{pos}'
            self._audit_row_map[iid]=r
            self.audit_tree.insert('', 'end', iid=iid, values=(st,r.get('numero'),_format_user_date(r.get('data') or ''),r.get('modelo') or '—','—' if r.get('valor_sat') is None else _format_brl(r.get('valor_sat') or 0),'—' if r.get('valor_xml') is None else _format_brl(r.get('valor_xml')),r.get('observacao') or ''), tags=(tag,))
        self._on_audit_selection()
        all_display=list(result.get('display_rows') or _audit_display_rows(result))
        problematic = any(_audit_status_label_for_row(r) in {'Sem correspondência','Divergência','Atenção'} for r in all_display)
        if hasattr(self,'audit_table_title_label'):
            self.audit_table_title_label.config(text=('Documentos analisados' if not problematic else 'Documentos e pontos de conferência'))
        self.audit_table_count.config(text=f'({len(all_display)})' if all_display else '(0)')
        if rows:
            shown=len(subset); self.audit_table_hint.config(text=f'Exibindo {start_idx+1}–{start_idx+shown} de {len(rows)} documento(s) filtrado(s).')
        else:
            self.audit_table_hint.config(text='Nenhum documento corresponde aos filtros selecionados.')
        self.audit_page_label.config(text=f'{self.audit_page+1} / {pages}')
        self.audit_prev_btn.config(state='normal' if self.audit_page>0 else 'disabled'); self.audit_next_btn.config(state='normal' if self.audit_page<pages-1 else 'disabled')

    def _audit_prev_page(self):
        self.audit_page-=1; self._audit_rebuild_table()

    def _audit_next_page(self):
        self.audit_page+=1; self._audit_rebuild_table()

    def _selected_audit_row(self):
        if not hasattr(self,'audit_tree'): return None
        sel=self.audit_tree.selection()
        return (getattr(self,'_audit_row_map',{}) or {}).get(sel[0]) if sel else None

    def _audit_source_document(self, audit_row=None):
        row=audit_row or self._selected_audit_row()
        if not row: return None
        cnpj=re.sub(r'\D','',str(self.cnpj_var.get().strip())) if hasattr(self,'cnpj_var') else ''
        return _find_local_audit_document(cnpj,row)

    def _on_audit_selection(self,event=None):
        row=self._selected_audit_row()
        if not hasattr(self,'audit_rep_btn'): return
        fam=_audit_family(row.get('modelo') or '') if row else ''
        label={'nfe':'VER/GERAR DANFE','nfce':'VER/GERAR DANFE NFC-e'}.get(fam,'VER/GERAR REPRESENTAÇÃO')
        self.audit_rep_btn.config(text=label)
        enable=bool(row and row.get('display_status')!='Sem correspondência' and fam in ('nfe','nfce') and row.get('valor_sat') is not None)
        self.audit_rep_btn.config(state='normal' if enable else 'disabled')

    def _open_selected_audit_representation(self):
        row=self._selected_audit_row()
        if not row: return
        if row.get('status')=='XML não localizado':
            messagebox.showinfo('Representação fiscal','O XML correspondente não foi localizado na Central Fiscal. Não é possível gerar a representação sem o XML original.')
            return
        source=self._audit_source_document(row)
        if not source:
            messagebox.showinfo('Representação fiscal','O XML original desta nota não foi localizado na base local da Central Fiscal.')
            return
        try:
            path=open_document_fiscal_representation(source)
            self.set_status(f'Representação fiscal aberta: {Path(path).name}')
        except Exception as exc:
            messagebox.showerror('Representação fiscal',str(exc))

    def _audit_context_menu(self,event=None):
        if not event or not hasattr(self,'audit_tree'): return
        iid=self.audit_tree.identify_row(event.y)
        if not iid: return
        self.audit_tree.selection_set(iid); self._on_audit_selection()
        menu=tk.Menu(self,tearoff=0)
        enabled=self.audit_rep_btn.cget('state')!='disabled'
        menu.add_command(label=self.audit_rep_btn.cget('text'),command=self._open_selected_audit_representation,state=('normal' if enabled else 'disabled'))
        menu.add_command(label='Ver detalhes da conciliação',command=self._audit_open_selected)
        menu.add_separator()
        selected=self._selected_audit_row()
        menu.add_command(label='Copiar chave de acesso',command=self._copy_selected_audit_key,state=('normal' if selected and selected.get('chave') else 'disabled'))
        try: menu.tk_popup(event.x_root,event.y_root)
        finally: menu.grab_release()

    def _copy_selected_audit_key(self):
        row=self._selected_audit_row()
        key=str((row or {}).get('chave') or '').strip()
        if not key: return
        self.clipboard_clear(); self.clipboard_append(key); self.update_idletasks(); self.set_status('Chave de acesso copiada para a área de transferência.')

    def _audit_open_selected(self,event=None):
        row=self._selected_audit_row()
        if not row: return
        extra=[]
        if row.get('chave'): extra.append(f'Chave: {row["chave"]}')
        if row.get('differences'): extra.append('Diferenças: ' + ' • '.join(d.get('detail','') for d in row['differences']))
        message=(f'Situação: {row.get("status")}\nNota: {row.get("numero")}\nData: {_format_user_date(row.get("data") or "")}\nModelo: {row.get("modelo") or "—"}\nValor SAT: {_format_brl(row.get("valor_sat") or 0)}\nValor XML: {"—" if row.get("valor_xml") is None else _format_brl(row.get("valor_xml"))}\n\n{row.get("observacao") or ""}' + (('\n\n'+'\n'.join(extra)) if extra else ''))
        messagebox.showinfo('Detalhes da conciliação',message)

    def _audit_show_history(self):
        top=tk.Toplevel(self); top.title('Histórico de auditorias'); top.geometry('980x440'); top.configure(bg=BG); top.transient(self)
        tk.Label(top,text='Histórico de auditorias',bg=BG,fg=TEXT,font=('Segoe UI Semibold',16)).pack(anchor='w',padx=16,pady=(14,2))
        tk.Label(top,text='Últimas conciliações realizadas nesta instalação.',bg=BG,fg=MUTED,font=('Segoe UI',9)).pack(anchor='w',padx=16,pady=(0,9))
        wrap=exato_ui.ModernCard(top, fill=WHITE, border=BORDER); wrap.pack(fill='both',expand=True,padx=16,pady=(0,14))
        cols=('data','empresa','tipo','periodo','documentos','pendencias','divergencias','status'); tree=ttk.Treeview(wrap,columns=cols,show='headings')
        heads={'data':'Data','empresa':'Empresa','tipo':'Tipo','periodo':'Período','documentos':'Docs.','pendencias':'Pendências','divergencias':'Divergências','status':'Status'}
        widths={'data':140,'empresa':260,'tipo':90,'periodo':155,'documentos':65,'pendencias':80,'divergencias':90,'status':95}
        for c in cols: tree.heading(c,text=heads[c]); tree.column(c,width=widths[c],anchor='w')
        for e in _audit_history_load():
            st='Conforme' if e.get('status')=='conforme' else ('Divergência' if e.get('status')=='divergencia' else 'Atenção')
            tipo=e.get('family_label') or SUPPORTED_FAMILIES.get(e.get('family',''),'—')
            tree.insert('', 'end', values=(e.get('timestamp','').replace('T',' '),e.get('company',''),tipo,f"{_format_user_date(e.get('period_start',''))} até {_format_user_date(e.get('period_end',''))}",e.get('sat_count',0),e.get('missing_count',0),e.get('divergence_count',0),st))
        tree.pack(side='left',fill='both',expand=True,padx=4,pady=4); ttk.Scrollbar(wrap,orient='vertical',command=tree.yview).pack(side='right',fill='y',pady=4)

    def _finish_sat_audit_cancelled(self, message='Auditoria cancelada pelo usuário.'):
        self.audit_running=False; self.audit_cancel_event.clear()
        if hasattr(self,'audit_import_btn'): self.audit_import_btn.config(state='normal')
        if hasattr(self,'audit_cancel_btn'): self.audit_cancel_btn.config(state='disabled')
        if hasattr(self,'audit_pdf_btn'): self.audit_pdf_btn.config(state='disabled')
        self.audit_progress_label.config(text='Auditoria cancelada.',fg=ORANGE)
        self.set_status('Auditoria cancelada.')

    def _finish_sat_audit_error(self, error_text):
        self.audit_running=False; self.audit_cancel_event.clear()
        if hasattr(self,'audit_import_btn'): self.audit_import_btn.config(state='normal')
        if hasattr(self,'audit_cancel_btn'): self.audit_cancel_btn.config(state='disabled')
        if hasattr(self,'audit_pdf_btn'): self.audit_pdf_btn.config(state='disabled')
        self.audit_progress_label.config(text='Não foi possível concluir a auditoria.',fg='#B91C1C')
        self.set_status('Auditoria não concluída: verifique o Excel selecionado.')
        messagebox.showerror('Auditoria não concluída',str(error_text))

    def _safe_finish_sat_audit(self,result,fetched):
        """Finish the audit on the UI thread without leaving the screen stuck on 'processing'."""
        try:
            self._finish_sat_audit(result,fetched)
        except Exception as exc:
            import traceback
            try:
                (WORK_DIR/'SAT_AUDITORIA').mkdir(parents=True,exist_ok=True)
                (WORK_DIR/'SAT_AUDITORIA'/'ULTIMO_ERRO_AUDITORIA_UI.txt').write_text(traceback.format_exc(),encoding='utf-8')
            except Exception:
                pass
            self._finish_sat_audit_error(f'Falha ao apresentar o resultado da auditoria: {exc}')

    def _finish_sat_audit(self,result,fetched):
        self.audit_running=False; self.audit_cancel_event.clear()
        if hasattr(self,'audit_import_btn'): self.audit_import_btn.config(state='normal')
        if hasattr(self,'audit_cancel_btn'): self.audit_cancel_btn.config(state='disabled')
        if hasattr(self,'audit_pdf_btn'): self.audit_pdf_btn.config(state='normal')
        self.last_audit_result=result
        self.audit_source_files=list(fetched.get('files') or []) if fetched else []
        result['source_files']=list(self.audit_source_files)
        self.audit_sat_file=self.audit_source_files[0] if self.audit_source_files else ''
        fam=result.get('family') or getattr(self,'audit_family_var',tk.StringVar(value='')).get()
        if result.get('family')=='multi':
            self.audit_selected_families=list(result.get('selected_families') or [])
            self.audit_family_var.set('multi')
        else:
            self.audit_selected_families=[fam] if fam in ('nfe','nfce') else []
            self.audit_family_var.set(fam)
        self._audit_refresh_family_buttons()
        cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
        company_name=db_get_company_name(cnpj) or 'Empresa não identificada'
        result['ai_analysis']=analyze_audit_result(result,company_name,result.get('period_start',''),result.get('period_end',''))
        _audit_history_save(result,company_name,cnpj,self.audit_source_files)
        self._audit_render_summary(result)
        ai=result['ai_analysis']; self._audit_refresh_mascot(ai.get('mascot_state','conforme')); self._audit_apply_ai_theme(ai.get('status','conforme'))
        self.audit_ai_title.config(text=ai.get('title','Auditoria concluída'),fg=GREEN if ai.get('status')=='conforme' else (ORANGE if ai.get('status')=='atencao' else RED))
        self.audit_ai_message.config(text=ai.get('message','')); self.audit_ai_callout.config(text=ai.get('callout','')); self.audit_ai_chat_history=[]
        self.audit_ai_tag.config(text='EXATO IA  |  ANÁLISE INTELIGENTE')
        self.audit_ai_next_title.config(text='Pronto para a próxima etapa'); self.audit_ai_next_step.config(text=ai.get('next_step',''))
        files_count=len(self.audit_source_files)
        family_label=result.get('family_label') or SUPPORTED_FAMILIES.get(fam,fam)
        self.audit_progress_label.config(text=f'Excel(s) {family_label} importado(s) • {files_count} arquivo(s) • {result["sat_count"]} documento(s) analisado(s). PDF disponível.',fg=GREEN)
        self.audit_from.set(_format_user_date(result.get('period_start',''))); self.audit_to.set(_format_user_date(result.get('period_end','')))
        self.audit_period_label.config(text=f'{self.audit_from.get()} até {self.audit_to.get()}')
        self.audit_page=0; self.audit_filter_var.set('Todos'); self.audit_type_filter_var.set('Todos'); self.audit_search_var.set(''); self._audit_rebuild_table()
        self.set_status(f'Auditoria concluída: {result["sat_count"]} documento(s) analisado(s).'); self._refresh_dashboard_async()

    def _cancel_sat_audit(self):
        if getattr(self,'audit_running',False):
            self.audit_cancel_event.set()
            self.audit_progress_label.config(text='Cancelando a auditoria...',fg=ORANGE)
            self.set_status('Cancelando auditoria...')

    def _import_sat_excel_files(self, paths=None):
        if getattr(self,'audit_running',False): self.set_status('Já existe uma auditoria em andamento.'); return
        selected=self._audit_selected_families()
        if not selected:
            messagebox.showinfo('Tipo de documento','Selecione NF-e, NFC-e ou ambos antes de importar os Excel(s) do SAT.'); return
        labels=' + '.join(SUPPORTED_FAMILIES[f] for f in selected)
        if paths is None:
            paths=filedialog.askopenfilenames(title=f'Selecione os Excel(s) do SAT — {labels}',filetypes=[('Excel do SAT','*.xlsx'),('Todos os arquivos','*.*')])
            if not paths: return
        else:
            paths=tuple(str(p) for p in paths if str(p).strip())
            if not paths:
                self.set_status('Nenhum Excel SAT compatível foi encontrado para reutilização.')
                return
            self.set_status(f'Reutilizando {len(paths)} Excel(s) SAT do mesmo período.')
        self.audit_running=True; self.audit_cancel_event.clear(); self.audit_import_btn.config(state='disabled'); self.audit_cancel_btn.config(state='normal'); self.audit_pdf_btn.config(state='disabled')
        try: self._ia_emit_event('AUDIT_STARTED',family='multi' if len(selected)>1 else selected[0],operation='Auditoria Fiscal')
        except Exception: pass
        self.audit_progress_label.config(text=f'Lendo {len(paths)} arquivo(s) do SAT — {labels}...',fg=BLUE); self.set_status('Lendo Excel(s) do SAT...')
        cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
        try:
            df=_parse_user_date(self.audit_from.get(),'data inicial') if self.audit_from.get().strip() else ''
            dt=_parse_user_date(self.audit_to.get(),'data final') if self.audit_to.get().strip() else ''
        except Exception as exc: self._finish_sat_audit_error(str(exc)); return
        if not df or not dt:
            if hasattr(self,'capture_from') and self.capture_from.get().strip() and self.capture_to.get().strip():
                df=_parse_user_date(self.capture_from.get(),'data inicial'); dt=_parse_user_date(self.capture_to.get(),'data final')
            else: self._finish_sat_audit_error('Informe o período da auditoria antes de importar o Excel.'); return
        if df and dt and df>dt: self._finish_sat_audit_error('A data inicial não pode ser maior que a data final.'); return
        self.audit_from.set(_format_user_date(df)); self.audit_to.set(_format_user_date(dt)); self.audit_period_label.config(text=f'{self.audit_from.get()} até {self.audit_to.get()}')
        def worker():
            try:
                grouped={fam:[] for fam in selected}; headers_by_family={fam:set() for fam in selected}; file_family={}; valid_files=[]
                for idx,path in enumerate(paths,1):
                    if self.audit_cancel_event.is_set(): raise AuditCancelled('Auditoria cancelada pelo usuário.')
                    self.after(0,lambda i=idx,n=len(paths):self.audit_progress_label.config(text=f'Lendo arquivo {i} de {n}...',fg=BLUE))
                    parsed=_xlsx_read_values(path); rows=parsed['rows']; headers=parsed['headers']
                    if not rows: raise ValueError(f'O arquivo "{Path(path).name}" não possui documentos utilizáveis do SAT.')
                    detected={_audit_row_detected_family(row) for row in rows if _audit_row_detected_family(row)}
                    if not detected: raise ValueError(f'Não foi possível identificar com segurança o tipo documental do arquivo "{Path(path).name}".')
                    if len(detected)>1:
                        labs=' + '.join(SUPPORTED_FAMILIES.get(f,f) for f in sorted(detected))
                        raise ValueError(f'O arquivo "{Path(path).name}" mistura tipos de documento ({labs}). Separe os arquivos do SAT por tipo documental.')
                    fam=next(iter(detected)); file_family[str(path)]=fam
                    if fam not in selected:
                        raise ValueError(f'O arquivo "{Path(path).name}" parece conter {SUPPORTED_FAMILIES.get(fam,fam)}, mas esse tipo não está selecionado para a auditoria.')
                    grouped[fam].extend(rows); headers_by_family[fam].update(headers); valid_files.append(str(path))
                missing=[SUPPORTED_FAMILIES[f] for f in selected if not grouped[f]]
                if missing: raise ValueError('Nenhum documento foi encontrado para o(s) tipo(s) selecionado(s): ' + ', '.join(missing) + '.')
                results={}
                for fam in selected:
                    if self.audit_cancel_event.is_set(): raise AuditCancelled('Auditoria cancelada pelo usuário.')
                    seen=set(); sat_rows=[]
                    for r in grouped[fam]:
                        k=_audit_key(r)
                        if k in seen: continue
                        seen.add(k); sat_rows.append(r)
                    self.after(0,lambda fam=fam,n=len(sat_rows):self.audit_progress_label.config(text=f'Conferindo {n} documento(s) de {SUPPORTED_FAMILIES[fam]} com os XMLs da Central...',fg=BLUE))
                    result=audit_sat_excel_against_xml(cnpj,sat_rows,df,dt,family=fam)
                    fam_files=[p for p in valid_files if file_family.get(p)==fam]
                    result['family']=fam; result['family_label']=SUPPORTED_FAMILIES[fam]; result['source_file']='Excel SAT (importado manualmente)'; result['source_files']=fam_files; result['headers']=sorted(headers_by_family[fam]); result['ai_analysis']=analyze_audit_result(result,db_get_company_name(cnpj) or '',df,dt)
                    results[fam]=result
                combined=_combine_audit_results(results,selected,valid_files,df,dt)
                combined['ai_analysis']=analyze_audit_result(combined,db_get_company_name(cnpj) or '',df,dt)
                self.after(0,lambda:self.audit_progress_label.config(text='Montando resultado consolidado e análise do Exato IA...',fg=BLUE))
                self.after(0,lambda r=combined,rs=results:self._safe_finish_sat_audit(r,{'rows':[],'files':valid_files,'download_dir':'','subresults':rs}))
            except AuditCancelled as exc: self.after(0,lambda e=str(exc):self._finish_sat_audit_cancelled(e))
            except Exception as exc: self.after(0,lambda e=str(exc):self._finish_sat_audit_error(e))
        threading.Thread(target=worker,daemon=True).start()

    def _generate_audit_pdf_action(self):
        result=getattr(self,'last_audit_result',None)
        if not result:
            messagebox.showinfo('Auditoria','Conclua a importação e a comparação antes de gerar o PDF.'); return
        cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
        company_name=db_get_company_name(cnpj) or 'Empresa não identificada'
        stamp=datetime.now().strftime('%Y%m%d_%H%M%S')
        path=filedialog.asksaveasfilename(title='Salvar relatório da Auditoria Fiscal',defaultextension='.pdf',initialfile=f'Auditoria_Fiscal_{cnpj or "empresa"}_{stamp}.pdf',filetypes=[('PDF','*.pdf')])
        if not path: return
        try:
            generate_audit_pdf(result,path,company_name,cnpj,result.get('period_start',''),result.get('period_end',''),result.get('source_files') or getattr(self,'audit_source_files',[]) or [])
            if os.name=='nt': os.startfile(path)
            elif sys.platform=='darwin': subprocess.Popen(['open',path])
            else: subprocess.Popen(['xdg-open',path])
            self.set_status(f'Relatório PDF da auditoria gerado: {Path(path).name}')
            messagebox.showinfo('PDF gerado','Relatório da Auditoria Fiscal criado com sucesso.')
        except Exception as exc:
            messagebox.showerror('Não foi possível gerar o PDF da auditoria',str(exc))

    def _find_reusable_audit_source_files(self, cnpj, period_start, period_end, selected):
        """Find previously exported SAT Excel files stored by the automatic SAT fetch.

        Only files recorded for the same company/period and covering all selected
        families are considered. Manual files outside SAT_AUDITORIA remain explicit
        user choices and are never guessed.
        """
        selected=set(selected or [])
        if not selected or not cnpj: return []
        try:
            for entry in _audit_history_load():
                if re.sub(r'\D','',str(entry.get('cnpj') or '')) != re.sub(r'\D','',str(cnpj)):
                    continue
                if str(entry.get('period_start') or '')[:10] != str(period_start or '')[:10] or str(entry.get('period_end') or '')[:10] != str(period_end or '')[:10]:
                    continue
                entry_selected=set(entry.get('selected_families') or [])
                if not selected.issubset(entry_selected):
                    continue
                names=[str(Path(x).name) for x in (entry.get('source_paths') or []) if str(x).strip()]
                if not names:
                    names=[str(Path(x).name) for x in (entry.get('source_files') or []) if str(x).strip()]
                if not names:
                    continue
                found=[]
                root=WORK_DIR/'SAT_AUDITORIA'
                for name in names:
                    matches=list(root.rglob(name)) if root.exists() else []
                    if matches: found.append(str(sorted(matches,key=lambda p:p.stat().st_mtime,reverse=True)[0]))
                if found:
                    # Validate that every selected family has at least one source.
                    detected=set()
                    for p in found:
                        try:
                            rows=_xlsx_read_values(p)['rows']
                            detected.update(_audit_row_detected_family(r) for r in rows if _audit_row_detected_family(r))
                        except Exception:
                            continue
                    if selected.issubset(detected):
                        return sorted(dict.fromkeys(found))
        except Exception:
            pass
        return []

    def _run_sat_audit(self):
        try:
            cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
            selected=self._audit_selected_families()
            df=_parse_user_date(self.audit_from.get(),'data inicial') if getattr(self,'audit_from',None) and self.audit_from.get().strip() else ''
            dt=_parse_user_date(self.audit_to.get(),'data final') if getattr(self,'audit_to',None) and self.audit_to.get().strip() else ''
            reusable=self._find_reusable_audit_source_files(cnpj,df,dt,selected)
        except Exception:
            reusable=[]
        if reusable:
            self._import_sat_excel_files(reusable)
        else:
            self._import_sat_excel_files()

    def _run_audit(self):
        self._import_sat_excel_files()



