    def _selected_user_id(self):
        if not hasattr(self,'users_tree'): return None
        sel=self.users_tree.selection()
        if not sel: return None
        try: return int(self.users_tree.item(sel[0],'values')[0])
        except Exception: return None

    def _on_user_selection(self,event=None):
        uid=self._selected_user_id(); user=db_auth_get_user_by_id(uid) if uid else None
        if not user: return
        is_self=int(user['id'])==int(self.current_user.get('id') or -1); status=str(user.get('status') or '')
        self.user_block_btn.config(state='normal' if status=='active' and not is_self else 'disabled')
        self.user_activate_btn.config(state='normal' if status=='blocked' else 'disabled'); self.user_reset_btn.config(state='normal')

    def _user_set_status(self,status):
        uid=self._selected_user_id()
        if not uid: return
        target=db_auth_get_user_by_id(uid)
        if not target: return
        label=AUTH_STATUSES.get(status,status)
        if not messagebox.askyesno('Confirmar alteração',f'Alterar {target["email"]} para “{label}”?'): return
        try:
            db_auth_set_status(uid,status,self.current_user); self._refresh_users(); messagebox.showinfo('Usuário atualizado',f'Usuário atualizado para: {label}.')
        except Exception as exc: messagebox.showerror('Não foi possível atualizar o usuário',str(exc))

    def _user_reset_password(self,target_id=None,request_id=None,parent=None):
        uid=int(target_id) if target_id is not None else self._selected_user_id()
        if not uid: return
        target=db_auth_get_user_by_id(uid)
        if not target: return
        dialog=tk.Toplevel(parent or self); dialog.title('Redefinir senha'); dialog.transient(parent or self); dialog.grab_set(); dialog.configure(bg=BG); dialog.geometry('430x270')
        tk.Label(dialog,text='REDEFINIR SENHA',bg=BG,fg=TEXT,font=('Segoe UI Semibold',14)).pack(anchor='w',padx=22,pady=(18,2)); tk.Label(dialog,text=f"{target['name']} • {target['email']}",bg=BG,fg=MUTED,font=('Segoe UI',8)).pack(anchor='w',padx=22,pady=(0,12))
        form=exato_ui.ModernCard(dialog, fill=WHITE, border=BORDER); form.pack(fill='x',padx=22)
        tk.Label(form,text='Nova senha',bg=WHITE,fg=TEXT,font=('Segoe UI',8)).pack(anchor='w',padx=12,pady=(10,2)); pw=tk.Entry(form,show='•',font=('Segoe UI',10),relief='flat',bd=0); pw.pack(fill='x',padx=12,pady=(0,6))
        tk.Label(form,text='Confirmar senha',bg=WHITE,fg=TEXT,font=('Segoe UI',8)).pack(anchor='w',padx=12,pady=(3,2)); pw2=tk.Entry(form,show='•',font=('Segoe UI',10),relief='flat',bd=0); pw2.pack(fill='x',padx=12,pady=(0,6)); tk.Label(form,text=f'Mínimo de {AUTH_MIN_PASSWORD_LENGTH} caracteres.',bg=WHITE,fg=MUTED,font=('Segoe UI',7)).pack(anchor='w',padx=12,pady=(0,8))
        def save():
            if pw.get()!=pw2.get(): messagebox.showerror('Senha','As senhas não conferem.',parent=dialog); return
            try:
                db_auth_set_password(uid,pw.get()); db_auth_log(self.current_user,'SENHA_REDEFINIDA',target['email'])
                if request_id is not None: db_auth_resolve_reset_request(request_id,self.current_user,'resolved')
                dialog.destroy(); self._refresh_users(); messagebox.showinfo('Senha redefinida','A nova senha foi gravada com segurança.' + ('\n\nA solicitação de recuperação foi marcada como atendida.' if request_id is not None else ''),parent=parent or self)
                if request_id is not None and parent is not None:
                    try: parent.destroy()
                    except Exception: pass
            except Exception as exc: messagebox.showerror('Senha',str(exc),parent=dialog)
        bar=tk.Frame(dialog,bg=BG); bar.pack(fill='x',padx=22,pady=12); ttk.Button(bar,text='CANCELAR',style='Secondary.TButton',command=dialog.destroy).pack(side='right'); ttk.Button(bar,text='SALVAR NOVA SENHA',style='Primary.TButton',command=save).pack(side='right',padx=(0,8)); pw.focus_set()

    def _show_password_reset_requests(self):
        if not _auth_is_admin(self.current_user):
            messagebox.showwarning('Acesso restrito','As solicitações de senha estão disponíveis apenas para administradores.')
            return
        dialog=tk.Toplevel(self); dialog.title('Solicitações de senha'); dialog.transient(self); dialog.geometry('820x470'); dialog.configure(bg=BG)
        tk.Label(dialog,text='SOLICITAÇÕES DE SENHA',bg=BG,fg=TEXT,font=('Segoe UI Semibold',15)).pack(anchor='w',padx=20,pady=(18,2)); tk.Label(dialog,text='Usuários que pediram ajuda pelo botão “Esqueci minha senha”.',bg=BG,fg=MUTED,font=('Segoe UI',9)).pack(anchor='w',padx=20,pady=(0,10))
        wrap=exato_ui.ModernCard(dialog, fill=WHITE, border=BORDER); wrap.pack(fill='both',expand=True,padx=20,pady=(0,10))
        tv=ttk.Treeview(wrap,columns=('id','date','name','email','status'),show='headings',selectmode='browse')
        for c,h,w in [('id','ID',50),('date','Solicitado em',150),('name','Usuário',180),('email','E-mail',260),('status','Situação',100)]: tv.heading(c,text=h); tv.column(c,width=w,anchor='w')
        sb=ttk.Scrollbar(wrap,orient='vertical',command=tv.yview); tv.configure(yscrollcommand=sb.set); tv.pack(side='left',fill='both',expand=True); sb.pack(side='right',fill='y')
        def refresh():
            for iid in tv.get_children(): tv.delete(iid)
            for r in db_auth_list_reset_requests(True,200): tv.insert('', 'end', iid=str(r['id']), values=(r['id'],str(r.get('requested_at') or '').replace('T',' ')[:16],r.get('name') or '—',r.get('user_email') or '—',AUTH_RESET_STATUSES.get(r.get('status'),r.get('status') or '—')) )
            self._refresh_users()
        def selected():
            sel=tv.selection();
            return int(sel[0]) if sel else None
        def attend():
            rid=selected()
            if not rid: messagebox.showinfo('Solicitação','Selecione uma solicitação.',parent=dialog); return
            req=next((r for r in db_auth_list_reset_requests(True,200) if int(r['id'])==rid),None)
            if not req: refresh(); return
            target=db_auth_get_user_by_id(req['user_id'])
            if not target: messagebox.showerror('Solicitação','O usuário desta solicitação não foi localizado.',parent=dialog); return
            self._user_reset_password(target_id=target['id'], request_id=rid, parent=dialog)
        def cancel_request():
            rid=selected()
            if not rid: return
            if not messagebox.askyesno('Cancelar solicitação','Cancelar esta solicitação de redefinição?',parent=dialog): return
            try: db_auth_resolve_reset_request(rid,self.current_user,'cancelled'); refresh()
            except Exception as exc: messagebox.showerror('Solicitação',str(exc),parent=dialog)
        bar=tk.Frame(dialog,bg=BG); bar.pack(fill='x',padx=20,pady=(0,12)); ttk.Button(bar,text='ATUALIZAR',style='Secondary.TButton',command=refresh).pack(side='left'); ttk.Button(bar,text='REDEFINIR SENHA DO USUÁRIO',style='Primary.TButton',command=attend).pack(side='left',padx=(8,0)); ttk.Button(bar,text='CANCELAR SOLICITAÇÃO',style='Secondary.TButton',command=cancel_request).pack(side='left',padx=(8,0)); ttk.Button(bar,text='FECHAR',style='Secondary.TButton',command=dialog.destroy).pack(side='right')
        refresh(); tv.focus_set()


