        wrap=exato_ui.ModernCard(dialog, fill=WHITE, border=BORDER); wrap.pack(fill='both',expand=True,padx=20,pady=(0,12)); tv=ttk.Treeview(wrap,columns=('time','user','action','details'),show='headings')
        for c,h,w in [('time','Data/Hora',150),('user','Usuário',220),('action','Ação',170),('details','Detalhes',300)]: tv.heading(c,text=h); tv.column(c,width=w,anchor='w')
