    def _refresh_users(self):
        if not hasattr(self,'users_tree'): return
        users=db_auth_list_users()
        for iid in self.users_tree.get_children(): self.users_tree.delete(iid)
        counts={'total':len(users),'active':0,'blocked':0}
        for user in users:
            status=str(user.get('status') or ''); counts[status]=counts.get(status,0)+1
            created=_format_user_date(str(user.get('created_at') or '')[:10]); last=str(user.get('last_login_at') or '').replace('T',' ')[:16] or '—'
            self.users_tree.insert('', 'end', values=(user['id'],user['name'],user['email'],user['role_label'],user['status_label'],created,last))
        counts['reset']=db_auth_pending_reset_count()
        for key,label in self.user_summary_labels.items(): label.config(text=str(counts.get(key,0)))
        self.user_block_btn.config(state='disabled'); self.user_activate_btn.config(state='disabled'); self.user_reset_btn.config(state='disabled')
        if hasattr(self,'user_reset_requests_btn'): self.user_reset_requests_btn.config(text=f'SOLICITAÇÕES DE SENHA ({counts["reset"]})')

    def _central_status_schedule(self):
        try: self._central_status_tick()
        except Exception: pass
        try: self._central_status_job=self.after(10000,self._central_status_schedule)
        except Exception: self._central_status_job=None

    def _central_status_tick(self):
        if getattr(self,'_central_status_busy',False): return
        self._central_status_busy=True
        def worker():
            try: result=central_client.local_central_health()
            except Exception as exc: result={'ok':False,'state':'offline','label':'Central indisponível','detail':str(exc)}
            try: self.after(0,lambda:self._central_status_finish(result))
            except Exception: pass
        threading.Thread(target=worker,daemon=True).start()

    def _central_status_finish(self,result):
        self._central_status_busy=False
        self._central_health_cache=dict(result or {})
        state=str(result.get('state') or 'offline')
        if hasattr(self,'header_central'):
            if state in ('online','server'):
                self.header_central.config(text='● Central online' if state=='online' else '● Servidor Exato',fg=GREEN)
            elif state=='local':
                self.header_central.config(text='● Central local',fg=MUTED)
            else:
                self.header_central.config(text='● Central offline',fg=RED)
        try: self._update_central_health_ui(result)
        except Exception: pass

    def _update_central_health_ui(self,result):
        if not hasattr(self,'central_health_labels'): return
        state=str(result.get('state') or 'offline')
        label=str(result.get('label') or '—')
        role=str(result.get('role') or '')
        pending=result.get('pending') or {}
        pending_total=int(pending.get('total') or 0)
        if state=='server':
            conn_text='Servidor Exato online'
            sync_text='Fonte central'
        elif state=='online':
            conn_text='Central online'
            sync_text=f"Tudo sincronizado" if pending_total==0 else f"{pending_total} pendência(s)"
        elif state=='local':
            conn_text='Modo local'
            sync_text='Compartilhamento desativado'
        else:
            conn_text='Central offline'
            sync_text=(f"{pending_total} pendência(s) locais" if pending_total else 'Sem sincronização')
        self.central_health_labels['connection'].config(text=conn_text,fg=GREEN if state in ('online','server') else (MUTED if state=='local' else RED))
        self.central_health_labels['sync'].config(text=sync_text,fg=GREEN if pending_total==0 and state in ('online','server') else ORANGE)
        auto=result.get('server_autostart') or {}
        auto_txt='Ativo no Windows' if auto.get('registered') else ('Não registrado' if auto.get('supported') else 'Não aplicável')
        self.central_health_labels['autostart'].config(text=auto_txt,fg=GREEN if auto.get('registered') else (MUTED if not auto.get('supported') else ORANGE))
        bat=str(result.get('last_automatic_backup_at') or '')
        due=bool(result.get('automatic_due'))
        if bat:
            try: bat=datetime.fromisoformat(bat).strftime('%d/%m/%Y %H:%M')
            except Exception: pass
        elif result.get('last_backup_at'):
            try: bat=datetime.fromisoformat(str(result.get('last_backup_at'))).strftime('%d/%m/%Y %H:%M')
            except Exception: bat=str(result.get('last_backup_at'))
        else:
            bat='Ainda não realizado'
        self.central_health_labels['backup'].config(text=('Pendente • '+bat) if due else bat,fg=ORANGE if due else GREEN)

    def _central_sync_schedule(self):
        try: self._central_sync_tick()
        except Exception: pass
        try: self._central_sync_job=self.after(30000,self._central_sync_schedule)
        except Exception: self._central_sync_job=None

    def _central_sync_tick(self):
        if getattr(self,'_central_sync_busy',False) or not central_client.is_client_enabled(): return
        self._central_sync_busy=True
        def worker():
            try: result=central_client.sync_now(max_seconds=12)
            except Exception as exc: result={'ok':False,'message':str(exc),'pushed':0,'pulled':0}
            try: self.after(0,lambda:self._central_sync_finish(result))
            except Exception: pass
        threading.Thread(target=worker,daemon=True).start()

    def _central_sync_finish(self,result):
        self._central_sync_busy=False
        try:
            if result.get('ok') and (result.get('pushed') or result.get('pulled')):
                self.set_status(str(result.get('message') or 'Central sincronizada.'))
                if getattr(self,'current_screen','')=='documents': self._refresh_documents_view()
            elif not result.get('ok') and result.get('message'):
                self.set_status('Central compartilhada indisponível no momento.')
        except Exception: pass

    def _open_central_config(self):
        _open_central_config_dialog(self, allow_server=True)
        try: self._refresh_maintenance()
        except Exception: pass

