    def _refresh_maintenance(self):
        if not hasattr(self,'maint_cards'): return
        backups=_list_recent_backups(1); newer=_find_newer_local_versions()
        try: self._central_status_tick()
        except Exception: pass
        self.maint_cards['version'].config(text=APP_VERSION)
        self.maint_cards['data'].config(text='Protegidos fora da pasta da versão')
        self.maint_cards['backup'].config(text=_format_user_date(datetime.fromtimestamp(backups[0].stat().st_mtime).strftime('%Y-%m-%d')) if backups else 'Ainda não realizado')
        self.maint_cards['updates'].config(text=str(len(newer)))
        stats=db_local_archive_stats('')
        size_mb=stats['bytes']/1024/1024
        self.maint_data_label.config(text=f'Dados: {APP_DATA_DIR}\nBanco: {DB_PATH.name}\nBackup: {BACKUP_DIR}\nArquivo Fiscal Local: {stats["documents"]:,} documento(s) • {size_mb:.1f} MB • {stats["exported"]:,} exportado(s) • {stats["not_exported"]:,} não exportado(s)'.replace(',', '.')+'\nAs credenciais e configurações permanecem fora da pasta da versão para reduzir risco de perda durante atualizações.')
        try:
            if hasattr(self,'maint_health_labels'):
                last=str(getattr(self,'last_response_info',{}) or {})
                cstat=str((getattr(self,'last_response_info',{}) or {}).get('cStat') or (getattr(self,'last_response_info',{}) or {}).get('cstat') or '—')
                for fam_key, fam_label in (('nfe','NF-e'),('nfce','NFC-e'),('cte','CT-e')):
                    rr={'nfe':self._ia_event_context.get('last_significant_type') if fam_key=='nfe' else None}
                    txt='Operacional' if not getattr(self,'sync_running',False) else 'Em processamento'
                    self.maint_health_labels[fam_key].config(text=txt,fg=BLUE if getattr(self,'sync_running',False) else GREEN)
                self.maint_health_labels['cert'].config(text='Selecionado' if self.selected else 'Não selecionado',fg=GREEN if self.selected else ORANGE)
                self.maint_health_labels['sefa'].config(text=f'Código {cstat}' if cstat!='—' else 'Sem retorno recente',fg=BLUE if cstat!='—' else MUTED)
        except Exception:
            pass
        if newer:
            lines=['Foi encontrada uma versão mais recente já extraída neste computador:']
            for ver,path,marker in newer[:5]: lines.append(f'• V{ver:03d} — {path.name}')
            lines.append('\nPara uma atualização segura: faça backup, confirme a nova pasta e só então abra a nova versão. O Central não sobrescreve a instalação atual automaticamente.')
            self.maint_versions.config(text='\n'.join(lines),fg=TEXT)
        else:
            self.maint_versions.config(text='Nenhuma versão mais recente foi encontrada nesta pasta.\n\nQuando uma nova versão estiver disponível, o Central poderá detectá-la aqui sem alterar automaticamente a instalação atual.',fg=MUTED)

    def _maintenance_backup(self):
        try:
            p=create_data_backup(reason='manual')
            self.set_status('Backup dos dados realizado com sucesso.')
            messagebox.showinfo('Backup realizado',f'Backup criado com sucesso.\n\n{p}')
            self._refresh_maintenance()
        except Exception as exc:
            messagebox.showerror('Não foi possível realizar o backup',str(exc))

    def _maintenance_restore_archive(self):
        path=filedialog.askopenfilename(title='Selecione um backup do Exato Central Fiscal',initialdir=str(BACKUP_DIR) if BACKUP_DIR.exists() else str(APP_DATA_DIR),filetypes=[('Backup do Exato','Exato_Backup_*.zip'),('ZIP','*.zip'),('Todos os arquivos','*.*')])
        if not path: return
        if not messagebox.askyesno('Restaurar Arquivo Fiscal','Isso vai substituir o Arquivo Fiscal Local atual pelo banco existente no backup. Antes da troca, a Central fará um backup de segurança do estado atual.\n\nContinuar?'):
            return
        try:
            restore_local_archive_backup(path)
            messagebox.showinfo('Arquivo Fiscal restaurado','A restauração foi concluída com verificação de integridade.\n\nA Central será reiniciada para carregar o Arquivo Fiscal restaurado.')
            try: self.destroy()
            finally:
                args=[sys.executable]+sys.argv if not getattr(sys,'frozen',False) else [sys.executable]+sys.argv[1:]
                subprocess.Popen(args,cwd=str(APP_DIR))
                os._exit(0)
        except Exception as exc:
            messagebox.showerror('Não foi possível restaurar',str(exc))

    def _maintenance_open_data(self):
        APP_DATA_DIR.mkdir(parents=True,exist_ok=True)
        try:
            if os.name=='nt': os.startfile(str(APP_DATA_DIR))
            elif sys.platform=='darwin': subprocess.Popen(['open',str(APP_DATA_DIR)])
            else: subprocess.Popen(['xdg-open',str(APP_DATA_DIR)])
        except Exception as exc:
            messagebox.showerror('Não foi possível abrir a pasta',str(exc))

    def _maintenance_diagnostics(self):
        cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
        checks=_run_system_diagnostics(cnpj)
        lines=['DIAGNÓSTICO DO SISTEMA', '']
        for label,value,ok in checks:
            lines.append(('✓ ' if ok else '⚠ ')+f'{label}: {value}')
        messagebox.showinfo('Diagnóstico do sistema','\n'.join(lines))

    def _maintenance_nfe_diagnostics(self):
        """Show local NF-e diagnostic state without making a fiscal request."""
        cnpj=re.sub(r'\D','',self.cnpj_var.get().strip()) if hasattr(self,'cnpj_var') else ''
        info=_nfe_runtime_diagnostic_summary(cnpj)
        lines=['DIAGNÓSTICO NF-e','',f"CNPJ: {info['cnpj'] or 'não informado'}",f"Último código de retorno: {info['last_cstat']}",f"Interpretação: {info['last_cstat_message']}",f"Última consulta: {info['last_query_at']}",f"Último resultado: {info['last_reason']}",f"Último ator: {info['actor']}  •  Próximo: {info['next_actor']}",f"Cooldown registrado: {info['cooldown_until']}",'','Este painel não executa uma nova consulta e não altera checkpoint/NSU.',f"Diagnóstico bruto mais recente: {info['diagnostic_path']}"]
        messagebox.showinfo('Diagnóstico NF-e','\n'.join(lines))

    def _show_pending(self):
        if getattr(self,'pending_frame',None) is None:
            self.pending_frame=tk.Frame(self.page_host,bg=BG); self._build_pending_contents()
        self._show_frame(self.pending_frame,'pending'); self._refresh_pending()

